// ---------- AV-81: dual-signed escrow split ----------
//
// `split_escrow` re-homes a funded escrow's remaining lockup into N
// fresh `Funded` child escrows by dual-signed governance, moving the
// parent `Funded -> Split` (terminal).
#[cfg(test)]
mod split_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32]; // initializer
    const BOB: [u8; 32] = [0xBB; 32]; // taker
    const MALLORY: [u8; 32] = [0xCC; 32]; // stranger
    const ARBITER: [u8; 32] = [0xA8; 32];
    const A1: [u8; 32] = [0xA1; 32];
    const A2: [u8; 32] = [0xA2; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;

    fn funded_escrow() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    #[test]
    fn split_moves_funded_escrow_to_split_and_births_funded_children() {
        let mut e = funded_escrow();
        let children = e
            .split_escrow(
                ALICE,
                BOB,
                &[600_000, 400_000],
                SplitConfig::default(),
                EXPIRES_AT,
            )
            .unwrap();
        assert_eq!(e.state(), EscrowState::Split);
        assert_eq!(children.len(), 2);
        assert_eq!(children[0].amount(), 600_000);
        assert_eq!(children[1].amount(), 400_000);
        for c in &children {
            assert_eq!(c.state(), EscrowState::Funded);
            assert_eq!(c.initializer(), ALICE);
            assert_eq!(c.taker(), BOB);
            assert_eq!(c.expires_at(), EXPIRES_AT, "the deal deadline does not move");
            assert_eq!(c.released_amount(), 0, "children are born whole");
            assert_eq!(c.remaining_amount(), c.amount());
        }
        // Conservation, pinned: Σ(children) == pre-split remaining, and
        // the parent's audit counters are preserved untouched.
        let total: u64 = children.iter().map(|c| c.amount()).sum();
        assert_eq!(total, 1_000_000);
        assert_eq!(e.amount(), 1_000_000);
        assert_eq!(e.released_amount(), 0);
        assert_eq!(e.remaining_amount(), 1_000_000);
    }

    #[test]
    fn split_after_partial_release_divides_the_remaining() {
        let mut e = funded_escrow();
        e.release(ALICE, EXPIRES_AT, 200_000, None, BOB).unwrap();
        assert_eq!(e.remaining_amount(), 800_000);
        let children = e
            .split_escrow(
                ALICE,
                BOB,
                &[500_000, 300_000],
                SplitConfig::default(),
                EXPIRES_AT,
            )
            .unwrap();
        assert_eq!(e.state(), EscrowState::Split);
        // The pinned conservation invariant: Σ(children) + released ==
        // amount — the split divides what is left, never the original.
        let total: u128 = children.iter().map(|c| c.amount() as u128).sum();
        assert_eq!(total, 800_000);
        assert_eq!(total + e.released_amount() as u128, e.amount() as u128);
    }

    #[test]
    fn split_rejects_single_party_and_strangers() {
        // One party alone, or a stranger pair, is Unauthorized — and the
        // parent stays Funded.
        for (init, taker) in [
            (MALLORY, MALLORY),
            (ALICE, MALLORY),
            (MALLORY, BOB),
            (BOB, BOB),
        ] {
            let mut e = funded_escrow();
            assert_eq!(
                e.split_escrow(init, taker, &[1_000_000], SplitConfig::default(), EXPIRES_AT),
                Err(EscrowError::Unauthorized),
                "init={init:?} taker={taker:?}"
            );
            assert_eq!(e.state(), EscrowState::Funded, "state must be unchanged");
        }
    }

    #[test]
    fn split_rejects_disputed_and_terminal_states() {
        // Disputed: arbitration in flight adjudicates the locked funds.
        let mut disputed = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap();
        disputed.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        disputed.escalate(ALICE, EXPIRES_AT - 1, disputed.remaining_amount(), None, None, 0).unwrap();
        assert_eq!(
            disputed.split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidStateTransition)
        );
        assert_eq!(disputed.state(), EscrowState::Disputed);
        // Terminal states: a split parent cannot be split again, and
        // settled / released / cancelled / closed vaults have no live
        // lockup to divide.
        for state in [
            EscrowState::Released,
            EscrowState::Cancelled,
            EscrowState::Settled,
            EscrowState::Closed,
        ] {
            let mut e = funded_escrow();
            match state {
                EscrowState::Released => {
                    e.release(ALICE, EXPIRES_AT, 1_000_000, None, BOB).unwrap();
                }
                EscrowState::Cancelled => {
                    e.cancel(ALICE, None, ALICE, 0).unwrap();
                }
                EscrowState::Settled => {
                    let mut d = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
                        .unwrap()
                        .with_arbiter(ARBITER)
                        .unwrap();
                    d.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
                    d.escalate(ALICE, EXPIRES_AT - 1, d.remaining_amount(), None, None, 0).unwrap();
                    d.resolve(ARBITER, 0, EXPIRES_AT - 1, None, None, BOB).unwrap();
                    e = d;
                }
                _ => {
                    e.cancel(ALICE, None, ALICE, 0).unwrap();
                    e.close_vault(ALICE).unwrap();
                }
            }
            assert_eq!(e.state(), state);
            assert_eq!(
                e.split_escrow(ALICE, BOB, &[e.remaining_amount()], SplitConfig::default(), EXPIRES_AT),
                Err(EscrowError::InvalidStateTransition),
                "from {state:?}"
            );
        }
        // A split parent cannot be split again.
        let mut e = funded_escrow();
        e.split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn split_rejects_bad_amount_tables() {
        // Empty table.
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidSplit)
        );
        // Zero entry.
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[0, 1_000_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidSplit)
        );
        // Under-covering the remaining lockup.
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[600_000, 300_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidSplit)
        );
        // Over-covering the remaining lockup.
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[600_000, 500_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidSplit)
        );
        // More children than the batching ceiling.
        let mut e = funded_escrow();
        let too_many = [62_500u64; MAX_SPLIT_CHILDREN + 1];
        assert_eq!(
            e.split_escrow(ALICE, BOB, &too_many, SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::InvalidSplit)
        );
        // A failed split never moves the parent.
        assert_eq!(e.state(), EscrowState::Funded);
        // The ceiling itself is usable: 16 children covering the lockup.
        let mut e = funded_escrow();
        let maxed = [62_500u64; MAX_SPLIT_CHILDREN];
        let children = e
            .split_escrow(ALICE, BOB, &maxed, SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(children.len(), MAX_SPLIT_CHILDREN);
        assert_eq!(e.state(), EscrowState::Split);
        // The degenerate single-child split is valid: Σ == remaining.
        let mut e = funded_escrow();
        let children = e
            .split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(children.len(), 1);
        assert_eq!(e.state(), EscrowState::Split);
    }

    #[test]
    fn invalid_split_error_code_is_142() {
        let mut e = funded_escrow();
        let err = e
            .split_escrow(ALICE, BOB, &[1], SplitConfig::default(), EXPIRES_AT)
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSplit);
        assert_eq!(err.code(), 142);
    }

    #[test]
    fn split_child_ids_derive_deterministically() {
        let parent = [0x11; 32];
        let a = derive_split_child_id(&parent, 0);
        let b = derive_split_child_id(&parent, 0);
        assert_eq!(a, b, "derivation is deterministic");
        // The exact preimage: H(parent_id || index_le).
        let mut preimage = [0u8; 40];
        preimage[..32].copy_from_slice(&parent);
        preimage[32..].copy_from_slice(&0u64.to_le_bytes());
        assert_eq!(a, sha256(&preimage), "preimage pinned byte-exact");
        // Siblings never collide; different parents never collide.
        assert_ne!(a, derive_split_child_id(&parent, 1));
        assert_ne!(a, derive_split_child_id(&[0x22; 32], 0));
        assert_ne!(
            derive_split_child_id(&parent, 1),
            derive_split_child_id(&parent, 2)
        );
    }

    #[test]
    fn split_default_config_inherits_nothing() {
        // A fully-configured parent, split with the default (inert)
        // config: children are born plain — no silent inheritance.
        let policy = QuorumPolicy::new(&[A1, A2], &[1, 1], 2).unwrap();
        let schedule = VestingSchedule::new(T0, T0 + 1_000).unwrap();
        let plan = MilestonePlan::new(&[600_000, 400_000]).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_quorum(policy)
            .unwrap()
            .with_vesting(schedule)
            .unwrap()
            .with_milestones(plan)
            .unwrap()
            .with_dual_sig()
            .unwrap();
        e.activate(ALICE).unwrap();
        e.activate(BOB).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let children = e
            .split_escrow(ALICE, BOB, &[600_000, 400_000], SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(e.state(), EscrowState::Split);
        for c in &children {
            assert_eq!(c.state(), EscrowState::Funded);
            assert_eq!(c.quorum(), None, "quorum not inherited by default");
            assert_eq!(c.vesting_schedule(), None, "vesting not inherited by default");
            assert_eq!(c.milestone_plan(), None, "milestones not inherited by default");
            assert!(!c.dual_sig_required(), "dual_sig not inherited by default");
        }
    }

    #[test]
    fn split_explicit_config_inherits_onto_every_child() {
        let policy = QuorumPolicy::new(&[A1, A2], &[1, 1], 2).unwrap();
        let schedule = VestingSchedule::new(T0, T0 + 1_000).unwrap();
        // Per-child plans, each summing to its child's amount — a
        // parent-sized plan could never be copied verbatim.
        let plan0 = MilestonePlan::new(&[400_000, 200_000]).unwrap();
        let plan1 = MilestonePlan::new(&[400_000]).unwrap();
        let plans = [plan0, plan1];
        let config = SplitConfig {
            vesting: Some(schedule),
            vesting_curve: None,
            quorum: Some(policy),
            dual_sig: true,
            milestones: Some(&plans),
        };
        let mut e = funded_escrow();
        let children = e
            .split_escrow(ALICE, BOB, &[600_000, 400_000], config, EXPIRES_AT)
            .unwrap();
        assert_eq!(children.len(), 2);
        for c in &children {
            assert_eq!(c.vesting_schedule(), Some(schedule));
            assert_eq!(c.quorum(), Some(policy));
            assert!(c.dual_sig_required());
            assert!(c.initializer_activated() && c.taker_activated());
            assert_eq!(c.state(), EscrowState::Funded);
        }
        assert_eq!(children[0].milestone_plan(), Some(plan0));
        assert_eq!(children[1].milestone_plan(), Some(plan1));
    }

    #[test]
    fn split_rejects_milestone_plan_length_mismatch() {
        let plan = MilestonePlan::new(&[600_000, 400_000]).unwrap();
        let plans = [plan];
        let config = SplitConfig {
            milestones: Some(&plans),
            ..SplitConfig::default()
        };
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[600_000, 400_000], config, EXPIRES_AT),
            Err(EscrowError::InvalidSplit),
            "one plan for two children"
        );
        assert_eq!(e.state(), EscrowState::Funded, "parent untouched");
    }

    #[test]
    fn split_child_milestone_plan_must_sum_to_child_amount() {
        // A parent-sized plan on a 600k child: the builder's own
        // validation rejects it (InvalidMilestones), and the parent is
        // left untouched — no half-split.
        let plan = MilestonePlan::new(&[600_000, 400_000]).unwrap();
        let plans = [plan, plan];
        let config = SplitConfig {
            milestones: Some(&plans),
            ..SplitConfig::default()
        };
        let mut e = funded_escrow();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[600_000, 400_000], config, EXPIRES_AT),
            Err(EscrowError::InvalidMilestones)
        );
        assert_eq!(
            e.state(),
            EscrowState::Funded,
            "failed child build must not half-split the parent"
        );
    }

    #[test]
    fn split_self_escrow_authorizes_with_one_key() {
        // Degenerate initializer == taker: one key passed twice, like
        // AV-12's activation.
        let mut e = Escrow::initialize(ALICE, ALICE, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let children = e
            .split_escrow(ALICE, ALICE, &[500_000, 500_000], SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(e.state(), EscrowState::Split);
        assert_eq!(children.len(), 2);
    }

    #[test]
    fn split_rejects_paused_escrow() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(ALICE)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.pause(ALICE, None).unwrap();
        assert_eq!(
            e.split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT),
            Err(EscrowError::Paused)
        );
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn split_adds_no_fields_and_keeps_space() {
        // AV-81 touches no persisted field: the state byte simply
        // carries discriminant 8. Re-asserted here so this feature
        // cannot silently grow the account (every byte of VAULT_SPACE
        // is rent the initializer paid for).
        let mut e = funded_escrow();
        e.split_escrow(ALICE, BOB, &[1_000_000], SplitConfig::default(), EXPIRES_AT)
            .unwrap();
        assert_eq!(e.state(), EscrowState::Split);
        assert_eq!(EscrowState::Split as u8, 8, "Split appended last");
        assert_eq!(VAULT_SPACE, 7663, "full Vault account space"); // AV-195: +309, AV-196: +1
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN, "no layout change");
    }
}

// ---------- AV-93: multi-recipient release split ----------

#[cfg(test)]
mod release_split_tests {
    use super::*;
    use crate::events::IndexedEscrow;

    const ALICE: [u8; 32] = [0xAA; 32]; // initializer
    const BOB: [u8; 32] = [0xBB; 32]; // taker
    const CAROL: [u8; 32] = [0xCC; 32];
    const DAVE: [u8; 32] = [0xDD; 32];
    const MALLORY: [u8; 32] = [0xEE; 32]; // stranger
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_750_000_000;

    fn funded_escrow() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    fn funded_allowlisted_escrow() -> Escrow {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_protocol_fee(250) // 2.5%
            .unwrap()
            .with_payout_allowlist(&[BOB, CAROL, DAVE])
            .unwrap();
        let mut e = e;
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    #[test]
    fn split_happy_path_splits_net_after_fee() {
        let mut e = funded_allowlisted_escrow();
        let (legs, fee) = e
            .release_split(ALICE, NOW, 400_000, None, &[(BOB, 5000), (CAROL, 5000)])
            .unwrap();
        // AV-17: fee charged on the gross first: floor(400_000 * 250 /
        // 10_000) = 10_000; the net 390_000 splits evenly.
        assert_eq!(fee, 10_000);
        assert_eq!(legs, vec![(BOB, 195_000), (CAROL, 195_000)]);
        assert_eq!(e.fees_paid(), 10_000);
        // Conservation: `released` keeps the gross, like `release`.
        assert_eq!(e.released_amount(), 400_000);
        assert_eq!(e.remaining_amount(), 600_000);
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn split_dust_lands_on_first_recipient() {
        // A fee-less allowlisted escrow for exact dust math.
        let base = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_payout_allowlist(&[BOB, CAROL, DAVE])
            .unwrap();
        let mut e = base;
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let (legs, fee) = e
            .release_split(ALICE, NOW, 1000, None, &[(BOB, 3333), (CAROL, 3333), (DAVE, 3334)])
            .unwrap();
        assert_eq!(fee, 0);
        // floor(1000 * 3333 / 10_000) = 333 each; the 1-lamport dust
        // from flooring lands on the first recipient.
        assert_eq!(legs, vec![(BOB, 334), (CAROL, 333), (DAVE, 333)]);
        let total: u64 = legs.iter().map(|(_, s)| s).sum();
        assert_eq!(total, 1000, "legs sum to the net exactly");
    }

    #[test]
    fn split_closing_split_moves_to_released() {
        let mut e = funded_allowlisted_escrow();
        let (legs, fee) = e
            .release_split(ALICE, NOW, 1_000_000, None, &[(BOB, 7000), (CAROL, 3000)])
            .unwrap();
        // floor(1_000_000 * 250 / 10_000) = 25_000 fee; net 975_000.
        assert_eq!(fee, 25_000);
        assert_eq!(legs, vec![(BOB, 682_500), (CAROL, 292_500)]);
        assert_eq!(e.released_amount(), 1_000_000, "gross, like release");
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn split_rejects_bad_share_tables() {
        let mut e = funded_allowlisted_escrow();
        // Empty table.
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        assert_eq!(err.code(), 150);
        // Zero bps weight.
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[(BOB, 10_000), (CAROL, 0)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        assert_eq!(err.code(), 150);
        // Zero recipient address.
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[([0u8; 32], 10_000)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        // Weight sum under 10_000.
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[(BOB, 5000), (CAROL, 4999)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        // Weight sum over 10_000.
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[(BOB, 5000), (CAROL, 5001)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        // Too many recipients.
        let many: Vec<([u8; 32], u16)> = (0..9u8).map(|i| ([i; 32], 1111)).collect();
        let err = e.release_split(ALICE, NOW, 100_000, None, &many).unwrap_err();
        assert_eq!(err, EscrowError::InvalidReleaseSplit);
        // Nothing moved on any rejection.
        assert_eq!(e.released_amount(), 0);
        assert_eq!(e.fees_paid(), 0);
    }

    #[test]
    fn split_enforces_the_payout_allowlist_per_recipient() {
        // Default policy (no allowlist): only the taker passes.
        let mut e = funded_escrow();
        let (legs, _) = e
            .release_split(ALICE, NOW, 100_000, None, &[(BOB, 10_000)])
            .unwrap();
        assert_eq!(legs, vec![(BOB, 100_000)]);
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[(CAROL, 10_000)])
            .unwrap_err();
        assert_eq!(err, EscrowError::PayoutNotAllowlisted);
        // With an allowlist: every recipient must be a member.
        let mut e = funded_allowlisted_escrow();
        e.release_split(ALICE, NOW, 100_000, None, &[(BOB, 5000), (CAROL, 5000)])
            .unwrap();
        let err = e
            .release_split(ALICE, NOW, 100_000, None, &[(BOB, 5000), (MALLORY, 5000)])
            .unwrap_err();
        assert_eq!(err, EscrowError::PayoutNotAllowlisted);
        assert_eq!(err.code(), 127);
        // The allowlist pin runs before the amount math: an off-policy
        // recipient with amount 0 reports the policy violation, not
        // AmountMismatch.
        let err = e
            .release_split(ALICE, NOW, 0, None, &[(MALLORY, 10_000)])
            .unwrap_err();
        assert_eq!(err, EscrowError::PayoutNotAllowlisted);
    }

    #[test]
    fn split_check_order_mirrors_release() {
        let shares = [(BOB, 10_000)];
        // Authority first — a stranger learns nothing, even with a bad
        // table.
        let mut e = funded_escrow();
        assert_eq!(
            e.release_split(MALLORY, NOW, 100_000, None, &[]),
            Err(EscrowError::Unauthorized)
        );
        // State before input shape.
        let e2 = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let mut e2 = e2;
        assert_eq!(
            e2.release_split(ALICE, NOW, 100_000, None, &[]),
            Err(EscrowError::InvalidStateTransition)
        );
        // Table shape before the gates.
        let mut e = funded_escrow();
        assert_eq!(
            e.release_split(ALICE, NOW, 100_000, None, &[]),
            Err(EscrowError::InvalidReleaseSplit)
        );
        // Milestones own the release path.
        let plan = MilestonePlan::new(&[400_000, 600_000]).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_milestones(plan)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.release_split(ALICE, NOW, 100_000, None, &shares),
            Err(EscrowError::InvalidMilestones)
        );
        // Amount math last: zero amount, then over-release.
        let mut e = funded_escrow();
        assert_eq!(
            e.release_split(ALICE, NOW, 0, None, &shares),
            Err(EscrowError::AmountMismatch)
        );
        assert_eq!(
            e.release_split(ALICE, NOW, 1_000_001, None, &shares),
            Err(EscrowError::ReleaseExceedsLocked)
        );
    }

    #[test]
    fn split_honors_quorum_and_timelock_gates() {
        // Quorum not satisfied.
        let policy = QuorumPolicy::new(&[CAROL, DAVE], &[1, 1], 2).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_quorum(policy)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.release_split(ALICE, NOW, 100_000, None, &[(BOB, 10_000)]),
            Err(EscrowError::QuorumNotReached)
        );
        // Timelock not reached.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_timelock(NOW + 3_600)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.release_split(ALICE, NOW, 100_000, None, &[(BOB, 10_000)]),
            Err(EscrowError::TimelockNotReached)
        );
    }

    #[test]
    fn split_emits_indexed_event_with_stamped_legs() {
        // The adapter's builder surface carries no payout-allowlist
        // passthrough, so this exercises the taker-only default policy
        // with a single-leg split — the stamp path is identical for N
        // legs (the multi-leg stamp math is covered on the state
        // machine above).
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0x1D; 32], NOW - 10)
            .unwrap()
            .with_protocol_fee(250)
            .unwrap();
        e.fund(ALICE, NOW - 5).unwrap();
        let before = e.event_count();
        let (legs, fee) = e
            .release_split(ALICE, 400_000, None, &[(BOB, 10_000)], NOW)
            .unwrap();
        assert_eq!(fee, 10_000);
        assert_eq!(legs, vec![(BOB, 390_000)]);
        assert_eq!(e.event_count(), before + 1);
        let ev = e.events().last().copied().expect("event pushed");
        assert_eq!(ev.kind, EscrowEventKind::ReleasedSplit);
        assert_eq!((ev.from, ev.to), (EscrowState::Funded, EscrowState::Funded));
        assert_eq!(ev.amounts.payout, 400_000, "gross, like Released");
        assert_eq!(ev.amounts.fee, 10_000);
        let (roster, len) = ev.release_split.expect("legs stamped");
        assert_eq!(len, 1);
        assert_eq!(roster[0].recipient, BOB);
        assert_eq!(roster[0].net_share, 390_000);
        // Every other event kind carries no roster.
        assert!(e.events()[0].release_split.is_none());
    }

    #[test]
    fn split_adds_no_fields_and_keeps_space() {
        // AV-93 is instruction logic: no new persisted field — the
        // vault account layout (VAULT_SPACE) is rent-critical and must
        // not move.
        let mut e = funded_escrow();
        e.release_split(ALICE, NOW, 1_000_000, None, &[(BOB, 10_000)])
            .unwrap();
        assert_eq!(e.state(), EscrowState::Released);
        assert_eq!(VAULT_SPACE, 7663, "full Vault account space"); // AV-195: +309, AV-196: +1
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN, "no layout change");
    }
}

// ---------- AV-82: opt-in default-penalty (slash) ----------

#[cfg(test)]
mod slash_tests {
    use super::*;
    use crate::events::IndexedEscrow;
    use crate::keeper::{scan_keeper_actions, KeeperActionKind};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const CAROL: [u8; 32] = [0xCC; 32];
    const PENALTY: [u8; 32] = [0xDD; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;
    const DEADLINE: u64 = T0 + 86_400;

    fn uninitialized_with_terms() -> Escrow {
        Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
    }

    fn slashable(amount: u64) -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, amount, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        e
    }

    fn watch(id: [u8; 32], escrow: Escrow) -> WatchedEscrow {
        WatchedEscrow {
            escrow_id: id,
            escrow,
            reference: None,
            vault_derivation: None,
            pending_intent: None,
        }
    }

    #[test]
    fn slash_terms_reject_zero_penalty_account() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e
            .with_slash_terms([0u8; 32], DEADLINE)
            .unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert_eq!(EscrowError::SlashNotEligible.code(), 143);
    }

    #[test]
    fn slash_terms_uninitialized_only() {
        let e = uninitialized_with_terms();
        assert_eq!(e.slash_terms().unwrap().penalty_account, PENALTY);
        assert_eq!(e.slash_terms().unwrap().slash_deadline, DEADLINE);
        assert_eq!(e.penalty_paid(), 0);
        // Re-configuring on a live escrow is rejected — the deadline is
        // fixed before funds move.
        let live = slashable(1_000_000);
        let err = live.with_slash_terms(PENALTY, DEADLINE + 1).unwrap_err();
        assert_eq!(err, EscrowError::InvalidStateTransition);
        let _ = e;
    }

    #[test]
    fn slash_happy_path_initializer() {
        let mut e = slashable(1_000_000);
        let slashed = e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        assert_eq!(slashed, 200_000);
        assert_eq!(e.penalty_paid(), 200_000);
        assert_eq!(e.released_amount(), 0);
        // The escrow stays Funded: the taker can still earn the rest.
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.remaining_amount(), 800_000);
    }

    #[test]
    fn slash_emits_indexed_event_with_penalty_amounts() {
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xEE; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0 + 1).unwrap();
        let slashed = e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        assert_eq!(slashed, 200_000);
        let last = e.events().last().unwrap();
        assert_eq!(last.kind, EscrowEventKind::Slashed);
        assert_eq!(last.amounts.penalty, 200_000);
        assert_eq!(last.amounts.payout, 0);
        // Like `resolve`: the authority rides the history-ring actor
        // slot, not the `caller` field.
        assert_eq!(last.caller, None);
        assert_eq!(last.from, EscrowState::Funded);
        assert_eq!(last.to, EscrowState::Funded);
    }

    #[test]
    fn slash_happy_path_arbiter() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_arbiter(CAROL)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        let slashed = e.slash(CAROL, 100_000, None, DEADLINE + 60).unwrap();
        assert_eq!(slashed, 100_000);
        assert_eq!(e.penalty_paid(), 100_000);
    }

    #[test]
    fn slash_rejects_stranger() {
        let mut e = slashable(1_000_000);
        let err = e.slash(CAROL, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::Unauthorized);
    }

    #[test]
    fn slash_rejects_before_deadline() {
        let mut e = slashable(1_000_000);
        let err = e.slash(ALICE, 100_000, None, DEADLINE - 1).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert_eq!(e.penalty_paid(), 0);
        assert!(!e.is_slash_eligible(DEADLINE - 1));
        assert!(e.is_slash_eligible(DEADLINE));
    }

    #[test]
    fn slash_rejects_without_terms() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, T0).unwrap();
        let err = e.slash(ALICE, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert!(!e.is_slash_eligible(DEADLINE));
    }

    #[test]
    fn slash_rejects_zero_and_excess_amount() {
        let mut e = slashable(1_000_000);
        let err = e.slash(ALICE, 0, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::AmountMismatch);
        let err = e.slash(ALICE, 1_000_001, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
    }

    #[test]
    fn slash_is_one_shot() {
        let mut e = slashable(1_000_000);
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        let err = e.slash(ALICE, 100_000, None, DEADLINE + 1).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert_eq!(e.penalty_paid(), 200_000);
        assert!(!e.is_slash_eligible(DEADLINE + 1));
    }

    #[test]
    fn slash_rejects_disputed_escrow() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_arbiter(CAROL)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.escalate(ALICE, T0 + 1, e.remaining_amount(), None, None, 0).unwrap();
        assert_eq!(e.state(), EscrowState::Disputed);
        let err = e.slash(ALICE, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        // Arbitration, not the penalty clause, owns disputed funds.
        assert!(!e.is_slash_eligible(DEADLINE));
    }

    #[test]
    fn slash_rejects_milestone_and_subscription_schedules() {
        let plan = MilestonePlan::new(&[400_000, 600_000]).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_milestones(plan)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        let err = e.slash(ALICE, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);

        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_subscription(86_400, 4, 250_000)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        let err = e.slash(ALICE, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
    }

    #[test]
    fn slash_rejects_unactivated_dual_sig() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_sig()
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        // Only one activation bit set: not yet a funded dual-sig escrow.
        e.activate(ALICE).unwrap();
        let mut both = e;
        both.activate(BOB).unwrap();
        both.fund(ALICE, T0).unwrap();
        // Both bits set and funded: slash is allowed.
        both.slash(ALICE, 100_000, None, DEADLINE).unwrap();
        // One bit only: fund never happened here, so the state check
        // fires first (Funded required); assert the dual-sig gate
        // independently on a funded-but-unactivated escrow is
        // impossible — activation is a precondition of fund.
        let err = e.slash(ALICE, 100_000, None, DEADLINE).unwrap_err();
        assert_eq!(err, EscrowError::InvalidStateTransition);
    }

    #[test]
    fn conservation_four_buckets() {
        // amount == released + penalty_paid + refundable remainder.
        let mut e = slashable(1_000_000);
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        e.release(ALICE, T0 + 1, 300_000, None, BOB).unwrap();
        assert_eq!(e.released_amount(), 300_000);
        assert_eq!(e.penalty_paid(), 200_000);
        assert_eq!(e.remaining_amount(), 500_000);
        assert_eq!(
            e.amount(),
            e.released_amount() + e.penalty_paid() + e.remaining_amount()
        );
    }

    #[test]
    fn release_after_slash_is_capped_at_remainder() {
        let mut e = slashable(1_000_000);
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        // 900_000 > 800_000 remainder: rejected.
        let err = e.release(ALICE, T0 + 1, 900_000, None, BOB).unwrap_err();
        assert_eq!(err, EscrowError::ReleaseExceedsLocked);
        // Draining the remainder closes the escrow.
        e.release(ALICE, T0 + 1, 800_000, None, BOB).unwrap();
        assert_eq!(e.state(), EscrowState::Released);
        assert_eq!(e.remaining_amount(), 0);
    }

    #[test]
    fn keeper_lists_slash_after_deadline() {
        let e = slashable(1_000_000);
        let report = scan_keeper_actions(&[watch([0x01; 32], e)], DEADLINE);
        assert_eq!(report.actions.len(), 1);
        let init = &report.actions[0];
        assert_eq!(init.kind, KeeperActionKind::Slash);
        assert_eq!(init.caller, ALICE);
        assert_eq!(init.caller_role, "initializer");
        assert_eq!(init.reason, "slash_deadline_passed");
        assert_eq!(init.refund_to, None);
        assert_eq!(init.amount, 1_000_000);
        // With an arbiter configured the enforcer signs as arbiter.
        let mut e2 = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_arbiter(CAROL)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap();
        e2.fund(ALICE, T0).unwrap();
        let report = scan_keeper_actions(&[watch([0x02; 32], e2)], DEADLINE);
        assert_eq!(report.actions.len(), 2);
        assert_eq!(report.actions[0].caller_role, "initializer");
        assert_eq!(report.actions[1].kind, KeeperActionKind::Slash);
        assert_eq!(report.actions[1].caller, CAROL);
        assert_eq!(report.actions[1].caller_role, "arbiter");
        assert_eq!(report.actions[1].reason, "slash_deadline_passed");
        assert_eq!(report.actions[1].refund_to, None);
        // Before the deadline nothing is listed.
        let e3 = slashable(1_000_000);
        let report = scan_keeper_actions(&[watch([0x03; 32], e3)], DEADLINE - 1);
        assert!(report.actions.is_empty());
    }

    #[test]
    fn snapshot_carries_slash_fields() {
        let mut e = slashable(1_000_000);
        let json = e.snapshot(DEADLINE).to_json();
        assert!(json.contains("\"slash_eligible\":true"), "{json}");
        assert!(json.contains(&format!(
            "\"slash_terms\":{{\"penalty_account\":\"{}\",\"slash_deadline\":{}}}",
            "dd".repeat(32),
            DEADLINE
        )), "{json}");
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        let json = e.snapshot(DEADLINE).to_json();
        assert!(json.contains("\"penalty_paid\":200000"), "{json}");
        assert!(json.contains("\"slash_eligible\":false"), "{json}");
    }

    #[test]
    fn slash_terms_persist_in_serialized_tail() {
        // v3 tail: schema_version (1) + slash_terms (41) + penalty_paid (8)
        // + cpi_allowlist (258) + multisig_authority (67) + the 26-byte
        // appeal region + the 82-byte vesting-curve region + the
        // 42-byte evidence-commitment region + the 386-byte basket
        // region + the 130-byte denylist region + the 19-byte auction
        // region.
        let e = slashable(1_000_000);
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        let base = ESCROW_BODY_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - PRICE_GATE_LEN - PENALTY_ESCALATION_TAIL_LEN - COMPOUND_INTEREST_TAIL_LEN - SLOT_TIMELOCK_TAIL_LEN - RELEASE_COOLING_TAIL_LEN - FUNDING_TAIL_LEN - RENT_TOP_UP_LEN - DEADMAN_REGION_LEN - PAYOUT_SPLIT_LEN - INTEREST_REGION_LEN - POOL_REGION_LEN - SWAP_LINK_REGION_LEN - APPEAL_BOND_REGION_LEN - DELEGATION_REGION_LEN - STREAMING_FEE_REGION_LEN - TRANSFER_HOOK_REGION_LEN - (1 + DUTCH_AUCTION_LEN) - (1 + PAYOUT_DENYLIST_LEN) - BASKET_REGION_LEN - (1 + 32) - 1 - 8 - (1 + VESTING_CURVE_LEN) - APPEAL_REGION_LEN - (1 + MULTISIG_AUTHORITY_LEN) - (1 + CPI_ALLOWLIST_LEN) - RENT_SWEEP_TAIL_LEN - 8 - 41 - 1 - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(bytes[base], 3, "schema_version");
        assert_eq!(bytes[base + 1], 1, "slash_terms: Some");
        assert_eq!(&bytes[base + 2..base + 34], &PENALTY, "penalty account");
        assert_eq!(
            u64::from_le_bytes(bytes[base + 34..base + 42].try_into().unwrap()),
            DEADLINE,
            "slash deadline"
        );
        assert_eq!(
            u64::from_le_bytes(
                bytes[ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - PRICE_GATE_LEN - PENALTY_ESCALATION_TAIL_LEN - COMPOUND_INTEREST_TAIL_LEN - SLOT_TIMELOCK_TAIL_LEN - RELEASE_COOLING_TAIL_LEN - FUNDING_TAIL_LEN - RENT_TOP_UP_LEN - DEADMAN_REGION_LEN - PAYOUT_SPLIT_LEN - INTEREST_REGION_LEN - POOL_REGION_LEN - SWAP_LINK_REGION_LEN - APPEAL_BOND_REGION_LEN - DELEGATION_REGION_LEN - STREAMING_FEE_REGION_LEN - TRANSFER_HOOK_REGION_LEN - (1 + DUTCH_AUCTION_LEN) - (1 + PAYOUT_DENYLIST_LEN) - BASKET_REGION_LEN - (1 + 32) - 1 - 8 - (1 + VESTING_CURVE_LEN) - APPEAL_REGION_LEN - (1 + MULTISIG_AUTHORITY_LEN) - (1 + CPI_ALLOWLIST_LEN) - RENT_SWEEP_TAIL_LEN - 8 - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN
                    ..ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - PRICE_GATE_LEN - PENALTY_ESCALATION_TAIL_LEN - COMPOUND_INTEREST_TAIL_LEN - SLOT_TIMELOCK_TAIL_LEN - RELEASE_COOLING_TAIL_LEN - FUNDING_TAIL_LEN - RENT_TOP_UP_LEN - DEADMAN_REGION_LEN - PAYOUT_SPLIT_LEN - INTEREST_REGION_LEN - POOL_REGION_LEN - SWAP_LINK_REGION_LEN - APPEAL_BOND_REGION_LEN - DELEGATION_REGION_LEN - STREAMING_FEE_REGION_LEN - TRANSFER_HOOK_REGION_LEN - (1 + DUTCH_AUCTION_LEN) - (1 + PAYOUT_DENYLIST_LEN) - BASKET_REGION_LEN - (1 + 32) - 1 - 8 - (1 + VESTING_CURVE_LEN) - APPEAL_REGION_LEN - (1 + MULTISIG_AUTHORITY_LEN) - (1 + CPI_ALLOWLIST_LEN) - RENT_SWEEP_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN]
                    .try_into()
                    .unwrap()
            ),
            0,
            "penalty_paid: zeroed before any slash"
        );
        // Structural decode round-trips the terms.
        let mut full = crate::discriminator::vault_account_discriminator().to_vec();
        full.extend_from_slice(&bytes);
        let decoded = decode_vault_account(&full).unwrap();
        assert_eq!(decoded.slash_terms().unwrap().penalty_account, PENALTY);
        assert_eq!(decoded.penalty_paid(), 0);
    }

    #[test]
    fn migrate_schema_zero_fills_slash_region() {
        // A pre-AV-82 v1 vault migrates to v2 with no slash terms
        // configured and zero penalty paid — same struct-level
        // simulation the AV-75 migration tests use (the byte decoder
        // only accepts full-size accounts; the program layer pads the
        // realloc'd account before decoding).
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.schema_version = 1;
        e.migrate_schema(ALICE).unwrap();
        assert_eq!(e.schema_version(), 3);
        assert_eq!(e.slash_terms(), None);
        assert_eq!(e.penalty_paid(), 0);
        assert!(!e.is_slash_eligible(DEADLINE));
    }
}
// ---------------------------------------------------------------------------
// AV-126: tiered default-penalty (slash) ladder tests.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod slash_ladder_tests {
    use super::*;
    use crate::discriminator::decode_vault_account;
    use crate::events::IndexedEscrow;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const PENALTY: [u8; 32] = [0xDD; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;
    const DAY: u64 = 86_400;

    /// A funded ladder escrow: three rungs — (T0, 1%) → (T0+1d, 5%) →
    /// (T0+2d, 10%) — on a 1_000_000 lockup.
    fn ladder_escrow() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_ladder(PENALTY, &[(T0, 100), (T0 + DAY, 500), (T0 + 2 * DAY, 1_000)])
            .unwrap();
        e.fund(ALICE, T0 - 1).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        e
    }

    fn account_bytes(e: &Escrow) -> Vec<u8> {
        let mut out = crate::discriminator::vault_account_discriminator().to_vec();
        out.extend_from_slice(&super::account_space_tests::encode_escrow(e));
        out
    }

    #[test]
    fn ladder_error_code_is_184() {
        assert_eq!(EscrowError::InvalidSlashLadder.code(), 184);
    }

    #[test]
    fn ladder_rejects_empty_table() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e.with_slash_ladder(PENALTY, &[]).unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
        assert_eq!(err.code(), 184);
    }

    #[test]
    fn ladder_rejects_overlong_table() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let rungs: Vec<(u64, u16)> = (0..9).map(|i| (T0 + i * DAY, 100 + i as u16)).collect();
        let err = e.with_slash_ladder(PENALTY, &rungs).unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_rejects_zero_bps_rung() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 0), (T0 + DAY, 500)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_rejects_bps_above_10000() {
        // A rung above 100% is incoherent — a cap above the whole
        // slashable remainder is a misconfiguration, not a policy.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 100), (T0 + DAY, 10_001)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_rejects_zero_penalty_account() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e
            .with_slash_ladder([0u8; 32], &[(T0, 100)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_rejects_non_ascending_deadlines() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Equal deadlines: not a schedule.
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 100), (T0, 500)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Retreating deadline.
        let err = e
            .with_slash_ladder(PENALTY, &[(T0 + DAY, 100), (T0, 500)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_rejects_non_ascending_bps() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Equal bps: not an escalation.
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 100), (T0 + DAY, 100)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Falling bps.
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 500), (T0 + DAY, 100)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_mutually_exclusive_with_slash_terms() {
        // Ladder after single-level terms.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, T0)
            .unwrap();
        let err = e.with_slash_ladder(PENALTY, &[(T0, 100)]).unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
        // Single-level terms after the ladder.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_ladder(PENALTY, &[(T0, 100)])
            .unwrap();
        let err = e.with_slash_terms(PENALTY, T0).unwrap_err();
        assert_eq!(err, EscrowError::InvalidSlashLadder);
    }

    #[test]
    fn ladder_uninitialized_only() {
        let mut e = ladder_escrow();
        assert_eq!(e.state(), EscrowState::Funded);
        let err = e
            .with_slash_ladder(PENALTY, &[(T0, 100)])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidStateTransition);
        let _ = e;
    }

    #[test]
    fn ladder_slash_consumes_rungs_in_order() {
        let mut e = ladder_escrow();
        assert_eq!(e.slash_ladder_index(), 0);
        // Rung 0: 1% of 1_000_000 = 10_000.
        let s1 = e.slash(ALICE, 10_000, None, T0).unwrap();
        assert_eq!(s1, 10_000);
        assert_eq!(e.penalty_paid(), 10_000);
        assert_eq!(e.slash_ladder_index(), 1);
        // Rung 1: 5% of the 990_000 remainder = 49_500.
        let s2 = e.slash(ALICE, 49_500, None, T0 + DAY).unwrap();
        assert_eq!(s2, 49_500);
        assert_eq!(e.penalty_paid(), 59_500);
        assert_eq!(e.slash_ladder_index(), 2);
        // Rung 2: 10% of the 940_500 remainder = 94_050.
        let s3 = e.slash(ALICE, 94_050, None, T0 + 2 * DAY).unwrap();
        assert_eq!(s3, 94_050);
        assert_eq!(e.penalty_paid(), 153_550);
        // The top rung is consumed — the cursor stays.
        assert_eq!(e.slash_ladder_index(), 2);
        // The escrow stays Funded throughout — the taker can still
        // earn the remainder by performing late.
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.remaining_amount(), 1_000_000 - 153_550);
    }

    #[test]
    fn ladder_single_slash_cap_enforced() {
        let mut e = ladder_escrow();
        // Rung 0 caps at 10_000 — one lamport over is refused.
        let err = e.slash(ALICE, 10_001, None, T0).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert_eq!(err.code(), 143);
        // A refused slash changes nothing.
        assert_eq!(e.penalty_paid(), 0);
        assert_eq!(e.slash_ladder_index(), 0);
        // The exact cap passes.
        e.slash(ALICE, 10_000, None, T0).unwrap();
        assert_eq!(e.slash_ladder_index(), 1);
    }

    #[test]
    fn ladder_exhausted_caps_at_top_rung() {
        let mut e = ladder_escrow();
        e.slash(ALICE, 10_000, None, T0).unwrap();
        e.slash(ALICE, 49_500, None, T0 + DAY).unwrap();
        e.slash(ALICE, 94_050, None, T0 + 2 * DAY).unwrap();
        assert_eq!(e.slash_ladder_index(), 2);
        // Exhausted: a fourth slash is still allowed, capped at the
        // top rung's 10% of the 846_450 remainder = 84_645.
        let s4 = e.slash(ALICE, 84_645, None, T0 + 3 * DAY).unwrap();
        assert_eq!(s4, 84_645);
        assert_eq!(e.penalty_paid(), 153_550 + 84_645);
        // The cursor never advances past the top rung.
        assert_eq!(e.slash_ladder_index(), 2);
        // And the top-rung cap still binds the fifth slash.
        let err = e.slash(ALICE, 100_000, None, T0 + 4 * DAY).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
    }

    #[test]
    fn ladder_eligibility_bypasses_one_shot_gate() {
        let mut e = ladder_escrow();
        // Before the first rung's deadline: not eligible.
        assert!(!e.is_slash_eligible(T0 - 1));
        assert!(e.is_slash_eligible(T0));
        e.slash(ALICE, 10_000, None, T0).unwrap();
        // A single-level escrow would now be ineligible (one-shot);
        // the ladder stays eligible — the next rung is a separate
        // enforcement.
        assert!(e.is_slash_eligible(T0 + DAY));
        // Still gated by the rung deadline.
        assert!(!e.is_slash_eligible(T0 + DAY - 1));
    }

    #[test]
    fn ladder_slash_before_rung_deadline_refused() {
        let mut e = ladder_escrow();
        e.slash(ALICE, 10_000, None, T0).unwrap();
        assert_eq!(e.slash_ladder_index(), 1);
        // Rung 1's deadline has not passed yet — the next rung is not
        // available, even though rung 0 was already consumed.
        let err = e.slash(ALICE, 100, None, T0 + DAY - 1).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert_eq!(e.slash_ladder_index(), 1);
    }

    #[test]
    fn ladder_event_carries_consumed_rung() {
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xEE; 32], T0 - 1)
            .unwrap()
            .with_slash_ladder(PENALTY, &[(T0, 100), (T0 + DAY, 500)])
            .unwrap();
        e.fund(ALICE, T0 - 1).unwrap();
        e.slash(ALICE, 10_000, None, T0).unwrap();
        let last = e.events().last().unwrap();
        assert_eq!(last.kind, EscrowEventKind::Slashed);
        assert_eq!(last.slash_ladder_index, Some(0));
        e.slash(ALICE, 49_500, None, T0 + DAY).unwrap();
        let last = e.events().last().unwrap();
        assert_eq!(last.slash_ladder_index, Some(1));
    }

    #[test]
    fn single_level_slash_event_carries_no_rung() {
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xEE; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, T0)
            .unwrap();
        e.fund(ALICE, T0 + 1).unwrap();
        e.slash(ALICE, 200_000, None, T0).unwrap();
        let last = e.events().last().unwrap();
        assert_eq!(last.kind, EscrowEventKind::Slashed);
        assert_eq!(last.slash_ladder_index, None);
    }

    #[test]
    fn plain_escrow_keeps_one_shot_slash() {
        // Regression pin: without a ladder the one-shot gate is
        // unchanged — a second slash is refused.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, T0)
            .unwrap();
        e.fund(ALICE, T0 + 1).unwrap();
        e.slash(ALICE, 200_000, None, T0).unwrap();
        let err = e.slash(ALICE, 100_000, None, T0 + DAY).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        assert!(!e.is_slash_eligible(T0 + DAY));
    }

    #[test]
    fn ladder_tail_byte_layout() {
        let e = ladder_escrow();
        let body = super::account_space_tests::encode_escrow(&e);
        assert_eq!(body.len(), ESCROW_BODY_LEN);
        let tail = ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        // The ladder region: 1-byte discriminant + 113-byte ladder.
        assert_eq!(body[tail], 1, "ladder discriminant");
        assert_eq!(&body[tail + 1..tail + 33], &PENALTY, "penalty account");
        // Rung 0: deadline then bps, little-endian.
        assert_eq!(
            u64::from_le_bytes(body[tail + 33..tail + 41].try_into().unwrap()),
            T0,
            "rung 0 deadline"
        );
        assert_eq!(
            u16::from_le_bytes(body[tail + 41..tail + 43].try_into().unwrap()),
            100,
            "rung 0 bps"
        );
        // Rung 1 at +10.
        assert_eq!(
            u64::from_le_bytes(body[tail + 43..tail + 51].try_into().unwrap()),
            T0 + DAY,
            "rung 1 deadline"
        );
        assert_eq!(
            u16::from_le_bytes(body[tail + 51..tail + 53].try_into().unwrap()),
            500,
            "rung 1 bps"
        );
        // Live rung count after the 8 fixed slots: 1 + 32 + 80 = 113.
        assert_eq!(body[tail + 113], 3, "rung count");
        // The cursor byte trails the region.
        assert_eq!(body[tail + 114], 0, "cursor starts at rung 0");
    }

    #[test]
    fn ladder_index_persists_across_serialization() {
        let mut e = ladder_escrow();
        e.slash(ALICE, 10_000, None, T0).unwrap();
        assert_eq!(e.slash_ladder_index(), 1);
        let body = super::account_space_tests::encode_escrow(&e);
        let tail = ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(body[tail + 114], 1, "cursor byte persists the advance");
        // The structural decoder round-trips the ladder and the
        // cursor.
        let decoded = decode_vault_account(&account_bytes(&e)).unwrap();
        let ladder = decoded.slash_ladder().unwrap();
        assert_eq!(ladder.penalty_account, PENALTY);
        assert_eq!(ladder.rung_count, 3);
        assert_eq!(ladder.rungs[0].deadline, T0);
        assert_eq!(ladder.rungs[0].bps, 100);
        assert_eq!(ladder.rungs[2].deadline, T0 + 2 * DAY);
        assert_eq!(ladder.rungs[2].bps, 1_000);
        assert_eq!(decoded.slash_ladder_index(), 1);
        // A decoded ladder escrow keeps enforcing: rung 1's cap
        // applies to the next slash.
        let mut d = decoded;
        let err = d.slash(ALICE, 49_501, None, T0 + DAY).unwrap_err();
        assert_eq!(err, EscrowError::SlashNotEligible);
        d.slash(ALICE, 49_500, None, T0 + DAY).unwrap();
        assert_eq!(d.slash_ladder_index(), 2);
    }

    #[test]
    fn ladder_without_config_decodes_to_none() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let body = super::account_space_tests::encode_escrow(&e);
        let tail = ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(body[tail], 0, "None discriminant");
        assert!(body[tail + 1..tail + SLASH_LADDER_TAIL_LEN]
            .iter()
            .all(|b| *b == 0));
        let decoded = decode_vault_account(&account_bytes(&e)).unwrap();
        assert_eq!(decoded.slash_ladder(), None);
        assert_eq!(decoded.slash_ladder_index(), 0);
    }
}

// ---------------------------------------------------------------------------
// AV-86: slash-penalty appeal window tests.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod appeal_tests {
    use super::*;
    use crate::events::IndexedEscrow;
    use crate::keeper::{scan_keeper_actions, KeeperActionKind};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const PENALTY: [u8; 32] = [0xDD; 32];
    const M1: [u8; 32] = [0x11; 32];
    const M2: [u8; 32] = [0x22; 32];
    const M3: [u8; 32] = [0x33; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;
    const DEADLINE: u64 = T0 + 86_400;
    const WINDOW: u64 = 7 * 86_400; // 7 days.

    fn windowed_uninitialized() -> Escrow {
        Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
    }

    fn windowed_slashed() -> Escrow {
        let mut e = windowed_uninitialized()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        e
    }

    fn watch(id: [u8; 32], escrow: Escrow) -> WatchedEscrow {
        WatchedEscrow {
            escrow_id: id,
            escrow,
            reference: None,
            vault_derivation: None,
            pending_intent: None,
        }
    }

    #[test]
    fn appeal_window_builder_stores_the_window() {
        let e = windowed_uninitialized();
        assert_eq!(e.appeal_window_secs(), WINDOW);
        assert_eq!(e.appeal_deadline(), 0, "deadline is stamped by slash");
        assert_eq!(e.appeal_state(), AppealState::None);
        assert!(!e.is_appeal_under_review());
    }

    #[test]
    fn appeal_window_rejects_zero_window() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let err = e.with_appeal_window(0).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
        assert_eq!(EscrowError::InvalidAppealWindow.code(), 146);
    }

    #[test]
    fn appeal_window_is_uninitialized_only() {
        let live = windowed_slashed();
        let err = live.with_appeal_window(3600).unwrap_err();
        assert_eq!(err, EscrowError::InvalidStateTransition);
    }

    #[test]
    fn appeal_window_still_needs_an_unpaused_vault() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(ALICE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.pause(ALICE, None).unwrap();
        // The pause guard fires before the Uninitialized-state gate.
        let err = e.with_appeal_window(WINDOW).unwrap_err();
        assert_eq!(err, EscrowError::Paused);
    }

    #[test]
    fn slash_stamps_the_appeal_deadline() {
        let e = windowed_slashed();
        assert_eq!(e.appeal_deadline(), DEADLINE + WINDOW);
        assert!(e.is_appeal_eligible(DEADLINE));
        assert!(e.is_appeal_eligible(DEADLINE + WINDOW), "window is inclusive");
        assert!(!e.is_appeal_eligible(DEADLINE + WINDOW + 1));
        assert_eq!(e.appeal_state(), AppealState::None);
    }

    #[test]
    fn slash_without_a_window_leaves_appeals_off() {
        // A vault that never opted in has no appeal deadline at all.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        assert_eq!(e.appeal_deadline(), 0);
        assert!(!e.is_appeal_eligible(DEADLINE));
        assert_eq!(
            e.file_appeal(BOB, DEADLINE),
            Err(EscrowError::InvalidAppealWindow)
        );
    }

    #[test]
    fn slash_rejects_a_window_that_would_overflow_the_deadline() {
        // now + window_secs must fit in u64.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, u64::MAX)
            .unwrap()
            .with_appeal_window(3600)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        assert_eq!(
            e.slash(ALICE, 200_000, None, u64::MAX),
            Err(EscrowError::InvalidAppealWindow)
        );
        assert_eq!(e.appeal_deadline(), 0, "failed slash changes nothing");
        assert_eq!(e.penalty_paid(), 0);
    }

    #[test]
    fn file_appeal_rejects_a_stranger() {
        let mut e = windowed_slashed();
        let err = e.file_appeal(M1, DEADLINE + 1).unwrap_err();
        assert_eq!(err, EscrowError::Unauthorized);
        assert_eq!(e.appeal_state(), AppealState::None);
    }

    #[test]
    fn file_appeal_requires_a_resolvable_panel() {
        // No panel means a filed appeal could never be reviewed —
        // reject the filing outright.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        let err = e.file_appeal(BOB, DEADLINE + 1).unwrap_err();
        assert_eq!(err, EscrowError::InvalidArbiterPanel);
        assert_eq!(e.appeal_state(), AppealState::None);
    }

    #[test]
    fn file_appeal_needs_a_slash_and_an_open_window() {
        // Nothing slashed yet: no appeal.
        let mut e = windowed_uninitialized()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        let err = e.file_appeal(BOB, T0).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
        // Past the window: too late.
        let mut e = windowed_slashed();
        let err = e.file_appeal(BOB, DEADLINE + WINDOW + 1).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
        assert_eq!(e.appeal_state(), AppealState::None);
        // Exactly on the boundary still files (inclusive).
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + WINDOW).unwrap();
        assert_eq!(e.appeal_state(), AppealState::Filed);
        assert!(e.is_appeal_under_review());
    }

    #[test]
    fn file_appeal_is_one_shot() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let err = e.file_appeal(BOB, DEADLINE + 2).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
        assert_eq!(e.appeal_state(), AppealState::Filed);
        // So is the resolved state — a decided appeal stays decided.
        e.review_appeal(M1, true).unwrap();
        e.review_appeal(M2, true).unwrap();
        assert_eq!(e.appeal_state(), AppealState::Upheld);
        let err = e.file_appeal(BOB, DEADLINE + 3).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
    }

    #[test]
    fn review_appeal_rejects_a_non_member() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let err = e.review_appeal(ALICE, true).unwrap_err();
        assert_eq!(err, EscrowError::Unauthorized);
        assert_eq!(e.appeal_state(), AppealState::Filed);
    }

    #[test]
    fn review_appeal_rejects_a_missing_filing() {
        let mut e = windowed_slashed();
        let err = e.review_appeal(M1, true).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
    }

    #[test]
    fn first_votes_do_not_resolve_the_appeal() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        assert_eq!(e.review_appeal(M1, false).unwrap(), None);
        assert_eq!(e.appeal_state(), AppealState::Filed);
        assert!(e.is_appeal_under_review());
        let ballot = e.appeal_ballot();
        assert_eq!(ballot.voted, 1);
        assert_eq!(ballot.votes[M1[0] as usize % 8], 0, "packed slot is zeroed");
    }

    #[test]
    fn uphold_wins_on_threshold_and_keeps_the_penalty() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true).unwrap();
        let (outcome, refunded, _bond) = e.review_appeal(M2, true).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Upheld);
        assert_eq!(refunded, 0);
        assert_eq!(e.appeal_state(), AppealState::Upheld);
        assert!(!e.is_appeal_under_review());
        assert!(!e.is_appeal_eligible(DEADLINE + 1), "decided appeal is closed");
        assert_eq!(e.penalty_paid(), 200_000, "uphold keeps the penalty");
        assert_eq!(e.released_amount(), 0);
        // The terminal ballot rejects late votes.
        let err = e.review_appeal(M3, false).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealWindow);
    }

    #[test]
    fn overturn_refunds_the_penalty_to_the_taker() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, false).unwrap();
        let (outcome, refunded, _bond) = e.review_appeal(M2, false).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Overturned);
        assert_eq!(refunded, 200_000);
        assert_eq!(e.appeal_state(), AppealState::Overturned);
        assert_eq!(e.penalty_paid(), 0, "overturn clears the penalty ledger");
        assert_eq!(e.released_amount(), 200_000, "refund routes to the taker");
        // Conservation stays exact: escrow value is fully accounted.
        let total = e.released_amount() + e.penalty_paid();
        assert_eq!(total, 200_000, "no lamports created or destroyed");
    }

    #[test]
    fn revote_moves_the_ballot_and_mixed_votes_block_early_resolution() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true).unwrap();
        // A member can overwrite their own vote before the tally closes.
        e.review_appeal(M1, false).unwrap();
        assert_eq!(e.appeal_state(), AppealState::Filed, "1 overturn < 2");
        e.review_appeal(M2, true).unwrap();
        assert_eq!(e.appeal_state(), AppealState::Filed, "split vote stalls");
        // The second overturner finally reaches threshold.
        let (outcome, refunded, _bond) = e.review_appeal(M3, false).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Overturned);
        assert_eq!(refunded, 200_000);
    }

    #[test]
    fn appeal_events_follow_the_indexed_escrow_convention() {
        // Build the configuration through the indexed wrapper so the
        // appeal events ride the ring.
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xF1; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        let before = e.event_count();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        // A non-resolving vote emits nothing — only the filing and the
        // resolution ride the ring.
        e.review_appeal(M1, false, DEADLINE + 2).unwrap();
        assert_eq!(e.event_count(), before + 1);
        let (outcome, refunded, _bond) = e.review_appeal(M2, false, DEADLINE + 3).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Overturned);
        assert_eq!(e.event_count(), before + 2);
        let events = e.events();
        let filed = &events[before];
        let resolved = &events[before + 1];
        assert_eq!(filed.kind, EscrowEventKind::AppealFiled);
        assert_eq!(filed.from, EscrowState::Funded);
        assert_eq!(filed.to, EscrowState::Funded, "appeals never move funds");
        assert_eq!(filed.amounts.payout, 0, "filing moves no funds");
        assert_eq!(filed.amounts.fee, 0);
        assert_eq!(resolved.kind, EscrowEventKind::AppealResolved);
        assert_eq!(resolved.appeal_outcome, Some(AppealOutcome::Overturned));
        assert_eq!(resolved.amounts.payout, refunded);
        assert_eq!(resolved.amounts.fee, 0, "restitution carries no fee");
    }

    #[test]
    fn appeal_csv_export_round_trips() {
        use crate::event_csv::{csv_to_events, events_to_csv};
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xF1; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, 200_000, None, DEADLINE).unwrap();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true, DEADLINE + 2).unwrap();
        e.review_appeal(M2, true, DEADLINE + 3).unwrap();
        let csv = events_to_csv(e.events());
        assert!(csv.contains("appeal_filed"));
        assert!(csv.contains("appeal_resolved"));
        // Round-trips byte-identically (the appeal verdict itself is an
        // in-ring annotation — the importer stamps `appeal_outcome: None`
        // by the schema_versions precedent, and the CSV carries it).
        assert_eq!(events_to_csv(&csv_to_events(&csv).unwrap()), csv);
    }

    #[test]
    fn keeper_surfaces_the_file_appeal_action_for_the_taker() {
        let id = [0xF1; 32];
        let escrow = windowed_slashed();
        assert!(escrow.is_appeal_eligible(DEADLINE + 1));
        let report = scan_keeper_actions(&[watch(id, escrow)], DEADLINE + 1);
        let file = report
            .actions
            .iter()
            .find(|a| matches!(a.kind, KeeperActionKind::FileAppeal))
            .expect("taker can file an appeal inside the window");
        assert_eq!(file.escrow_id, id);
        assert_eq!(file.caller, BOB);
        assert_eq!(file.caller_role, "taker");
        assert_eq!(file.reason, "appeal_window_open");
    }

    #[test]
    fn keeper_surfaces_a_review_action_per_unvoted_member() {
        let id = [0xF1; 32];
        let mut escrow = windowed_slashed();
        escrow.file_appeal(BOB, DEADLINE + 1).unwrap();
        escrow.review_appeal(M1, true).unwrap();
        let report = scan_keeper_actions(&[watch(id, escrow)], DEADLINE + 2);
        let mut members: Vec<[u8; 32]> = report
            .actions
            .iter()
            .filter(|a| matches!(a.kind, KeeperActionKind::ReviewAppeal))
            .map(|a| a.caller)
            .collect();
        members.sort();
        assert_eq!(members, vec![M2, M3], "only unvoted members are nudged");
        let review = report
            .actions
            .iter()
            .find(|a| matches!(a.kind, KeeperActionKind::ReviewAppeal))
            .unwrap();
        assert_eq!(review.reason, "appeal_filed");
    }

    #[test]
    fn appeal_fields_round_trip_through_the_serialized_tail() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        assert_eq!(bytes.len(), 7655); // AV-195: +309 recovery, AV-196: +1 jury size
        // Appeal region: [4221..4247] — window (8), deadline (8), state
        // (1), ballot (9).
        assert_eq!(
            u64::from_le_bytes(bytes[4221..4229].try_into().unwrap()),
            WINDOW
        );
        assert_eq!(
            u64::from_le_bytes(bytes[4229..4237].try_into().unwrap()),
            DEADLINE + WINDOW
        );
        assert_eq!(bytes[4237], 1, "AppealState::Filed == 1");
        assert_eq!(bytes[4238], 1, "one vote cast");
        // Full-state decode (AV-75 decoder path) preserves the region —
        // the decoder expects the 8-byte discriminator + body.
        let mut full = crate::discriminator::vault_account_discriminator().to_vec();
        full.extend_from_slice(&bytes);
        let decoded = crate::discriminator::decode_vault_account(&full).unwrap();
        assert_eq!(decoded.appeal_window_secs, WINDOW);
        assert_eq!(decoded.appeal_deadline, DEADLINE + WINDOW);
        assert_eq!(decoded.appeal_state, AppealState::Filed);
        assert_eq!(decoded.appeal_ballot.voted, 1);
        // A vault that never opted in zero-fills the region.
        let plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&plain);
        assert_eq!(&bytes[4221..4247], &[0u8; 26]);
        // Unknown appeal-state discriminants are rejected by the decoder.
        let mut bad = full.clone();
        bad[8 + 4237] = 7;
        assert!(crate::discriminator::decode_vault_account(&bad).is_err());
    }

    #[test]
    fn snapshot_carries_the_appeal_state() {
        let mut e = windowed_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let snap = e.snapshot(DEADLINE + 2);
        let json = snap.to_json();
        assert!(json.contains(&format!("\"appeal_window_secs\":{}", WINDOW)));
        assert!(json.contains(&format!(
            "\"appeal_deadline\":{}",
            DEADLINE + WINDOW
        )));
        assert!(json.contains("\"appeal_state\":\"filed\""));
        assert!(json.contains("\"appeal_eligible\":false"));
    }
}

// ---------------------------------------------------------------------------
// AV-103: appeal-bond tests.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod appeal_bond_tests {
    use super::*;
    use crate::events::IndexedEscrow;
    use crate::keeper::{scan_keeper_actions, KeeperActionKind};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const PENALTY: [u8; 32] = [0xDD; 32];
    const M1: [u8; 32] = [0x11; 32];
    const M2: [u8; 32] = [0x22; 32];
    const M3: [u8; 32] = [0x33; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;
    const DEADLINE: u64 = T0 + 86_400;
    const WINDOW: u64 = 7 * 86_400; // 7 days.
    const AMOUNT: u64 = 1_000_000;
    const SLASHED: u64 = 200_000;
    const BOND: u64 = 50_000;

    fn bonded_uninitialized() -> Escrow {
        Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_appeal_bond(BOND)
            .unwrap()
    }

    fn bonded_slashed() -> Escrow {
        let mut e = bonded_uninitialized()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        e
    }

    fn watch(id: [u8; 32], escrow: Escrow) -> WatchedEscrow {
        WatchedEscrow {
            escrow_id: id,
            escrow,
            reference: None,
            vault_derivation: None,
            pending_intent: None,
        }
    }

    #[test]
    fn bond_builder_stores_the_bond() {
        let e = bonded_uninitialized();
        assert_eq!(e.appeal_bond(), BOND);
        assert_eq!(e.appeal_bond_paid(), 0, "nothing locked before filing");
        // The no-bond default keeps filing free (backward compatible).
        let plain = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        assert_eq!(plain.appeal_bond(), 0);
        assert_eq!(plain.appeal_bond_paid(), 0);
    }

    #[test]
    fn bond_builder_rejects_a_zero_bond() {
        let e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        let err = e.with_appeal_bond(0).unwrap_err();
        assert_eq!(err, EscrowError::InvalidAppealBond);
        assert_eq!(EscrowError::InvalidAppealBond.code(), 158);
    }

    #[test]
    fn bond_builder_is_uninitialized_only() {
        let live = bonded_slashed();
        let err = live.with_appeal_bond(BOND).unwrap_err();
        assert_eq!(err, EscrowError::InvalidStateTransition);
    }

    #[test]
    fn bond_builder_fails_fast_when_paused() {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(ALICE)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.pause(ALICE, None).unwrap();
        // The pause guard fires before the Uninitialized-state gate.
        let err = e.with_appeal_bond(BOND).unwrap_err();
        assert_eq!(err, EscrowError::Paused);
    }

    #[test]
    fn filing_locks_the_configured_bond() {
        let mut e = bonded_slashed();
        let locked = e.file_appeal(BOB, DEADLINE + 1).unwrap();
        assert_eq!(locked, BOND, "file_appeal returns the locked bond");
        assert_eq!(e.appeal_bond_paid(), BOND);
        assert_eq!(e.appeal_state(), AppealState::Filed);
        // The bond is an independent counter — never mixed into the
        // other sinks.
        assert_eq!(e.released_amount(), 0);
        assert_eq!(e.penalty_paid(), SLASHED);
    }

    #[test]
    fn filing_without_a_bond_locks_nothing() {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        let locked = e.file_appeal(BOB, DEADLINE + 1).unwrap();
        assert_eq!(locked, 0);
        assert_eq!(e.appeal_bond_paid(), 0);
        assert_eq!(e.appeal_state(), AppealState::Filed);
    }

    #[test]
    fn uphold_forfeits_the_bond_to_the_initializer() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true).unwrap();
        let (outcome, penalty_refunded, bond_moved) =
            e.review_appeal(M2, true).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Upheld);
        assert_eq!(penalty_refunded, 0);
        assert_eq!(
            bond_moved, BOND,
            "the forfeited bond is returned for transfer sizing"
        );
        assert_eq!(e.appeal_bond_paid(), 0, "counter zeroes on forfeit");
        assert_eq!(e.appeal_state(), AppealState::Upheld);
        assert_eq!(e.penalty_paid(), SLASHED, "uphold keeps the penalty");
        // The bond is never mixed into `released`.
        assert_eq!(e.released_amount(), 0);
        // Principal conservation stays exact: the bond is additional
        // inflow, tracked in its own (now zeroed) counter.
        assert_eq!(
            e.remaining_amount() + e.released_amount() + e.penalty_paid(),
            AMOUNT,
            "principal conservation: amount == locked + released + penalty"
        );
    }

    #[test]
    fn overturn_refunds_the_bond_in_full_with_no_fee() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, false).unwrap();
        let (outcome, penalty_refunded, bond_moved) =
            e.review_appeal(M2, false).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Overturned);
        assert_eq!(penalty_refunded, SLASHED);
        assert_eq!(bond_moved, BOND, "bond refunded in full, no fee");
        assert_eq!(e.appeal_bond_paid(), 0, "counter zeroes on refund");
        assert_eq!(e.appeal_state(), AppealState::Overturned);
        assert_eq!(e.penalty_paid(), 0);
        // Only the penalty restitution accumulates in `released` — the
        // bond is never mixed in.
        assert_eq!(e.released_amount(), SLASHED);
        assert_eq!(
            e.remaining_amount() + e.released_amount() + e.penalty_paid(),
            AMOUNT,
            "principal conservation after overturn"
        );
    }

    #[test]
    fn conservation_counts_the_bond_as_additional_inflow() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        // inflow (principal + taker-locked bond) == locked + released +
        // refunded + penalty_paid + appeal_bond_paid.
        let inflow = AMOUNT as u128 + e.appeal_bond_paid() as u128;
        let sinks = e.remaining_amount() as u128
            + e.released_amount() as u128
            + e.penalty_paid() as u128
            + e.appeal_bond_paid() as u128;
        assert_eq!(inflow, sinks, "extended conservation identity");
    }

    #[test]
    fn bond_is_excluded_from_the_claimable_base_while_pending() {
        // A vesting escrow, slashed, with a bonded appeal in flight.
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_vesting(VestingSchedule::new(T0, T0 + 86_400).unwrap())
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_appeal_bond(BOND)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        let vested_end = T0 + 86_400;
        let claimable_before = e.claimable_amount(vested_end);
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        // Fully vested: priced == AMOUNT; the claimable base prices
        // only against `released` — the pending bond is invisible to
        // it (like `claim`, which additionally prices against
        // `penalty_paid`, the bond never enters either base).
        assert_eq!(
            e.claimable_amount(vested_end),
            claimable_before,
            "pending bond must not shrink the claimable base"
        );
        assert_eq!(
            e.claimable_amount(vested_end),
            AMOUNT,
            "claimable == vested - released, bond excluded"
        );
        assert_eq!(
            e.remaining_amount(),
            AMOUNT - SLASHED,
            "remaining_amount excludes the bond too"
        );
    }

    #[test]
    fn expiry_sweep_forfeits_the_bond_and_closes_the_appeal() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        assert!(!e.is_appeal_expired(DEADLINE + WINDOW), "window is inclusive");
        assert!(e.is_appeal_expired(DEADLINE + WINDOW + 1));
        let forfeited = e.expire_appeal(ALICE, DEADLINE + WINDOW + 1).unwrap();
        assert_eq!(
            forfeited, BOND,
            "the forfeited bond is returned for transfer sizing"
        );
        assert_eq!(e.appeal_bond_paid(), 0);
        assert_eq!(e.appeal_state(), AppealState::Expired);
        assert_eq!(e.penalty_paid(), SLASHED, "the slash stands");
        assert_eq!(e.released_amount(), 0, "bond never mixed into released");
        // A swept appeal is terminal: no more votes, no second sweep.
        assert_eq!(
            e.review_appeal(M1, true),
            Err(EscrowError::InvalidAppealWindow)
        );
        assert_eq!(
            e.expire_appeal(ALICE, DEADLINE + WINDOW + 2),
            Err(EscrowError::InvalidAppealWindow)
        );
        assert!(!e.is_appeal_under_review());
        assert!(!e.is_appeal_expired(DEADLINE + WINDOW + 2));
    }

    #[test]
    fn expiry_sweep_rejects_a_live_window() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let err = e.expire_appeal(ALICE, DEADLINE + WINDOW).unwrap_err();
        assert_eq!(err, EscrowError::AppealExpiryNotDue);
        assert_eq!(EscrowError::AppealExpiryNotDue.code(), 159);
        assert_eq!(e.appeal_state(), AppealState::Filed, "state unchanged");
        assert_eq!(e.appeal_bond_paid(), BOND, "bond untouched");
    }

    #[test]
    fn expiry_sweep_rejects_a_never_filed_appeal() {
        let mut e = bonded_slashed();
        assert_eq!(
            e.expire_appeal(ALICE, DEADLINE + WINDOW + 1),
            Err(EscrowError::InvalidAppealWindow)
        );
    }

    #[test]
    fn keeper_lists_the_expiry_sweep_once_the_window_lapses() {
        let id = [0xE1; 32];
        // Before the lapse: no sweep listed (the appeal is under review
        // instead — one action per unvoted panel member).
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let report = scan_keeper_actions(&[watch(id, e)], DEADLINE + WINDOW);
        assert!(
            report
                .actions
                .iter()
                .all(|a| a.kind != KeeperActionKind::ExpireAppeal),
            "no sweep while the window is live"
        );
        // After the lapse: exactly one permissionless sweep.
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let report = scan_keeper_actions(&[watch(id, e)], DEADLINE + WINDOW + 1);
        let sweeps: Vec<_> = report
            .actions
            .iter()
            .filter(|a| a.kind == KeeperActionKind::ExpireAppeal)
            .collect();
        assert_eq!(sweeps.len(), 1);
        let sweep = sweeps[0];
        assert_eq!(sweep.caller_role, "anyone");
        assert_eq!(sweep.amount, BOND, "the forfeitable bond, informational");
        assert_eq!(sweep.reason, "appeal_window_lapsed");
        assert_eq!(sweep.kind.as_str(), "expire_appeal");
    }

    #[test]
    fn snapshot_carries_the_bond_and_expiry_eligibility() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        let snap = e.snapshot(DEADLINE + WINDOW + 1);
        let json = snap.to_json();
        assert!(json.contains(&format!("\"appeal_bond\":{}", BOND)));
        assert!(json.contains(&format!("\"appeal_bond_paid\":{}", BOND)));
        assert!(json.contains("\"appeal_expiry_eligible\":true"));
        assert!(json.contains("\"appeal_state\":\"filed\""));
        let live = e.snapshot(DEADLINE + 1);
        assert!(live
            .to_json()
            .contains("\"appeal_expiry_eligible\":false"));
    }

    #[test]
    fn decode_round_trips_the_bond_fields_and_expired_state() {
        let mut e = bonded_slashed();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.expire_appeal(ALICE, DEADLINE + WINDOW + 1).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), super::ESCROW_BODY_LEN);
        // Full-state decode (AV-75 decoder path) — the decoder expects
        // the 8-byte discriminator + body.
        let mut full = crate::discriminator::vault_account_discriminator().to_vec();
        full.extend_from_slice(&bytes);
        // The two u64s before the delegation region are the bond region
        // (encode order: appeal_bond, then appeal_bond_paid) — the
        // AV-104 delegation region (37 bytes) trails them.
        let tail = &full[8 + super::ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - RENT_SWEEP_TAIL_LEN - ARBITER_FEE_TAIL_LEN - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN - super::DISPUTE_INTEREST_LEN - super::PRICE_GATE_LEN - super::PENALTY_ESCALATION_TAIL_LEN - super::COMPOUND_INTEREST_TAIL_LEN - super::SLOT_TIMELOCK_TAIL_LEN - super::RELEASE_COOLING_TAIL_LEN - super::FUNDING_TAIL_LEN - super::RENT_TOP_UP_LEN - super::DEADMAN_REGION_LEN - super::PAYOUT_SPLIT_LEN - super::INTEREST_REGION_LEN - POOL_REGION_LEN - super::SWAP_LINK_REGION_LEN - 37 - 16 - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..8 + super::ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN - super::DISPUTE_INTEREST_LEN - super::PRICE_GATE_LEN - super::PENALTY_ESCALATION_TAIL_LEN - super::COMPOUND_INTEREST_TAIL_LEN - super::SLOT_TIMELOCK_TAIL_LEN - super::RELEASE_COOLING_TAIL_LEN - super::FUNDING_TAIL_LEN - super::RENT_TOP_UP_LEN - super::DEADMAN_REGION_LEN - super::PAYOUT_SPLIT_LEN - super::INTEREST_REGION_LEN - POOL_REGION_LEN - RENT_SWEEP_TAIL_LEN - super::SWAP_LINK_REGION_LEN - 37 - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN];
        assert_eq!(&tail[..8], &BOND.to_le_bytes());
        assert_eq!(&tail[8..], &[0u8; 8], "forfeited bond zeroes the counter");
        let decoded = crate::discriminator::decode_vault_account(&full).unwrap();
        assert_eq!(decoded.appeal_bond, BOND);
        assert_eq!(decoded.appeal_bond_paid, 0);
        assert_eq!(decoded.appeal_state, AppealState::Expired);
    }

    #[test]
    fn indexed_wrapper_emits_the_expiry_event() {
        let mut e = IndexedEscrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT, [0xF1; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_appeal_bond(BOND)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        let locked = e.file_appeal(BOB, DEADLINE + 1).unwrap();
        assert_eq!(locked, BOND);
        let before = e.event_count();
        let forfeited = e.expire_appeal(ALICE, DEADLINE + WINDOW + 1).unwrap();
        assert_eq!(forfeited, BOND);
        assert_eq!(e.event_count(), before + 1);
        let expired = &e.events()[before];
        assert_eq!(expired.kind, EscrowEventKind::AppealExpired);
        assert_eq!(expired.from, EscrowState::Funded);
        assert_eq!(expired.to, EscrowState::Funded);
        assert_eq!(
            expired.amounts.penalty, BOND,
            "the forfeited bond rides amounts.penalty"
        );
        assert_eq!(expired.amounts.payout, 0);
    }

    #[test]
    fn indexed_wrapper_resolution_events_carry_the_bond() {
        // Overturn: the taker's full restitution (penalty + bond) rides
        // payout.
        let mut e = IndexedEscrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT, [0xF1; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_appeal_bond(BOND)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, false, DEADLINE + 2).unwrap();
        let (outcome, penalty_refunded, bond_moved) =
            e.review_appeal(M2, false, DEADLINE + 3).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Overturned);
        assert_eq!((penalty_refunded, bond_moved), (SLASHED, BOND));
        let resolved = e.events().last().unwrap();
        assert_eq!(resolved.kind, EscrowEventKind::AppealResolved);
        assert_eq!(
            resolved.amounts.payout,
            SLASHED + BOND,
            "penalty + bond restitution rides payout"
        );
        // Uphold: the forfeited bond rides penalty.
        let mut e = IndexedEscrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT, [0xF2; 32], T0)
            .unwrap()
            .with_slash_terms(PENALTY, DEADLINE)
            .unwrap()
            .with_appeal_window(WINDOW)
            .unwrap()
            .with_appeal_bond(BOND)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e.slash(ALICE, SLASHED, None, DEADLINE).unwrap();
        e.file_appeal(BOB, DEADLINE + 1).unwrap();
        e.review_appeal(M1, true, DEADLINE + 2).unwrap();
        let (outcome, penalty_refunded, bond_moved) =
            e.review_appeal(M2, true, DEADLINE + 3).unwrap().unwrap();
        assert_eq!(outcome, AppealOutcome::Upheld);
        assert_eq!((penalty_refunded, bond_moved), (0, BOND));
        let resolved = e.events().last().unwrap();
        assert_eq!(resolved.amounts.penalty, BOND, "forfeiture rides penalty");
        assert_eq!(resolved.amounts.payout, 0);
    }
}

// ---------------------------------------------------------------------------
// AV-83: CPI target-program allowlist tests.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod cpi_allowlist_tests {
    use super::*;
    use crate::events::IndexedEscrow;
    use crate::keeper::{assemble_cpi_invocation, WatchedEscrow};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const DEX: [u8; 32] = [0xD1; 32];
    const LENDING: [u8; 32] = [0xD2; 32];
    const EVIL: [u8; 32] = [0xE1; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_700_000_000;

    fn key(n: u8) -> Pubkey {
        [n; 32]
    }

    fn dex_invocation() -> CpiInvocation {
        CpiInvocation {
            program_id: DEX,
            accounts: vec![
                AccountMeta { pubkey: key(1), is_signer: true, is_writable: true },
                AccountMeta { pubkey: key(2), is_signer: false, is_writable: true },
            ],
            data: vec![1, 2, 3],
        }
    }

    fn funded_with_allowlist() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_cpi_allowlist(&[DEX, LENDING])
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        e
    }

    #[test]
    fn builder_binds_the_allowlist_uninitialized_only() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_cpi_allowlist(&[DEX, LENDING])
            .unwrap();
        let list = e.cpi_allowlist().expect("allowlist bound");
        assert_eq!(list.as_slice(), &[DEX, LENDING]);
        assert!(e.cpi_target_allowed(&DEX));
        assert!(e.cpi_target_allowed(&LENDING));
        assert!(!e.cpi_target_allowed(&EVIL));
        // Re-configuring a live escrow is rejected — use the governed
        // update path instead.
        let mut e = e;
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e.with_cpi_allowlist(&[DEX]).map(|_| ()).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn builder_rejects_malformed_lists() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Empty.
        let err = e.clone().with_cpi_allowlist(&[]).unwrap_err();
        assert_eq!(err, EscrowError::InvalidCpiAllowlist);
        assert_eq!(err.code(), 144);
        // Over-long.
        let nine = [[0xD1; 32]; 9];
        assert_eq!(
            e.clone().with_cpi_allowlist(&nine).unwrap_err(),
            EscrowError::InvalidCpiAllowlist
        );
        // Zero program id.
        assert_eq!(
            e.clone().with_cpi_allowlist(&[[0u8; 32]]).unwrap_err(),
            EscrowError::InvalidCpiAllowlist
        );
        // Eight (the max) is accepted.
        let eight = [[0xD1; 32], [0xD2; 32], [0xD3; 32], [0xD4; 32],
                     [0xD5; 32], [0xD6; 32], [0xD7; 32], [0xD8; 32]];
        let e8 = e.with_cpi_allowlist(&eight).unwrap();
        assert_eq!(e8.cpi_allowlist().unwrap().len, 8);
    }

    #[test]
    fn allowlisted_target_releases_normally() {
        let mut e = funded_with_allowlist();
        let inv = dex_invocation();
        let (payout, fee, receipt) = e
            .release_via_cpi(ALICE, NOW, 1_000_000, None, BOB, 0, &inv, |_| Ok(1_000_000))
            .unwrap();
        assert_eq!((payout, fee), (1_000_000, 0));
        assert_eq!(receipt.cpi_target, DEX);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn non_allowlisted_target_fails_with_invalid_cpi_target_and_rolls_back() {
        let mut e = funded_with_allowlist();
        let mut inv = dex_invocation();
        inv.program_id = EVIL;
        let err = e
            .release_via_cpi(ALICE, NOW, 1_000_000, None, BOB, 0, &inv, |_| Ok(1_000_000))
            .unwrap_err();
        // Deliberately the shape-rejection code (120), not the config
        // code (144): one code for every invocation/target rejection.
        assert_eq!(err, EscrowError::InvalidCpiTarget);
        assert_eq!(err.code(), 120);
        // Full rollback: nothing observable changed.
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.released_amount(), 0);
        assert_eq!(e.fees_paid(), 0);
    }

    #[test]
    fn no_allowlist_means_no_restriction() {
        // Backward compatible: escrows without the opt-in accept any
        // well-formed target.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(e.cpi_allowlist(), None);
        assert!(e.cpi_target_allowed(&EVIL));
        let mut inv = dex_invocation();
        inv.program_id = EVIL;
        e.release_via_cpi(ALICE, NOW, 1_000_000, None, BOB, 0, &inv, |_| Ok(1_000_000))
            .unwrap();
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn allowlist_check_runs_after_shape_check() {
        // A malformed invocation against an allowlisted escrow still
        // fails on shape first — the check order is unchanged.
        let mut e = funded_with_allowlist();
        let mut inv = dex_invocation();
        inv.program_id = [0u8; 32]; // malformed AND non-allowlisted
        assert_eq!(
            e.release_via_cpi(ALICE, NOW, 100, None, BOB, 0, &inv, |_| Ok(100))
                .unwrap_err(),
            EscrowError::InvalidCpiTarget
        );
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn update_requires_both_parties_always() {
        let mut e = funded_with_allowlist();
        // Initializer alone is not enough — stricter than
        // update_payout_allowlist's dual-sig-only governance.
        assert_eq!(
            e.update_cpi_allowlist(ALICE, MALLORY, &[DEX]),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            e.update_cpi_allowlist(MALLORY, BOB, &[DEX]),
            Err(EscrowError::Unauthorized)
        );
        // Both parties: the list is replaced wholesale.
        e.update_cpi_allowlist(ALICE, BOB, &[EVIL]).unwrap();
        assert_eq!(e.cpi_allowlist().unwrap().as_slice(), &[EVIL]);
        assert!(!e.cpi_target_allowed(&DEX));
        assert!(e.cpi_target_allowed(&EVIL));
        // Empty clears back to None (no restriction).
        e.update_cpi_allowlist(ALICE, BOB, &[]).unwrap();
        assert_eq!(e.cpi_allowlist(), None);
        assert!(e.cpi_target_allowed(&EVIL));
        // Failed updates keep the old list.
        assert_eq!(
            e.update_cpi_allowlist(ALICE, BOB, &[[0u8; 32]]),
            Err(EscrowError::InvalidCpiAllowlist)
        );
        assert_eq!(e.cpi_allowlist(), None);
    }

    #[test]
    fn update_state_gating_and_pause_first() {
        // Uninitialized works too.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.update_cpi_allowlist(ALICE, BOB, &[DEX]).unwrap();
        assert_eq!(e.cpi_allowlist().unwrap().as_slice(), &[DEX]);
        // Terminal states are locked out.
        let mut e = funded_with_allowlist();
        e.release(ALICE, NOW, 1_000_000, None, BOB).unwrap();
        assert_eq!(e.state(), EscrowState::Released);
        assert_eq!(
            e.update_cpi_allowlist(ALICE, BOB, &[DEX]),
            Err(EscrowError::InvalidStateTransition)
        );
        // Pause gate first — a paused escrow fails fast even for the
        // legitimate parties.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_cpi_allowlist(&[DEX, LENDING])
            .unwrap()
            .with_pause_authority(ALICE)
            .unwrap();
        e.fund(ALICE, NOW).unwrap();
        e.pause(ALICE, None).unwrap();
        assert_eq!(
            e.update_cpi_allowlist(ALICE, BOB, &[DEX]),
            Err(EscrowError::Paused)
        );
    }

    #[test]
    fn update_emits_cpi_allowlist_updated_only_on_change() {
        let mut ix =
            IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xE5; 32], NOW).unwrap();
        ix.fund(ALICE, NOW + 1).unwrap();
        let before = ix.event_count();
        ix.update_cpi_allowlist(ALICE, BOB, &[DEX, LENDING], NOW + 2)
            .unwrap();
        assert_eq!(ix.event_count(), before + 1);
        let ev = ix.events().last().expect("event emitted");
        assert_eq!(ev.kind, EscrowEventKind::CpiAllowlistUpdated);
        assert_eq!(ev.kind.discriminant(), 43);
        assert_eq!(ev.kind.name(), "cpi_allowlist_updated");
        // Same-list update is a silent no-op.
        ix.update_cpi_allowlist(ALICE, BOB, &[DEX, LENDING], NOW + 3)
            .unwrap();
        assert_eq!(ix.event_count(), before + 1);
        // Clearing the list also emits (a real governance change).
        ix.update_cpi_allowlist(ALICE, BOB, &[], NOW + 4).unwrap();
        assert_eq!(ix.event_count(), before + 2);
    }

    #[test]
    fn keeper_assembly_rejects_non_allowlisted_targets() {
        let watched = WatchedEscrow {
            escrow_id: [0xE5; 32],
            escrow: funded_with_allowlist(),
            reference: None,
            vault_derivation: None,
            pending_intent: None,
        };
        // Allowlisted target assembles fine.
        let inv = assemble_cpi_invocation(
            &watched,
            DEX,
            vec![AccountMeta { pubkey: key(1), is_signer: true, is_writable: true }],
            vec![9],
        )
        .unwrap();
        assert_eq!(inv.program_id, DEX);
        // Non-allowlisted target fails at assembly — the bundle never
        // carries a doomed invocation.
        let err = assemble_cpi_invocation(
            &watched,
            EVIL,
            vec![AccountMeta { pubkey: key(1), is_signer: true, is_writable: true }],
            vec![9],
        )
        .unwrap_err();
        assert_eq!(err, EscrowError::InvalidCpiTarget);
        // Malformed shape fails at assembly too (shape first, like the
        // state machine).
        let err = assemble_cpi_invocation(&watched, [0u8; 32], vec![], vec![])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidCpiTarget);
        // No allowlist: assembly accepts any well-formed target.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        let watched = WatchedEscrow { escrow_id: [0xE5; 32], escrow: e, reference: None, vault_derivation: None, pending_intent: None };
        assemble_cpi_invocation(
            &watched,
            EVIL,
            vec![AccountMeta { pubkey: key(1), is_signer: true, is_writable: true }],
            vec![],
        )
        .unwrap();
    }

    #[test]
    fn allowlist_persists_in_the_serialized_tail() {
        // The allowlist sits just before the AV-84 multisig region:
        // discriminant at offset 3495, then eight 32-byte slots and
        // the count byte.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_cpi_allowlist(&[DEX, LENDING])
            .unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        assert_eq!(bytes.len(), 7655); // AV-195: +309 recovery, AV-196: +1 jury size
        assert_eq!(bytes[3896], 1, "Some discriminant");
        assert_eq!(&bytes[3897..3897 + 32], &DEX);
        assert_eq!(&bytes[3897 + 32..3897 + 64], &LENDING);
        assert_eq!(&bytes[3897 + 64..3897 + 256], &[0u8; 192]);
        assert_eq!(bytes[3897 + 256], 2, "count byte");
        // A vault without the opt-in zero-fills the region.
        let plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&plain);
        assert_eq!(bytes[3896], 0, "None discriminant");
        assert_eq!(&bytes[3496..3496 + 257], &[0u8; 257]);
        // The field name is the twenty-seventh-from-last VAULT_FIELDS entry
        // (AV-84 appended the multisig region after it, AV-86 the
        // 4-field appeal region after that, AV-90 the vesting curve
        // after that, AV-91 the 3-field evidence-commitment region
        // after that, AV-95 the basket region after that, AV-96 the
        // payout denylist region after that, AV-97 the auction region
        // after that, AV-99 the transfer-hook region after that,
        // AV-100 the streaming-fee region after that, AV-103 the
        // appeal-bond region after that, AV-104 the delegation region
        // after that, AV-105 the swap-link region after that, AV-106
        // the insurance-pool region after that, AV-107 the interest
        // region after that, AV-108 the payout-split region after
        // that, AV-109 the deadman region after that, AV-110 the
        // rent top-up counter after that, AV-111 the tranched-funding
        // region after that, AV-112 the release-cooling tail after
        // that, AV-113 the price-gate tail after that, AV-115 the
        // slot-timelock tail after that, AV-116 the compound-interest
        // tail after that, AV-117 the dispute-interest tail after
        // that, AV-121 the claim-cooldown tail after that, AV-122
        // the counter-offer tail after that, AV-123 the intent nonce
        // tail after that).
        assert_eq!(VAULT_FIELDS[VAULT_FIELDS.len() - (63+16)].0, "cpi_allowlist");
        assert_eq!(VAULT_FIELDS[VAULT_FIELDS.len() - (63+16)].2, 1 + CPI_ALLOWLIST_LEN);
    }
}

// ---------- AV-84: Squads multisig authority adapter ----------
mod multisig_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const VAULT_PDA: [u8; 32] = [0x5A; 32];
    const CREATE_KEY: [u8; 32] = [0xC4; 32];
    const ESCROW_PROGRAM: [u8; 32] = [0xE9; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_700_000_000;

    fn bound() -> MultisigAuthority {
        MultisigAuthority::new(SQUADS_V4_PROGRAM_ID, VAULT_PDA, 2).unwrap()
    }

    fn bound_escrow() -> Escrow {
        Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_multisig_authority(SQUADS_V4_PROGRAM_ID, VAULT_PDA, 2)
            .unwrap()
    }

    #[test]
    fn builder_binds_program_id_authority_and_threshold() {
        let e = bound_escrow();
        let b = e.multisig_authority().unwrap();
        assert_eq!(b.program_id, SQUADS_V4_PROGRAM_ID);
        assert_eq!(b.authority, VAULT_PDA);
        assert_eq!(b.threshold, 2);
        // Default: no binding.
        let plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        assert_eq!(plain.multisig_authority(), None);
    }

    #[test]
    fn builder_rejects_zero_inputs() {
        let base = || Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        assert_eq!(
            base().with_multisig_authority([0u8; 32], VAULT_PDA, 2).unwrap_err(),
            EscrowError::InvalidMultisigAuthority
        );
        assert_eq!(
            base()
                .with_multisig_authority(SQUADS_V4_PROGRAM_ID, [0u8; 32], 2)
                .unwrap_err(),
            EscrowError::InvalidMultisigAuthority
        );
        assert_eq!(
            base()
                .with_multisig_authority(SQUADS_V4_PROGRAM_ID, VAULT_PDA, 0)
                .unwrap_err(),
            EscrowError::InvalidMultisigAuthority
        );
    }

    #[test]
    fn builder_is_uninitialized_only() {
        let mut e = bound_escrow();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e.with_multisig_authority(SQUADS_V4_PROGRAM_ID, VAULT_PDA, 2)
                .unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn error_code_is_145_and_stable() {
        assert_eq!(EscrowError::InvalidMultisigAuthority.code(), 145);
        assert!(EscrowError::all().contains(&EscrowError::InvalidMultisigAuthority));
    }

    #[test]
    fn squads_v4_program_id_matches_base58() {
        // The hardcoded bytes decode to the documented mainnet program
        // id (via the test-only base58 encoder).
        assert_eq!(
            super::base58_tests::base58_encode(&SQUADS_V4_PROGRAM_ID),
            "SQDS4ep65T869zMMBKyuUq6aD6EgTu8psMjkvj52pCf"
        );
    }

    #[test]
    fn squads_v4_seed_assembly_matches_documented_derivation() {
        // Multisig PDA: ["multisig", create_key].
        assert_eq!(
            squads_v4_multisig_seeds(&CREATE_KEY),
            vec![b"multisig".to_vec(), CREATE_KEY.to_vec()]
        );
        // Vault PDA: ["multisig", multisig, "vault", vault_index].
        assert_eq!(
            squads_v4_vault_seeds(&VAULT_PDA, 0),
            vec![
                b"multisig".to_vec(),
                VAULT_PDA.to_vec(),
                b"vault".to_vec(),
                vec![0u8],
            ]
        );
        assert_eq!(
            squads_v4_vault_seeds(&VAULT_PDA, 3)[3],
            vec![3u8],
            "vault index is the u8 seed tail"
        );
    }

    #[test]
    fn squads_seeds_derive_through_unified_find_program_address() {
        // AV-92 convergence: the multisig seed assembly feeds the
        // unified derivation tool — no caller hand-rolls a bump
        // search anymore.
        let seeds = squads_v4_multisig_seeds(&CREATE_KEY);
        let refs: Vec<&[u8]> = seeds.iter().map(|s| s.as_slice()).collect();
        let (addr, bump) = crate::find_program_address(&refs, &SQUADS_V4_PROGRAM_ID).unwrap();
        assert_eq!(
            addr,
            crate::derive_vault_address(&refs, &SQUADS_V4_PROGRAM_ID, bump).unwrap()
        );
        assert!(!crate::is_on_ed25519_curve(&addr));
    }

    #[test]
    fn assemble_and_validate_multisig_escrow_call() {
        let rest = vec![AccountMeta {
            pubkey: [0x11; 32],
            is_signer: false,
            is_writable: true,
        }];
        let inv = assemble_multisig_escrow_call(ESCROW_PROGRAM, VAULT_PDA, rest, vec![1, 2, 3]);
        // The authority PDA leads as a signer.
        assert_eq!(inv.program_id, ESCROW_PROGRAM);
        assert_eq!(inv.accounts[0].pubkey, VAULT_PDA);
        assert!(inv.accounts[0].is_signer);
        assert_eq!(inv.accounts.len(), 2);
        // Well-formed: validates.
        validate_multisig_escrow_call(&inv, &ESCROW_PROGRAM, &bound()).unwrap();
    }

    #[test]
    fn validate_rejects_mistargeted_or_unsigned_proposals() {
        let rest = vec![AccountMeta {
            pubkey: [0x11; 32],
            is_signer: false,
            is_writable: true,
        }];
        let inv = assemble_multisig_escrow_call(ESCROW_PROGRAM, VAULT_PDA, rest, vec![]);
        // Wrong escrow program: the proposal would execute elsewhere
        // after votes are cast.
        assert_eq!(
            validate_multisig_escrow_call(&inv, &[0x99; 32], &bound()).unwrap_err(),
            EscrowError::InvalidCpiTarget
        );
        // Authority not a signer: the multisig could not authorize the
        // escrow transition.
        let no_sig = CpiInvocation {
            program_id: ESCROW_PROGRAM,
            accounts: vec![
                AccountMeta { pubkey: VAULT_PDA, is_signer: false, is_writable: true },
                AccountMeta { pubkey: [0x11; 32], is_signer: true, is_writable: false },
            ],
            data: vec![],
        };
        assert_eq!(
            validate_multisig_escrow_call(&no_sig, &ESCROW_PROGRAM, &bound()).unwrap_err(),
            EscrowError::InvalidMultisigAuthority
        );
        // Malformed shape still fails as InvalidCpiTarget.
        let empty = CpiInvocation {
            program_id: ESCROW_PROGRAM,
            accounts: vec![],
            data: vec![],
        };
        assert_eq!(
            validate_multisig_escrow_call(&empty, &ESCROW_PROGRAM, &bound()).unwrap_err(),
            EscrowError::InvalidCpiTarget
        );
    }

    #[test]
    fn binding_persists_in_the_serialized_tail() {
        // The multisig region keeps its offset (appended-last fields
        // never move earlier offsets): discriminant at offset 3753
        // (3846 - 26 - 67), then the 32-byte program id, the 32-byte
        // authority PDA, and the u16 threshold — the 26-byte AV-86
        // appeal region is the new tail after it.
        let e = bound_escrow();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        assert_eq!(bytes.len(), 7655); // AV-195: +309 recovery, AV-196: +1 jury size
        assert_eq!(bytes[4154], 1, "Some discriminant");
        assert_eq!(&bytes[4155..4155 + 32], &SQUADS_V4_PROGRAM_ID);
        assert_eq!(&bytes[4155 + 32..4155 + 64], &VAULT_PDA);
        assert_eq!(
            u16::from_le_bytes(bytes[4155 + 64..4155 + 66].try_into().unwrap()),
            2,
            "threshold"
        );
        // A vault without the binding zero-fills the region.
        let plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&plain);
        assert_eq!(bytes[4154], 0, "None discriminant");
        assert_eq!(&bytes[4155..4221], &[0u8; 66]);
        // The field name is the twenty-sixth-from-last VAULT_FIELDS entry
        // (AV-86 appended the 4-field appeal region after it, AV-90
        // the vesting-curve region after that, AV-91 the 3-field
        // evidence-commitment region after that, AV-95 the basket
        // region after that, AV-96 the payout denylist region after
        // that, AV-97 the auction region after that, AV-99 the
        // transfer-hook region after that, AV-100 the streaming-fee
        // region after that, AV-103 the appeal-bond region after
        // that, AV-104 the delegation region after that, AV-105 the
        // swap-link region after that, AV-106 the insurance-pool
        // region after that).
        assert_eq!(VAULT_FIELDS[VAULT_FIELDS.len() - (62+16)].0, "multisig_authority");
        assert_eq!(VAULT_FIELDS[VAULT_FIELDS.len() - (62+16)].2, 1 + MULTISIG_AUTHORITY_LEN);
        assert_eq!(MULTISIG_AUTHORITY_LEN, 66);
    }

    #[test]
    fn decode_round_trips_the_binding() {
        let e = bound_escrow();
        let bytes = super::account_space_tests::encode_escrow(&e);
        let mut full = vault_account_discriminator().to_vec();
        full.extend_from_slice(&bytes);
        let decoded = decode_vault_account(&full).unwrap();
        assert_eq!(decoded.multisig_authority(), Some(bound()));
        // A bad option discriminant is rejected, not misread.
        let mut bad = full.clone();
        bad[8 + 4154] = 7;
        assert!(decode_vault_account(&bad).is_err());
    }

    #[test]
    fn snapshot_and_keeper_carry_the_binding() {
        let mut e = bound_escrow();
        e.fund(ALICE, NOW).unwrap();
        let snap = e.snapshot(NOW);
        assert_eq!(snap.multisig_authority, Some(bound()));
        let json = snap.to_json();
        assert!(json.contains("\"multisig_authority\":{\"program_id\":\""));
        assert!(json.contains("\"threshold\":2}"));
        // Keeper actions surface the binding so the keeper routes the
        // call through the multisig program.
        let watched = WatchedEscrow {
            escrow_id: [0x1D; 32],
            escrow: e,
            reference: None,
            vault_derivation: None,
            pending_intent: None,
        };
        let report = scan_keeper_actions(&[watched], EXPIRES_AT + 100);
        assert!(!report.actions.is_empty());
        assert_eq!(report.actions[0].multisig_authority, Some(bound()));
        assert!(report.to_json().contains("\"multisig_authority\":{\"program_id\":\""));
    }

    #[test]
    fn zero_trust_authority_check_is_key_equality() {
        // The escrow never calls the multisig program: when the
        // initializer IS the vault PDA, the normal key-equality check
        // authorizes it — the threshold vote happened off-band inside
        // Squads.
        let mut e = Escrow::initialize(VAULT_PDA, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_multisig_authority(SQUADS_V4_PROGRAM_ID, VAULT_PDA, 2)
            .unwrap();
        e.fund(VAULT_PDA, NOW).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
    }
}

// ---------------------------------------------------------------------------
// AV-100: streaming fee on funded time.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod streaming_fee_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const FUND_AT: u64 = 1_700_000_000;

    fn streaming_escrow(rate: u64) -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_streaming_fee(rate)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e
    }

    #[test]
    fn builder_matrix() {
        // Happy path: Uninitialized, any u64 rate (0 = off, like fee_bps).
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_streaming_fee(10)
            .unwrap();
        assert_eq!(e.streaming_fee_rate(), 10);
        assert_eq!(e.streaming_fees_accrued(), 0);
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_streaming_fee(0)
            .unwrap();
        assert_eq!(e.streaming_fee_rate(), 0);
        // Default is off (backward compatible).
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX).unwrap();
        assert_eq!(e.streaming_fee_rate(), 0);
        // Builder is Uninitialized-only.
        let mut funded = streaming_escrow(10);
        assert_eq!(
            funded.with_streaming_fee(20),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn release_deducts_accrued_slice_and_folds_into_fee() {
        // rate 10/s, 100s funded -> 1_000 accrued.
        let mut e = streaming_escrow(10);
        let (payout, fee) = e.release(ALICE, FUND_AT + 100, 1_000_000, None, BOB).unwrap();
        assert_eq!(fee, 1_000);
        assert_eq!(payout, 999_000);
        assert_eq!(e.streaming_fees_accrued(), 1_000);
        assert_eq!(e.fees_paid(), 1_000);
    }

    #[test]
    fn no_double_billing_across_payouts() {
        let mut e = streaming_escrow(10);
        let (_, fee1) = e.release(ALICE, FUND_AT + 100, 600_000, None, BOB).unwrap();
        assert_eq!(fee1, 1_000);
        // Another 100s pass: only the new 1_000 is billed.
        let (_, fee2) = e.release(ALICE, FUND_AT + 200, 400_000, None, BOB).unwrap();
        assert_eq!(fee2, 1_000);
        assert_eq!(e.streaming_fees_accrued(), 2_000);
        // Settling at the same timestamp bills nothing new.
        let mut e2 = streaming_escrow(10);
        let (_, f1) = e2.release(ALICE, FUND_AT + 100, 500_000, None, BOB).unwrap();
        let (_, f2) = e2.release(ALICE, FUND_AT + 100, 500_000, None, BOB).unwrap();
        assert_eq!((f1, f2), (1_000, 0));
    }

    #[test]
    fn charge_caps_at_net_payout_and_remainder_stays_billable() {
        // rate 10/s, 100s -> 1_000 due, but the payout nets only 100.
        let mut e = streaming_escrow(10);
        let (payout, fee) = e.release(ALICE, FUND_AT + 100, 100, None, BOB).unwrap();
        assert_eq!(fee, 100);
        assert_eq!(payout, 0);
        assert_eq!(e.streaming_fees_accrued(), 100);
        // The unbilled 900 is still owed: a later payout picks it up.
        let (_, fee2) = e.release(ALICE, FUND_AT + 100, 999_900, None, BOB).unwrap();
        assert_eq!(fee2, 900);
        assert_eq!(e.streaming_fees_accrued(), 1_000);
    }

    #[test]
    fn bps_fee_applies_first_then_streaming_on_remainder() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_protocol_fee(100) // 1%
            .unwrap()
            .with_streaming_fee(10)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        // Gross 1_000_000: bps fee 10_000 first, streaming 1_000 on the
        // remainder (capped at the remainder, so no interaction).
        let (payout, fee) = e.release(ALICE, FUND_AT + 100, 1_000_000, None, BOB).unwrap();
        assert_eq!(fee, 11_000);
        assert_eq!(payout, 989_000);
        assert_eq!(e.streaming_fees_accrued(), 1_000);
        assert_eq!(e.fees_paid(), 11_000);
    }

    #[test]
    fn disputed_anchor_freezes_at_disputed_at() {
        const ARBITER: [u8; 32] = [0xCC; 32];
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_streaming_fee(10)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e.escalate(ALICE, FUND_AT + 100, e.remaining_amount(), None, None, 0).unwrap();
        // 900 more seconds pass before the arbiter resolves — the
        // streaming fee must NOT accrue through the dispute.
        let (payout, fee, _) = e.resolve(ARBITER, 1_000_000, FUND_AT + 100, None, None, BOB).unwrap();
        assert_eq!(fee, 1_000, "accrual froze at disputed_at");
        assert_eq!(payout, 999_000);
    }

    #[test]
    fn zero_rate_is_a_noop() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX).unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let (payout, fee) = e.release(ALICE, FUND_AT + 1_000_000, 1_000_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (1_000_000, 0));
        assert_eq!(e.streaming_fees_accrued(), 0);
    }

    #[test]
    fn saturation_never_overflows() {
        // u64::MAX rate over u64::MAX seconds: u128 math saturates,
        // the charge caps at the net payout.
        let mut e = streaming_escrow(u64::MAX);
        let (payout, fee) = e.release(ALICE, u64::MAX, 1_000_000, None, BOB).unwrap();
        assert_eq!(fee, 1_000_000);
        assert_eq!(payout, 0);
        assert_eq!(e.streaming_fees_accrued(), 1_000_000);
    }

    #[test]
    fn refunds_never_carry_the_streaming_fee() {
        // AV-17's rule extended: only taker-received value is feeable.
        let mut e = streaming_escrow(10);
        e.cancel(ALICE, None, ALICE, 0).unwrap();
        assert_eq!(e.streaming_fees_accrued(), 0);
        assert_eq!(e.fees_paid(), 0);
    }

    #[test]
    fn fields_round_trip_through_encode_decode() {
        let mut e = streaming_escrow(10);
        e.release(ALICE, FUND_AT + 100, 600_000, None, BOB).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        let tail = &bytes[ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - PRICE_GATE_LEN - PENALTY_ESCALATION_TAIL_LEN - COMPOUND_INTEREST_TAIL_LEN - SLOT_TIMELOCK_TAIL_LEN - RELEASE_COOLING_TAIL_LEN - FUNDING_TAIL_LEN - RENT_TOP_UP_LEN - DEADMAN_REGION_LEN - PAYOUT_SPLIT_LEN - INTEREST_REGION_LEN - POOL_REGION_LEN - SWAP_LINK_REGION_LEN - APPEAL_BOND_REGION_LEN - DELEGATION_REGION_LEN - STREAMING_FEE_REGION_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..];
        assert_eq!(u64::from_le_bytes(tail[..8].try_into().unwrap()), 10);
        assert_eq!(u64::from_le_bytes(tail[8..16].try_into().unwrap()), 1_000);
        let mut account = vec![0u8; 8 + ESCROW_BODY_LEN];
        account[..8].copy_from_slice(&vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = decode_vault_account(&account).unwrap();
        assert_eq!(decoded.streaming_fee_rate(), 10);
        assert_eq!(decoded.streaming_fees_accrued(), 1_000);
    }
}

// ---------- AV-107: interest-bearing escrow ----------
//
// Opt-in APR on the locked principal (`with_interest`), lazy accrual
// settled from an explicit `now` at each fund-moving transition,
// harvested via `claim_interest` (taker-only) or bundled with a
// taker payout. `interest_paid` is the new sink in the extended
// conservation identity — principal (`released`) and yield
// (`interest_paid`) stay separately auditable.
#[cfg(test)]
mod interest_tests {
    use super::*;
    use crate::discriminator::{decode_vault_account, vault_account_discriminator};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const ARBITER: [u8; 32] = [0xA8; 32];
    const FUND_AT: u64 = 1_700_000_000;
    const YEAR: u64 = 31_536_000; // == Escrow::SECONDS_PER_YEAR

    fn interest_escrow(rate_bps: u16) -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(rate_bps)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e
    }

    #[test]
    fn builder_matrix() {
        // Happy path: 500 bps = 5% APR.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(500)
            .unwrap();
        assert_eq!(e.interest_rate_bps(), 500);
        assert_eq!(e.interest_accrued(), 0);
        assert_eq!(e.interest_paid(), 0);
        // 0 disables (backward compatible); the ceiling is 10000.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(0)
            .unwrap();
        assert_eq!(e.interest_rate_bps(), 0);
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(10_000)
            .unwrap();
        assert_eq!(e.interest_rate_bps(), 10_000);
        // Default is off.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX).unwrap();
        assert_eq!(e.interest_rate_bps(), 0);
        // Above 100% APR is rejected (code 165).
        let err = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(10_001)
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidInterestRate);
        assert_eq!(err.code(), 165);
        // Builder is Uninitialized-only.
        let funded = interest_escrow(500);
        assert_eq!(
            funded.with_interest(500).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn accrual_math_is_linear_in_time_and_rate() {
        // 1M principal at 5% APR for exactly one year: 50_000.
        let mut e = interest_escrow(500);
        let paid = e.claim_interest(BOB, FUND_AT + YEAR).unwrap();
        assert_eq!(paid, 50_000);
        assert_eq!(e.interest_paid(), 50_000);
        assert_eq!(e.interest_accrued(), 0);
        // Half the time -> half the yield; double the rate -> double.
        let mut e = interest_escrow(500);
        assert_eq!(e.claim_interest(BOB, FUND_AT + YEAR / 2).unwrap(), 25_000);
        let mut e = interest_escrow(1_000);
        assert_eq!(e.claim_interest(BOB, FUND_AT + YEAR).unwrap(), 100_000);
        // Zero rate accrues nothing even over a year.
        let e = interest_escrow(0);
        assert_eq!(e.interest_rate_bps(), 0);
    }

    #[test]
    fn u128_math_cannot_overflow() {
        // u64::MAX principal at 100% APR for ~forever: the u128
        // product is astronomic, but saturating math caps the claim
        // at u64::MAX instead of panicking or wrapping.
        let mut e = Escrow::initialize(ALICE, BOB, u64::MAX, u64::MAX)
            .unwrap()
            .with_interest(10_000)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let paid = e.claim_interest(BOB, u64::MAX).unwrap();
        assert_eq!(paid, u64::MAX);
        assert_eq!(e.interest_paid(), u64::MAX);
        assert_eq!(e.interest_accrued(), 0);
    }

    #[test]
    fn accrual_is_lazy_no_tick_between_transitions() {
        // A year passes with no transition: nothing is booked until a
        // transition settles the clock.
        let mut e = interest_escrow(500);
        assert_eq!(e.interest_accrued(), 0);
        // The harvest settles the whole window at once — exact to the
        // second, no per-block ticking. 1M * 500bps * 1s floors to 0;
        // 1000s accrue 1.
        assert_eq!(e.claim_interest(BOB, FUND_AT + 1).unwrap(), 0);
        assert_eq!(e.claim_interest(BOB, FUND_AT + 1001).unwrap(), 1);
    }

    #[test]
    fn claim_interest_is_taker_only() {
        let mut e = interest_escrow(500);
        assert_eq!(
            e.claim_interest(ALICE, FUND_AT + YEAR).unwrap_err(),
            EscrowError::Unauthorized
        );
        assert_eq!(
            e.claim_interest(MALLORY, FUND_AT + YEAR).unwrap_err(),
            EscrowError::Unauthorized
        );
        // A rejected harvest touches nothing.
        assert_eq!(e.interest_accrued(), 0);
        assert_eq!(e.interest_paid(), 0);
    }

    #[test]
    fn claim_interest_requires_opt_in() {
        // No rate configured: InterestNotEnabled (code 166) — distinct
        // from a zero harvest.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX).unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let err = e.claim_interest(BOB, FUND_AT + YEAR).unwrap_err();
        assert_eq!(err, EscrowError::InterestNotEnabled);
        assert_eq!(err.code(), 166);
    }

    #[test]
    fn claim_interest_zero_harvest_is_ok() {
        // Configured but nothing earned yet: Ok(0), not an error — a
        // keeper crank that finds nothing due is not a failure.
        let mut e = interest_escrow(500);
        assert_eq!(e.claim_interest(BOB, FUND_AT).unwrap(), 0);
        assert_eq!(e.interest_paid(), 0);
    }

    #[test]
    fn claim_interest_rejects_non_funded_states() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(500)
            .unwrap();
        assert_eq!(
            e.claim_interest(BOB, FUND_AT).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn release_bundles_accrued_interest_fee_free() {
        // 10% protocol fee: the fee slices the principal payout only;
        // the 5% yield leg rides fee-free.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_protocol_fee(1_000)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let (taker_payout, fee) = e.release(ALICE, FUND_AT + YEAR, 1_000_000, None, BOB).unwrap();
        assert_eq!(fee, 100_000, "fee is 10% of principal only");
        assert_eq!(
            taker_payout,
            900_000 + 50_000,
            "principal net of fee plus the full yield"
        );
        assert_eq!(e.interest_paid(), 50_000);
        assert_eq!(e.interest_accrued(), 0);
        // The principal counter keeps the gross — interest never
        // leaks into `released`.
        assert_eq!(e.released_amount(), 1_000_000);
        assert_eq!(e.fees_paid(), 100_000);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn partial_release_shrinks_the_accrual_base() {
        // Released funds stop earning: after releasing half, the
        // second year accrues on 500_000, not 1M.
        let mut e = interest_escrow(500);
        let (payout, _) = e.release(ALICE, FUND_AT, 500_000, None, BOB).unwrap();
        assert_eq!(payout, 500_000, "no time elapsed — no yield yet");
        assert_eq!(e.claim_interest(BOB, FUND_AT + YEAR).unwrap(), 25_000);
    }

    #[test]
    fn cancel_forfeits_the_outstanding_claim() {
        // A year of yield is outstanding; the initializer walks away.
        // The cancelled deal unwinds to the pre-deal state: the claim
        // is voided, `interest_paid` stays untouched (forfeiture is
        // distinguishable from a payout in the audit trail).
        let mut e = interest_escrow(500);
        e.cancel(ALICE, None, ALICE, 0).unwrap();
        assert_eq!(e.state(), EscrowState::Cancelled);
        assert_eq!(e.interest_accrued(), 0);
        assert_eq!(e.interest_paid(), 0);
    }

    #[test]
    fn cancel_expired_forfeits_the_outstanding_claim() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, FUND_AT + 100)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e.cancel_expired(BOB, FUND_AT + 200, None, ALICE).unwrap();
        assert_eq!(e.state(), EscrowState::Cancelled);
        assert_eq!(e.interest_accrued(), 0);
        assert_eq!(e.interest_paid(), 0);
    }

    #[test]
    fn dispute_window_accrues_and_claim_splits_pro_rata() {
        // AV-119: 36.5 days to the dispute: 5_000 of yield. Resolving
        // at disputed_at leaves an empty dispute window, so the claim
        // is exactly the 5_000 — and the settlement splits it pro-rata
        // by taker_amount / remaining: 600_000 / 1_000_000 of the claim
        // rides the taker payout, the rest rides the refund.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 600_000, disputed_at, None, None, BOB).unwrap();
        assert_eq!(fee, 0);
        assert_eq!(taker_payout, 600_000 + 3_000, "taker's 60% of the claim");
        assert_eq!(refund, 400_000 + 2_000, "initializer's 40% of the claim");
        assert_eq!(e.interest_paid(), 3_000);
        assert_eq!(e.dispute_interest(), 2_000);
        assert_eq!(e.interest_accrued(), 0, "claim zeroed at settlement");
        assert_eq!(e.state(), EscrowState::Settled);
    }

    #[test]
    fn dispute_window_accrual_grows_the_claim() {
        // AV-119: the [disputed_at, resolved_at] window accrues on the
        // locked remainder at the AV-107 rate — a full year of dispute
        // on 1M at 5% adds 50_000 to the 5_000 pre-dispute claim.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        let resolved_at = disputed_at + YEAR;
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 600_000, resolved_at, None, None, BOB).unwrap();
        assert_eq!(fee, 0);
        // Total claim 55_000; taker's 60% = 33_000, initializer's 40% =
        // 22_000.
        assert_eq!(taker_payout, 600_000 + 33_000);
        assert_eq!(refund, 400_000 + 22_000);
        assert_eq!(e.interest_paid(), 33_000);
        assert_eq!(e.dispute_interest(), 22_000);
        assert_eq!(e.interest_accrued(), 0);
    }

    #[test]
    fn taker_full_win_takes_all_interest() {
        // AV-119: taker_amount == remaining — the taker takes the whole
        // claim with the principal (the pre-AV-119 behavior, unchanged).
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 1_000_000, disputed_at, None, None, BOB).unwrap();
        assert_eq!((taker_payout, fee, refund), (1_005_000, 0, 0));
        assert_eq!(e.interest_paid(), 5_000);
        assert_eq!(e.dispute_interest(), 0, "no initializer share on a taker full win");
    }

    #[test]
    fn initializer_full_win_refunds_all_interest() {
        // AV-119: taker_amount == 0 — the whole claim rides the refund
        // back to the initializer (pre-AV-119 it went to the taker).
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 0, disputed_at, None, None, BOB).unwrap();
        assert_eq!((taker_payout, fee, refund), (0, 0, 1_005_000));
        assert_eq!(e.interest_paid(), 0, "no taker share on an initializer full win");
        assert_eq!(e.dispute_interest(), 5_000);
    }

    #[test]
    fn zero_rate_means_zero_dispute_interest() {
        // No rate configured: the settlement is a no-op for the yield
        // legs — every pre-AV-119 escrow takes this branch.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e.escalate(ALICE, FUND_AT + 1_000, e.remaining_amount(), None, None, 0).unwrap();
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 600_000, FUND_AT + YEAR, None, None, BOB).unwrap();
        assert_eq!((taker_payout, fee, refund), (600_000, 0, 400_000));
        assert_eq!(e.interest_paid(), 0);
        assert_eq!(e.dispute_interest(), 0);
    }

    #[test]
    fn panel_settling_vote_uses_the_same_attribution() {
        // AV-119: the panel's settling vote runs the shared helper —
        // the same pro-rata rule as `resolve`.
        const M1: [u8; 32] = [0xC1; 32];
        const M2: [u8; 32] = [0xC2; 32];
        const M3: [u8; 32] = [0xC3; 32];
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter_panel(&[M1, M2, M3], 2)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        assert_eq!(
            e.submit_panel_judgment(M1, 600_000, disputed_at, None, None, BOB).unwrap(),
            None,
            "first vote does not settle"
        );
        let settled = e
            .submit_panel_judgment(M2, 600_000, disputed_at, None, None, BOB)
            .unwrap()
            .expect("second matching vote settles");
        assert_eq!(settled, (603_000, 0, 402_000));
        assert_eq!(e.interest_paid(), 3_000);
        assert_eq!(e.dispute_interest(), 2_000);
        assert_eq!(e.state(), EscrowState::Settled);
    }

    #[test]
    fn compound_escrow_folds_dispute_yield_into_principal() {
        // AV-119 / AV-117 mutual exclusion: on a compound-interest
        // escrow the dispute settlement folds the yield into the
        // principal — no separate yield legs, both sinks stay zero.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap()
            .with_compound_interest()
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        let (taker_payout, fee, refund) =
            e.resolve(ARBITER, 600_000, disputed_at, None, None, BOB).unwrap();
        assert_eq!(fee, 0);
        assert_eq!(e.interest_compounded(), 5_000, "yield folded into principal");
        assert_eq!(e.interest_paid(), 0, "compound never pays a separate leg");
        assert_eq!(e.dispute_interest(), 0, "compound never attributes separately");
        // The split applies to the pre-fold remainder (the AV-117
        // ordering: `remaining` is captured before the fold) — the
        // taker takes 600_000, the initializer is refunded 400_000,
        // and the folded 5_000 stays in the grown principal.
        assert_eq!(taker_payout, 600_000);
        assert_eq!(refund, 400_000);
        assert_eq!(e.amount(), 1_005_000);
        assert_eq!(e.remaining_amount(), 405_000);
    }

    #[test]
    fn conservation_identity_includes_dispute_interest() {
        // Extended identity: inflow + yield == locked + released +
        // refunded + interest_paid + dispute_interest, with yield ==
        // interest_accrued + interest_paid + interest_compounded +
        // dispute_interest.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        e.resolve(ARBITER, 600_000, disputed_at + YEAR, None, None, BOB).unwrap();
        let inflow = 1_000_000u128;
        let yield_ = e.total_yield() as u128;
        // The AV-03 model semantics: `locked` counts only live
        // escrows — a Settled escrow's remainder left via the refund
        // leg, so it joins `refunded`, not `locked`.
        let locked = if e.state() == EscrowState::Funded {
            e.remaining_amount() as u128
        } else {
            0
        };
        let sinks = locked
            + e.released_amount() as u128
            + 400_000u128 // principal refunded to the initializer
            + e.interest_paid() as u128
            + e.dispute_interest() as u128;
        assert_eq!(inflow + yield_, sinks, "extended conservation identity");
        assert_eq!(e.total_yield(), 55_000);
        assert_eq!(e.interest_paid() + e.dispute_interest(), 55_000);
    }

    #[test]
    fn dispute_interest_tail_roundtrips_through_account_bytes() {
        // The 8-byte dispute-interest tail is the absolute tail:
        // encoder, VAULT_FIELDS, and decoder agree.
        assert_eq!(DISPUTE_INTEREST_LEN, 8);
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        let disputed_at = FUND_AT + 3_153_600;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0).unwrap();
        // Initializer full win: the whole 5_000 claim lands in the new
        // sink.
        e.resolve(ARBITER, 0, disputed_at, None, None, BOB).unwrap();
        assert_eq!(e.dispute_interest(), 5_000);
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        // The dispute-interest tail sits just before the AV-121
        // claim-cooldown tail (the AV-124 keeper-bounty tail is the
        // absolute tail).
        let tail = &bytes[ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN];
        assert_eq!(
            u64::from_le_bytes(tail.try_into().unwrap()),
            5_000,
            "dispute_interest tail offset"
        );
        let mut account = crate::discriminator::vault_account_discriminator().to_vec();
        account.extend_from_slice(&bytes);
        let decoded = crate::discriminator::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.dispute_interest(), 5_000);
        // The snapshot exports the sink for indexers.
        let snap = e.snapshot(disputed_at);
        assert_eq!(snap.dispute_interest, 5_000);
    }

    #[test]
    fn conservation_identity_gains_the_interest_sink() {
        // Extended identity: principal out (released) + yield out
        // (interest_paid) == principal in (amount) + yield earned.
        // The principal leg is untouched by the yield leg.
        let mut e = interest_escrow(500);
        let (taker_payout, _) = e.release(ALICE, FUND_AT + YEAR, 1_000_000, None, BOB).unwrap();
        assert_eq!(taker_payout, 1_050_000);
        assert_eq!(
            e.released_amount() + e.interest_paid(),
            e.amount() + 50_000,
            "locked + released + refunded + interest_paid balances against inflow + yield"
        );
        assert_eq!(e.released_amount(), 1_000_000, "principal leg exact");
        assert_eq!(e.remaining_amount(), 0);
    }

    #[test]
    fn slash_settles_before_the_lockup_shrinks() {
        // The pre-slash window accrues on the pre-slash principal;
        // the slash then shrinks the base for later windows.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_slash_terms(ALICE, FUND_AT + 10 * YEAR)
            .unwrap()
            .with_interest(500)
            .unwrap();
        e.fund(ALICE, FUND_AT).unwrap();
        e.slash(ALICE, 500_000, None, FUND_AT + 10 * YEAR).unwrap();
        // Harvest right after the slash: ten years accrued on 1M.
        assert_eq!(e.claim_interest(BOB, FUND_AT + 10 * YEAR).unwrap(), 500_000);
        // The next year accrues on the post-slash 500_000.
        assert_eq!(e.claim_interest(BOB, FUND_AT + 11 * YEAR).unwrap(), 25_000);
    }

    #[test]
    fn interest_tail_roundtrips_through_account_bytes() {
        // The 26-byte interest tail is pinned at the end of the
        // account: encoder, VAULT_FIELDS, and decoder agree.
        assert_eq!(INTEREST_REGION_LEN, 26);
        let mut e = interest_escrow(500);
        assert_eq!(e.claim_interest(BOB, FUND_AT + 3_153_600).unwrap(), 5_000);
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        let tail = &bytes[ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - DISPUTED_AMOUNT_TAIL_LEN - AUTO_UNPAUSE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - TWAP_GATE_LEN - DUAL_CONTROL_TAIL_LEN - REFUNDED_TAIL_LEN - SLASH_LADDER_TAIL_LEN - CLAIM_COOLDOWN_TAIL_LEN - COUNTER_OFFER_TAIL_LEN - RELEASE_INTENT_TAIL_LEN - KEEPER_BOUNTY_TAIL_LEN - DISPUTE_INTEREST_LEN - PRICE_GATE_LEN - PENALTY_ESCALATION_TAIL_LEN - COMPOUND_INTEREST_TAIL_LEN - SLOT_TIMELOCK_TAIL_LEN - RELEASE_COOLING_TAIL_LEN - FUNDING_TAIL_LEN - RENT_TOP_UP_LEN - DEADMAN_REGION_LEN - PAYOUT_SPLIT_LEN - INTEREST_REGION_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..];
        assert_eq!(u16::from_le_bytes(tail[..2].try_into().unwrap()), 500);
        assert_eq!(
            u64::from_le_bytes(tail[2..10].try_into().unwrap()),
            FUND_AT + 3_153_600,
            "accrual base advanced to the harvest"
        );
        assert_eq!(u64::from_le_bytes(tail[10..18].try_into().unwrap()), 0);
        assert_eq!(u64::from_le_bytes(tail[18..26].try_into().unwrap()), 5_000);
        let mut account = vec![0u8; 8 + ESCROW_BODY_LEN];
        account[..8].copy_from_slice(&vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = decode_vault_account(&account).unwrap();
        assert_eq!(decoded.interest_rate_bps(), 500);
        assert_eq!(decoded.interest_accrued(), 0);
        assert_eq!(decoded.interest_paid(), 5_000);
        // A decoded escrow settles and bundles exactly like the live one.
        let mut live = e;
        let mut back = decoded;
        let live_out = live.release(ALICE, FUND_AT + YEAR, 1_000_000, None, BOB).unwrap();
        let back_out = back.release(ALICE, FUND_AT + YEAR, 1_000_000, None, BOB).unwrap();
        assert_eq!(live_out, back_out);
    }

    #[test]
    fn claim_interest_refuses_live_swap_link() {
        // A live-linked escrow settles only through the pair path —
        // the single-side harvest is refused like release / claim.
        let mut a = Escrow::initialize(ALICE, BOB, 1_000_000, u64::MAX)
            .unwrap()
            .with_interest(500)
            .unwrap();
        let mut b = Escrow::initialize(BOB, ALICE, 1_000_000, u64::MAX).unwrap();
        crate::link_swap(&mut a, &mut b, ALICE, [0xA1; 32], [0xB1; 32], 1_000_000, 1_000_000)
            .unwrap();
        a.fund(ALICE, FUND_AT).unwrap();
        b.fund(BOB, FUND_AT).unwrap();
        assert_eq!(
            a.claim_interest(BOB, FUND_AT + YEAR).unwrap_err(),
            EscrowError::SwapLinkActive
        );
        // The pair path still bundles each leg's yield via the inner
        // release (the link is taken and restored around each leg).
        let (payout_a, _, payout_b, _) = crate::release_swap(
            &mut a,
            &mut b,
            ALICE,
            [0xA1; 32],
            [0xB1; 32],
            FUND_AT + YEAR,
            1_000_000,
            None,
            BOB,
            1_000_000,
            None,
            ALICE,
        )
        .unwrap();
        assert_eq!(payout_a, 1_050_000, "leg A's principal + its yield");
        assert_eq!(payout_b, 1_000_000, "leg B has no interest configured");
        assert_eq!(a.interest_paid(), 50_000);
    }

    #[test]
    fn error_codes_are_pinned() {
        assert_eq!(EscrowError::InvalidInterestRate.code(), 165);
        assert_eq!(EscrowError::InterestNotEnabled.code(), 166);
    }
}

// ---------- AV-104: authority delegation ----------
//
// The initializer/taker may grant a bounded slice of their authority
// to an operator key (scope bitmap: fund/release/cancel). The
// delegation-aware authority checks sit behind
// `require_scoped_authority` on the four core paths (fund, release,
// cancel, cancel_expired).
#[cfg(test)]
mod delegation_tests {
    use super::*;
    use crate::discriminator::{decode_vault_account, vault_account_discriminator};

    const ALICE: [u8; 32] = [0xAA; 32]; // initializer
    const BOB: [u8; 32] = [0xBB; 32]; // taker
    const MALLORY: [u8; 32] = [0xCC; 32]; // stranger
    const OPERATOR: [u8; 32] = [0x0D; 32]; // delegated operator
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_700_000_000;

    fn funded() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        e
    }

    fn full_scopes() -> u32 {
        DELEGATION_SCOPE_FUND | DELEGATION_SCOPE_RELEASE | DELEGATION_SCOPE_CANCEL
    }

    #[test]
    fn grant_requires_a_party() {
        let mut e = funded();
        // A stranger cannot grant — and cannot sub-delegate from
        // nothing.
        assert_eq!(
            e.delegate_authority(MALLORY, OPERATOR, full_scopes()),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.delegation(), None, "failed grant stores nothing");
        // Either party may grant.
        e.delegate_authority(ALICE, OPERATOR, full_scopes()).unwrap();
        assert_eq!(
            e.delegation(),
            Some(Delegation::new(OPERATOR, full_scopes()))
        );
        let mut e2 = funded();
        e2.delegate_authority(BOB, OPERATOR, DELEGATION_SCOPE_RELEASE)
            .unwrap();
        assert_eq!(
            e2.delegation().unwrap().scopes(),
            DELEGATION_SCOPE_RELEASE
        );
    }

    #[test]
    fn grant_rejects_zero_key_and_bad_scopes() {
        let mut e = funded();
        // Zero operator key: a grant to nowhere.
        assert_eq!(
            e.delegate_authority(ALICE, [0u8; 32], full_scopes()),
            Err(EscrowError::InvalidDelegation)
        );
        // Empty bitmap: a grant of nothing.
        assert_eq!(
            e.delegate_authority(ALICE, OPERATOR, 0),
            Err(EscrowError::InvalidDelegation)
        );
        // Unknown bits: a future scope smuggled into an old bitmap.
        assert_eq!(
            e.delegate_authority(ALICE, OPERATOR, full_scopes() | (1 << 7)),
            Err(EscrowError::InvalidDelegation)
        );
        assert_eq!(EscrowError::InvalidDelegation.code(), 160);
        assert_eq!(e.delegation(), None, "rejected grants store nothing");
    }

    #[test]
    fn grant_rejects_terminal_states() {
        let mut e = funded();
        e.cancel(ALICE, None, ALICE, 0).unwrap();
        assert_eq!(e.state(), EscrowState::Cancelled);
        assert_eq!(
            e.delegate_authority(ALICE, OPERATOR, full_scopes()),
            Err(EscrowError::InvalidStateTransition)
        );
        assert_eq!(
            e.revoke_delegation(ALICE),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn grant_is_idempotent_and_overwrites() {
        let mut e = funded();
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_FUND)
            .unwrap();
        // Identical re-grant: no-op success.
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_FUND)
            .unwrap();
        assert_eq!(
            e.delegation().unwrap().scopes(),
            DELEGATION_SCOPE_FUND
        );
        // A later grant wins — the single slot is overwritten, so a
        // compromised operator is cut off by one new grant.
        e.delegate_authority(ALICE, MALLORY, DELEGATION_SCOPE_CANCEL)
            .unwrap();
        let grant = e.delegation().unwrap();
        assert_eq!(grant.delegate(), MALLORY);
        assert_eq!(grant.scopes(), DELEGATION_SCOPE_CANCEL);
    }

    #[test]
    fn revoke_needs_a_live_grant_and_either_party() {
        let mut e = funded();
        assert_eq!(
            e.revoke_delegation(ALICE),
            Err(EscrowError::InvalidDelegation)
        );
        assert_eq!(
            e.revoke_delegation(MALLORY),
            Err(EscrowError::Unauthorized),
            "a stranger cannot revoke either"
        );
        e.delegate_authority(ALICE, OPERATOR, full_scopes()).unwrap();
        // The taker can cut off an initializer-appointed operator.
        e.revoke_delegation(BOB).unwrap();
        assert_eq!(e.delegation(), None);
        assert_eq!(
            e.revoke_delegation(ALICE),
            Err(EscrowError::InvalidDelegation),
            "double revoke fails"
        );
    }

    #[test]
    fn operator_funds_with_fund_scope() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_FUND)
            .unwrap();
        e.fund(OPERATOR, NOW).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn operator_cannot_act_outside_scope() {
        let mut e = funded();
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_RELEASE)
            .unwrap();
        // Out-of-scope calls fail with the pre-existing Unauthorized —
        // not the new InvalidDelegation code.
        assert_eq!(
            e.fund(OPERATOR, NOW),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            e.cancel(OPERATOR, None, ALICE, 0),
            Err(EscrowError::Unauthorized)
        );
        // In-scope: the release goes through to the pinned taker.
        let (payout, fee) = e.release(OPERATOR, NOW, 400_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (400_000, 0));
        assert_eq!(e.released_amount(), 400_000);
    }

    #[test]
    fn operator_cancels_with_cancel_scope() {
        let mut e = funded();
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_CANCEL)
            .unwrap();
        e.cancel(OPERATOR, None, ALICE, 0).unwrap();
        assert_eq!(e.state(), EscrowState::Cancelled);

        // cancel_expired through the operator: the refund still goes
        // to the pinned destination and the operator pays no taker
        // penalty.
        let mut e2 = Escrow::initialize(ALICE, BOB, 1_000_000, NOW - 100).unwrap();
        e2.fund(ALICE, NOW - 200).unwrap();
        e2.delegate_authority(BOB, OPERATOR, DELEGATION_SCOPE_CANCEL)
            .unwrap();
        let (refund, _, penalty) = e2.cancel_expired(OPERATOR, NOW, None, ALICE).unwrap();
        assert_eq!(e2.state(), EscrowState::Cancelled);
        assert_eq!((refund, penalty), (1_000_000, 0));
    }

    #[test]
    fn pause_blocks_grant_and_delegated_paths() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(ALICE)
            .unwrap();
        e.pause(ALICE, None).unwrap();
        // The pause gate runs before the authority check (AV-46).
        assert_eq!(
            e.delegate_authority(ALICE, OPERATOR, full_scopes()),
            Err(EscrowError::Paused)
        );
        assert_eq!(
            e.revoke_delegation(ALICE),
            Err(EscrowError::Paused)
        );
        e.unpause(ALICE).unwrap();
        e.delegate_authority(ALICE, OPERATOR, DELEGATION_SCOPE_FUND)
            .unwrap();
        e.pause(ALICE, None).unwrap();
        assert_eq!(e.fund(OPERATOR, NOW), Err(EscrowError::Paused));
    }

    #[test]
    fn rotation_clears_the_grant() {
        let mut e = funded();
        e.delegate_authority(ALICE, OPERATOR, full_scopes()).unwrap();
        e.rotate_taker(ALICE, BOB, MALLORY).unwrap();
        assert_eq!(e.delegation(), None, "taker rotation clears the grant");
        assert_eq!(
            e.release(MALLORY, NOW, 100, None, MALLORY),
            Err(EscrowError::Unauthorized),
            "the old operator is cut off"
        );

        let mut e2 = funded();
        e2.delegate_authority(BOB, OPERATOR, full_scopes()).unwrap();
        e2.rotate_initializer(ALICE, BOB, MALLORY).unwrap();
        assert_eq!(
            e2.delegation(),
            None,
            "initializer rotation clears the grant"
        );
    }

    #[test]
    fn effective_role_reports_party_first() {
        let mut e = funded();
        assert_eq!(e.effective_role(ALICE), Some(DelegatedRole::Initializer));
        assert_eq!(e.effective_role(BOB), Some(DelegatedRole::Taker));
        assert_eq!(e.effective_role(MALLORY), None);
        e.delegate_authority(ALICE, OPERATOR, full_scopes()).unwrap();
        assert_eq!(
            e.effective_role(OPERATOR),
            Some(DelegatedRole::Operator(full_scopes()))
        );
        // A party that also holds a grant still reports as the party.
        e.delegate_authority(ALICE, BOB, DELEGATION_SCOPE_FUND).unwrap();
        assert_eq!(e.effective_role(BOB), Some(DelegatedRole::Taker));
    }

    #[test]
    fn grant_round_trips_through_encode_decode() {
        let mut e = funded();
        e.delegate_authority(ALICE, OPERATOR, full_scopes()).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), super::ESCROW_BODY_LEN);
        // The grant sits in the 37 bytes before the trailing 33-byte
        // AV-105 swap-link region: 1-byte Some discriminant, the
        // 32-byte operator key, the u32 bitmap.
        let tail = &bytes[super::ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN - super::DISPUTE_INTEREST_LEN - super::PRICE_GATE_LEN - super::PENALTY_ESCALATION_TAIL_LEN - super::COMPOUND_INTEREST_TAIL_LEN - super::SLOT_TIMELOCK_TAIL_LEN - super::RELEASE_COOLING_TAIL_LEN - super::FUNDING_TAIL_LEN - super::RENT_TOP_UP_LEN - super::DEADMAN_REGION_LEN - super::PAYOUT_SPLIT_LEN - super::INTEREST_REGION_LEN - POOL_REGION_LEN - super::SWAP_LINK_REGION_LEN - DELEGATION_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..];
        assert_eq!(tail[0], 1, "Some discriminant");
        assert_eq!(&tail[1..33], &OPERATOR);
        assert_eq!(
            u32::from_le_bytes(tail[33..37].try_into().unwrap()),
            full_scopes()
        );
        let mut account = vec![0u8; 8 + super::ESCROW_BODY_LEN];
        account[..8].copy_from_slice(&vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = decode_vault_account(&account).unwrap();
        assert_eq!(decoded.delegation(), Some(Delegation::new(OPERATOR, full_scopes())));
        // A grant-less escrow still decodes with a zeroed tail.
        let plain = funded();
        let plain_bytes = super::account_space_tests::encode_escrow(&plain);
        assert_eq!(
            &plain_bytes[super::ESCROW_BODY_LEN - super::MINT_ALLOWLIST_TAIL_LEN - super::GOVERNANCE_DELAY_TAIL_LEN - super::GOVERNANCE_PROPOSAL_TAIL_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - RENT_SWEEP_TAIL_LEN - ARBITER_FEE_TAIL_LEN - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN - super::DISPUTE_INTEREST_LEN - super::PRICE_GATE_LEN - super::PENALTY_ESCALATION_TAIL_LEN - super::COMPOUND_INTEREST_TAIL_LEN - super::SLOT_TIMELOCK_TAIL_LEN - super::RELEASE_COOLING_TAIL_LEN - super::FUNDING_TAIL_LEN - super::RENT_TOP_UP_LEN - super::DEADMAN_REGION_LEN - super::PAYOUT_SPLIT_LEN - super::INTEREST_REGION_LEN - POOL_REGION_LEN - super::SWAP_LINK_REGION_LEN - DELEGATION_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..super::ESCROW_BODY_LEN - super::MINT_ALLOWLIST_TAIL_LEN - super::GOVERNANCE_DELAY_TAIL_LEN - super::GOVERNANCE_PROPOSAL_TAIL_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN - super::DISPUTE_INTEREST_LEN - super::PRICE_GATE_LEN - super::PENALTY_ESCALATION_TAIL_LEN - super::COMPOUND_INTEREST_TAIL_LEN - super::SLOT_TIMELOCK_TAIL_LEN - super::RELEASE_COOLING_TAIL_LEN - super::FUNDING_TAIL_LEN - super::RENT_TOP_UP_LEN - super::DEADMAN_REGION_LEN - super::PAYOUT_SPLIT_LEN - super::INTEREST_REGION_LEN - POOL_REGION_LEN - RENT_SWEEP_TAIL_LEN - super::SWAP_LINK_REGION_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN],
            &[0u8; DELEGATION_LEN]
        );
        let mut account = vec![0u8; 8 + super::ESCROW_BODY_LEN];
        account[..8].copy_from_slice(&vault_account_discriminator());
        account[8..].copy_from_slice(&plain_bytes);
        assert_eq!(decode_vault_account(&account).unwrap().delegation(), None);
    }

    #[test]
    fn indexed_wrapper_emits_grant_and_revoke_events() {
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xF1; 32], NOW)
            .unwrap();
        let before = e.event_count();
        e.delegate_authority(ALICE, OPERATOR, full_scopes(), NOW).unwrap();
        assert_eq!(e.event_count(), before + 1);
        let ev = e.events().last().expect("grant event");
        assert_eq!(ev.kind, EscrowEventKind::DelegationGranted);
        assert_eq!((ev.from, ev.to), (EscrowState::Uninitialized, EscrowState::Uninitialized));
        assert_eq!(ev.caller, None, "caller is only set for permissionless cranks");
        // Identical re-grant: no-op, no event.
        e.delegate_authority(ALICE, OPERATOR, full_scopes(), NOW).unwrap();
        assert_eq!(e.event_count(), before + 1, "no-op re-grant emits nothing");
        e.revoke_delegation(BOB, NOW).unwrap();
        assert_eq!(e.event_count(), before + 2);
        let ev = e.events().last().expect("revoke event");
        assert_eq!(ev.kind, EscrowEventKind::DelegationRevoked);
        assert_eq!((ev.from, ev.to), (EscrowState::Uninitialized, EscrowState::Uninitialized));
        assert_eq!(ev.caller, None, "caller is only set for permissionless cranks");
    }

    #[test]
    fn scope_bits_and_validation() {
        assert_eq!(DELEGATION_SCOPE_FUND, 1);
        assert_eq!(DELEGATION_SCOPE_RELEASE, 2);
        assert_eq!(DELEGATION_SCOPE_CANCEL, 4);
        assert_eq!(DELEGATION_SCOPE_MASK, 0b111);
        assert_eq!(DELEGATION_LEN, 37);
        assert!(validate_delegation_scopes(DELEGATION_SCOPE_FUND));
        assert!(validate_delegation_scopes(full_scopes()));
        assert!(!validate_delegation_scopes(0));
        assert!(!validate_delegation_scopes(1 << 7));
        let grant = Delegation::new(OPERATOR, full_scopes());
        assert!(grant.covers(DELEGATION_SCOPE_FUND));
        assert!(grant.covers(DELEGATION_SCOPE_RELEASE));
        assert!(grant.covers(DELEGATION_SCOPE_CANCEL));
        let narrow = Delegation::new(OPERATOR, DELEGATION_SCOPE_CANCEL);
        assert!(!narrow.covers(DELEGATION_SCOPE_FUND));
        assert!(narrow.covers(DELEGATION_SCOPE_CANCEL));
    }
}

#[cfg(test)]
mod compound_interest_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xA1; 32];
    const BOB: [u8; 32] = [0xB2; 32];
    const NOW: u64 = 1_700_000_000;
    const YEAR: u64 = 31_536_000;
    const AMOUNT: u64 = 1_000_000;

    fn funded_compound() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX).unwrap();
        e = e.with_interest(1_000).unwrap(); // 10% annual
        e = e.with_compound_interest().unwrap();
        e.fund(ALICE, NOW).unwrap();
        e
    }

    #[test]
    fn with_compound_interest_requires_uninitialized() {
        let e = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX).unwrap();
        let e = e.with_compound_interest().unwrap();
        assert!(e.compound_interest());
        // Cannot opt in after funding.
        let mut e2 = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX).unwrap();
        e2.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e2.with_compound_interest().unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn with_compound_interest_is_order_independent() {
        // Compound before rate: accepted, inert while rate == 0.
        let e = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX)
            .unwrap()
            .with_compound_interest()
            .unwrap();
        assert!(e.compound_interest());
        assert_eq!(e.interest_rate_bps(), 0);
        // Rate before compound: also accepted.
        let e2 = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX)
            .unwrap()
            .with_interest(500)
            .unwrap()
            .with_compound_interest()
            .unwrap();
        assert!(e2.compound_interest());
        assert_eq!(e2.interest_rate_bps(), 500);
    }

    #[test]
    fn claim_interest_refused_on_compound_escrow() {
        let mut e = funded_compound();
        // Settle a full year so there is accrued interest.
        e.settle_interest(NOW + YEAR);
        assert!(e.interest_accrued() > 0);
        let err = e.claim_interest(BOB, NOW + YEAR).unwrap_err();
        assert_eq!(err, EscrowError::CompoundInterestActive);
        assert_eq!(err.code(), 178);
        // The escrow is untouched: the claim is still outstanding.
        assert!(e.interest_accrued() > 0);
        assert_eq!(e.interest_paid(), 0);
    }

    #[test]
    fn compound_folds_yield_into_principal() {
        let mut e = funded_compound();
        let principal_before = e.amount();
        // Settle one year at 10%: ~100,000 lamports of yield.
        e.settle_interest(NOW + YEAR);
        let accrued = e.interest_accrued();
        assert!(accrued > 0);
        // Release triggers compounding (not a separate payout).
        let (payout, _fee) = e.release(ALICE, NOW + YEAR, principal_before, None, BOB).unwrap();
        // The principal grew by the compounded yield.
        assert_eq!(e.amount(), principal_before + accrued);
        assert_eq!(e.interest_compounded(), accrued);
        assert_eq!(e.interest_accrued(), 0);
        assert_eq!(e.interest_paid(), 0, "compound never pays out separately");
        // The taker received principal + compounded yield.
        assert!(payout >= principal_before);
    }

    #[test]
    fn total_yield_accounts_for_all_three_legs() {
        let mut e = funded_compound();
        e.settle_interest(NOW + YEAR);
        let accrued = e.interest_accrued();
        assert_eq!(e.total_yield(), accrued);
        // After compounding, the yield moved legs but the total holds.
        let principal = e.amount();
        e.release(ALICE, NOW + YEAR, principal, None, BOB).unwrap();
        assert_eq!(e.total_yield(), accrued);
        assert_eq!(e.interest_compounded(), accrued);
    }

    #[test]
    fn compound_tail_roundtrips_through_account_bytes() {
        let mut e = funded_compound();
        e.settle_interest(NOW + YEAR);
        let principal = e.amount();
        e.release(ALICE, NOW + YEAR, principal, None, BOB).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), super::ESCROW_BODY_LEN);
        // The 9-byte compound tail now sits just before the AV-119
        // dispute-interest tail (which the AV-121 claim-cooldown tail
        // trails, itself trailed by the AV-122 counter-offer tail,
        // the AV-123 intent nonce tail, the AV-124 keeper-bounty tail
        // and the AV-126 slash-ladder tail).
        let tail = &bytes[super::ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - super::ARBITER_FEE_TAIL_LEN - super::RENT_SWEEP_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN
            - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN
            - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN
            - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN
            - super::DISPUTE_INTEREST_LEN
            - super::COMPOUND_INTEREST_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN..super::ESCROW_BODY_LEN - super::MINT_ALLOWLIST_TAIL_LEN - super::GOVERNANCE_DELAY_TAIL_LEN - super::GOVERNANCE_PROPOSAL_TAIL_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - super::ARBITER_FEE_TAIL_LEN - super::RENT_SWEEP_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN
                - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN
                - super::CLAIM_COOLDOWN_TAIL_LEN - super::COUNTER_OFFER_TAIL_LEN
                - super::RELEASE_INTENT_TAIL_LEN - super::KEEPER_BOUNTY_TAIL_LEN
                - super::DISPUTE_INTEREST_LEN];
        assert_eq!(tail.len(), super::COMPOUND_INTEREST_TAIL_LEN);
        assert_eq!(tail[0], 1, "compound_interest flag");
        assert_eq!(
            u64::from_le_bytes(tail[1..9].try_into().unwrap()),
            e.interest_compounded(),
            "interest_compounded tail offset"
        );
        // The 8-byte dispute-interest tail now trails the
        // claim-cooldown / counter-offer / intent / keeper-bounty /
        // slash-ladder tails — zeroed here (no dispute ever ran on
        // this escrow).
        let dtail = &bytes[super::ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - super::ARBITER_FEE_TAIL_LEN - super::RENT_SWEEP_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN
            - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN
            - super::KEEPER_BOUNTY_TAIL_LEN
            - super::RELEASE_INTENT_TAIL_LEN
            - super::COUNTER_OFFER_TAIL_LEN
            - super::CLAIM_COOLDOWN_TAIL_LEN
            - super::DISPUTE_INTEREST_LEN
            ..super::ESCROW_BODY_LEN - super::MINT_ALLOWLIST_TAIL_LEN - super::GOVERNANCE_DELAY_TAIL_LEN - super::GOVERNANCE_PROPOSAL_TAIL_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - super::ARBITER_FEE_TAIL_LEN - super::RENT_SWEEP_TAIL_LEN - super::FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN
                - super::DISPUTED_AMOUNT_TAIL_LEN - super::AUTO_UNPAUSE_TAIL_LEN - super::AMOUNT_BOUNDS_TAIL_LEN - super::TWAP_GATE_LEN - super::DUAL_CONTROL_TAIL_LEN - super::REFUNDED_TAIL_LEN - super::SLASH_LADDER_TAIL_LEN
                - super::KEEPER_BOUNTY_TAIL_LEN
                - super::RELEASE_INTENT_TAIL_LEN
                - super::COUNTER_OFFER_TAIL_LEN
                - super::CLAIM_COOLDOWN_TAIL_LEN];
        assert_eq!(dtail.len(), super::DISPUTE_INTEREST_LEN);
        assert_eq!(
            u64::from_le_bytes(dtail.try_into().unwrap()),
            0,
            "dispute_interest absolute tail offset"
        );
        // Full account decode preserves the mode.
        let mut account = crate::discriminator::vault_account_discriminator().to_vec();
        account.extend_from_slice(&bytes);
        let decoded = crate::discriminator::decode_vault_account(&account).unwrap();
        assert!(decoded.compound_interest());
        assert_eq!(decoded.interest_compounded(), e.interest_compounded());
        assert_eq!(decoded.dispute_interest(), e.dispute_interest());
    }

    #[test]
    fn snapshot_exports_compound_fields() {
        let mut e = funded_compound();
        e.settle_interest(NOW + YEAR);
        let snap = e.snapshot(NOW + YEAR);
        assert!(snap.compound_interest);
        assert_eq!(snap.interest_compounded, 0);
        let principal = e.amount();
        e.release(ALICE, NOW + YEAR, principal, None, BOB).unwrap();
        let snap2 = e.snapshot(NOW + YEAR);
        assert!(snap2.compound_interest);
        assert!(snap2.interest_compounded > 0);
    }

    #[test]
    fn non_compound_escrow_unchanged() {
        // Backward compatibility: without the opt-in, the AV-107
        // behavior is preserved.
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, u64::MAX).unwrap();
        e = e.with_interest(1_000).unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert!(!e.compound_interest());
        e.settle_interest(NOW + YEAR);
        let accrued = e.interest_accrued();
        let paid = e.claim_interest(BOB, NOW + YEAR).unwrap();
        assert_eq!(paid, accrued);
        assert_eq!(e.interest_paid(), accrued);
        assert_eq!(e.interest_compounded(), 0);
    }
}

// ---------- AV-130: dual-control (maker-checker) release ----------
//
// The two-step payout protocol: the initializer (the *maker*) freezes
// each payout declaration with `initiate_release`; a second, distinct
// key (the *checker*) approves it with `confirm_release`, or either
// party aborts it with `cancel_release`. No single key moves funds.
#[cfg(test)]
mod dual_control_tests {
    use super::*;
    use crate::discriminator::{decode_vault_account, vault_account_discriminator};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const CHECKER: [u8; 32] = [0xC0; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const ZERO_KEY: [u8; 32] = [0x00; 32];
    const PAUSE_AUTH: [u8; 32] = [0xA6; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_750_000_000;
    const TTL: u64 = 3_600;

    /// A funded dual-control escrow: initializer ALICE, taker BOB,
    /// checker CHECKER, 1_000_000 locked.
    fn funded_dc() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    /// A funded dual-control escrow with a live declaration.
    fn declared(amount: u64, now: u64) -> Escrow {
        let mut e = funded_dc();
        e.initiate_release(ALICE, now, amount, None, BOB, TTL)
            .unwrap();
        e
    }

    // ----- with_dual_control -----

    #[test]
    fn with_dual_control_happy_path() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        assert_eq!(e.dual_control_checker(), Some(CHECKER));
        assert_eq!(e.dual_control_intent(), None);
        // No intent live, plain escrow otherwise.
        assert_eq!(e.state(), EscrowState::Uninitialized);
    }

    #[test]
    fn with_dual_control_zero_checker_rejected() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        assert_eq!(
            e.with_dual_control(ZERO_KEY).unwrap_err(),
            EscrowError::InvalidDualControl
        );
    }

    #[test]
    fn with_dual_control_rejected_after_funding() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.with_dual_control(CHECKER).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn with_dual_control_rejected_while_paused() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(PAUSE_AUTH)
            .unwrap();
        e.pause(PAUSE_AUTH, None).unwrap();
        assert_eq!(
            e.with_dual_control(CHECKER).unwrap_err(),
            EscrowError::Paused
        );
    }

    // ----- initiate_release -----

    #[test]
    fn initiate_freezes_the_declaration_and_keeps_state_funded() {
        let mut e = funded_dc();
        e.initiate_release(ALICE, NOW, 400_000, None, BOB, TTL)
            .unwrap();
        let intent = e.dual_control_intent().unwrap();
        assert_eq!(intent.amount, 400_000);
        assert_eq!(intent.mint, None);
        assert_eq!(intent.payout_to, BOB);
        assert_eq!(intent.initiated_at, NOW);
        assert_eq!(intent.intent_expires_at, NOW + TTL);
        assert_eq!(e.state(), EscrowState::Funded);
        // No funds moved by the declaration.
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn initiate_stranger_is_unauthorized() {
        let mut e = funded_dc();
        assert_eq!(
            e.initiate_release(MALLORY, NOW, 400_000, None, BOB, TTL),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.dual_control_intent(), None);
    }

    #[test]
    fn initiate_without_opt_in_is_invalid_dual_control() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.initiate_release(ALICE, NOW, 400_000, None, BOB, TTL),
            Err(EscrowError::InvalidDualControl)
        );
    }

    #[test]
    fn initiate_twice_is_intent_exists() {
        let mut e = declared(400_000, NOW);
        assert_eq!(
            e.initiate_release(ALICE, NOW + 1, 100_000, None, BOB, TTL),
            Err(EscrowError::DualControlIntentExists)
        );
        // The first declaration survives the rejected second one.
        assert_eq!(e.dual_control_intent().unwrap().amount, 400_000);
    }

    #[test]
    fn initiate_zero_amount_or_ttl_is_invalid() {
        let mut e = funded_dc();
        assert_eq!(
            e.initiate_release(ALICE, NOW, 0, None, BOB, TTL),
            Err(EscrowError::InvalidDualControl)
        );
        assert_eq!(
            e.initiate_release(ALICE, NOW, 400_000, None, BOB, 0),
            Err(EscrowError::InvalidDualControl)
        );
        // An expiry that overflows u64 is rejected, not wrapped.
        assert_eq!(
            e.initiate_release(ALICE, u64::MAX, 400_000, None, BOB, 1),
            Err(EscrowError::InvalidDualControl)
        );
        assert_eq!(e.dual_control_intent(), None);
    }

    #[test]
    fn initiate_rejected_when_not_funded() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        assert_eq!(
            e.initiate_release(ALICE, NOW, 400_000, None, BOB, TTL),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn initiate_rejected_while_paused() {
        let mut e = funded_dc();
        e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_pause_authority(PAUSE_AUTH)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.pause(PAUSE_AUTH, None).unwrap();
        assert_eq!(
            e.initiate_release(ALICE, NOW, 400_000, None, BOB, TTL),
            Err(EscrowError::Paused)
        );
    }

    // ----- the direct-release gate -----

    #[test]
    fn direct_release_is_refused_on_dual_control_escrow() {
        let mut e = funded_dc();
        assert_eq!(
            e.release(ALICE, NOW, 400_000, None, BOB),
            Err(EscrowError::DualControlRequired)
        );
        assert_eq!(e.released_amount(), 0);
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn release_via_intent_is_refused_on_dual_control_escrow() {
        // The gasless path routes through `release`, so it inherits
        // the dual-control gate — no bypass via intent.
        use crate::release_intent::{sign_release_intent, ReleaseIntent};
        let key = SigningKey::from_seed([0xA1; 32]);
        let mut e = Escrow::initialize(key.public_key(), BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(key.public_key(), NOW).unwrap();
        let intent = ReleaseIntent::new([0x11; 32], 400_000, BOB, 1, 1_000_000);
        let sig = sign_release_intent(&key, &intent);
        assert_eq!(
            e.release_via_intent(&intent, &sig, NOW, 100_000, None),
            Err(EscrowError::DualControlRequired)
        );
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn direct_release_still_works_without_dual_control() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let (payout, fee) = e.release(ALICE, NOW, 400_000, None, BOB).unwrap();
        assert_eq!(payout, 400_000);
        assert_eq!(fee, 0);
    }

    // ----- confirm_release -----

    #[test]
    fn confirm_settles_the_declaration() {
        let mut e = declared(400_000, NOW);
        let (payout, fee) = e.confirm_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(payout, 400_000);
        assert_eq!(fee, 0);
        assert_eq!(e.released_amount(), 400_000);
        // The declaration is consumed; the escrow stays Funded on a
        // partial settlement.
        assert_eq!(e.dual_control_intent(), None);
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn confirm_draining_declaration_moves_to_released() {
        let mut e = declared(1_000_000, NOW);
        let (payout, _) = e.confirm_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(payout, 1_000_000);
        assert_eq!(e.state(), EscrowState::Released);
        assert_eq!(e.dual_control_intent(), None);
    }

    #[test]
    fn confirm_charges_the_protocol_fee() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_protocol_fee(1_000) // 10%
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.initiate_release(ALICE, NOW, 400_000, None, BOB, TTL)
            .unwrap();
        let (payout, fee) = e.confirm_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(fee, 40_000);
        assert_eq!(payout, 360_000);
        assert_eq!(e.fees_paid(), 40_000);
    }

    #[test]
    fn confirm_wrong_checker_is_unauthorized() {
        let mut e = declared(400_000, NOW);
        // The maker cannot self-approve; a stranger cannot either.
        assert_eq!(
            e.confirm_release(ALICE, NOW + 100),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            e.confirm_release(MALLORY, NOW + 100),
            Err(EscrowError::Unauthorized)
        );
        // The declaration survives the rejected approvals.
        assert!(e.dual_control_intent().is_some());
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn confirm_expired_intent_clears_it_and_fails() {
        let mut e = declared(400_000, NOW);
        // `now == intent_expires_at` is already expired.
        assert_eq!(
            e.confirm_release(CHECKER, NOW + TTL),
            Err(EscrowError::DualControlExpired)
        );
        assert_eq!(e.dual_control_intent(), None);
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn confirm_without_intent_is_not_initiated() {
        let mut e = funded_dc();
        assert_eq!(
            e.confirm_release(CHECKER, NOW),
            Err(EscrowError::DualControlNotInitiated)
        );
    }

    #[test]
    fn confirm_without_opt_in_is_invalid_dual_control() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.confirm_release(CHECKER, NOW),
            Err(EscrowError::InvalidDualControl)
        );
    }

    #[test]
    fn confirm_failed_settlement_leaves_intent_live() {
        // Declare more than the lockup holds; the settlement fails and
        // the declaration stays live for a retry.
        let mut e = funded_dc();
        e.initiate_release(ALICE, NOW, 1_000_001, None, BOB, TTL)
            .unwrap();
        assert_eq!(
            e.confirm_release(CHECKER, NOW + 100),
            Err(EscrowError::ReleaseExceedsLocked)
        );
        assert!(e.dual_control_intent().is_some());
    }

    // ----- cancel_release -----

    #[test]
    fn cancel_by_initializer_clears_the_intent() {
        let mut e = declared(400_000, NOW);
        e.cancel_release(ALICE, NOW + 100).unwrap();
        assert_eq!(e.dual_control_intent(), None);
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn cancel_by_checker_clears_the_intent() {
        let mut e = declared(400_000, NOW);
        e.cancel_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(e.dual_control_intent(), None);
    }

    #[test]
    fn cancel_by_stranger_is_unauthorized() {
        let mut e = declared(400_000, NOW);
        assert_eq!(
            e.cancel_release(MALLORY, NOW + 100),
            Err(EscrowError::Unauthorized)
        );
        assert!(e.dual_control_intent().is_some());
    }

    #[test]
    fn cancel_without_intent_is_not_initiated() {
        let mut e = funded_dc();
        assert_eq!(
            e.cancel_release(ALICE, NOW),
            Err(EscrowError::DualControlNotInitiated)
        );
        assert_eq!(
            e.cancel_release(CHECKER, NOW),
            Err(EscrowError::DualControlNotInitiated)
        );
    }

    // ----- single-key compromise -----

    #[test]
    fn stolen_initializer_key_cannot_settle_alone() {
        // The attacker holds the initializer key: they can declare,
        // but the declaration never settles without the checker.
        let mut e = funded_dc();
        e.initiate_release(ALICE, NOW, 1_000_000, None, MALLORY, TTL)
            .unwrap();
        assert_eq!(
            e.confirm_release(ALICE, NOW + 100),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.released_amount(), 0);
        // And the direct path is closed too.
        assert_eq!(
            e.release(ALICE, NOW + 100, 1_000_000, None, MALLORY),
            Err(EscrowError::DualControlRequired)
        );
    }

    #[test]
    fn stolen_checker_key_cannot_declare_alone() {
        // The attacker holds only the checker key: they cannot
        // declare a payout, so there is nothing to approve.
        let mut e = funded_dc();
        assert_eq!(
            e.initiate_release(CHECKER, NOW, 1_000_000, None, MALLORY, TTL),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.dual_control_intent(), None);
    }

    #[test]
    fn checker_can_cancel_a_hostile_declaration() {
        // The compromised maker declares a payout to the attacker;
        // the honest checker aborts it.
        let mut e = funded_dc();
        e.initiate_release(ALICE, NOW, 1_000_000, None, MALLORY, TTL)
            .unwrap();
        e.cancel_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(e.dual_control_intent(), None);
        assert_eq!(e.released_amount(), 0);
    }

    // ----- error codes -----

    #[test]
    fn dual_control_error_codes_are_pinned() {
        assert_eq!(EscrowError::InvalidDualControl.code(), 188);
        assert_eq!(EscrowError::DualControlIntentExists.code(), 189);
        assert_eq!(EscrowError::DualControlNotInitiated.code(), 190);
        assert_eq!(EscrowError::DualControlExpired.code(), 191);
        assert_eq!(EscrowError::DualControlRequired.code(), 192);
    }

    // ----- layout pins -----

    #[test]
    fn dual_control_tail_layout_is_pinned() {
        assert_eq!(DUAL_CONTROL_INTENT_LEN, 8 + 33 + 32 + 8 + 8);
        assert_eq!(DUAL_CONTROL_INTENT_LEN, 89);
        assert_eq!(DUAL_CONTROL_TAIL_LEN, 33 + (1 + 89));
        assert_eq!(DUAL_CONTROL_TAIL_LEN, 123);
        assert_eq!(VAULT_SPACE_NO_QUORUM, 7173); // AV-195: +309, AV-196: +1
        assert_eq!(VAULT_SPACE, 7663); // AV-195: +309, AV-196: +1
        assert_eq!(ESCROW_BODY_LEN, 7655); // AV-195: +309, AV-196: +1
        assert_eq!(vault_close_rent_reclaimed(), 54_225_360);
        let n = VAULT_FIELDS.len();
        assert_eq!(VAULT_FIELDS[n - (21+2)].0, "dual_control_checker"); // AV-191: +3
        assert_eq!(VAULT_FIELDS[n - (21+2)].1, "Option<Pubkey>");
        assert_eq!(VAULT_FIELDS[n - (21+2)].2, 33);
        assert_eq!(VAULT_FIELDS[n - (20+2)].0, "dual_control_intent");
        assert_eq!(VAULT_FIELDS[n - (20+2)].1, "Option<DualControlIntent>");
        assert_eq!(VAULT_FIELDS[n - (20+2)].2, 90);
        // AV-131: the disputed-amount counter trailed the dual-control
        // tail.
        assert_eq!(VAULT_FIELDS[n - (19+2)].0, "disputed_amount");
        assert_eq!(VAULT_FIELDS[n - (19+2)].1, "u64");
        assert_eq!(VAULT_FIELDS[n - (19+2)].2, 8);
        // AV-133: the auto-unpause timestamp trailed the dispute tail.
        assert_eq!(VAULT_FIELDS[n - (18+2)].0, "auto_unpause_at");
        assert_eq!(VAULT_FIELDS[n - (15+2)].1, "Option<u64>");
        assert_eq!(VAULT_FIELDS[n - (15+2)].2, 9);
        // AV-134: the funding amount bounds trailed the auto-unpause
        // tail.
        assert_eq!(VAULT_FIELDS[n - (17+2)].0, "min_funding_amount"); // AV-191: +3
        assert_eq!(VAULT_FIELDS[n - (17+2)].1, "Option<u64>");
        assert_eq!(VAULT_FIELDS[n - (17+2)].2, 9);
        assert_eq!(VAULT_FIELDS[n - (16+2)].0, "max_funding_amount");
        assert_eq!(VAULT_FIELDS[n - (16+2)].1, "Option<u64>");
        assert_eq!(VAULT_FIELDS[n - (16+2)].2, 9);
        assert_eq!(AMOUNT_BOUNDS_TAIL_LEN, 18);
        // AV-135: the arbiter adjudication fee tail — 9-byte flat
        // slice + 3-byte bps rate (no longer the absolute tail;
        // AV-139's rent-sweep tail sits after it).
        assert_eq!(VAULT_FIELDS[n - (15+2)].0, "arbiter_fee_flat"); // AV-191: +3
        assert_eq!(VAULT_FIELDS[n - (15+2)].1, "Option<u64>");
        assert_eq!(VAULT_FIELDS[n - (15+2)].2, 9);
        assert_eq!(VAULT_FIELDS[n - (14+2)].0, "arbiter_fee_bps");
        assert_eq!(VAULT_FIELDS[n - (14+2)].1, "Option<u16>");
        assert_eq!(VAULT_FIELDS[n - (14+2)].2, 3);
        // AV-139: the rent-sweep tail — terminal_at +
        // rent_sweep_grace_secs (no longer the absolute tail;
        // AV-148's taker_locked sits after it, AV-149's
        // claimants roster after that, AV-150's vesting-pause
        // marker after that, and AV-157's mint-allowlist after that).
        assert_eq!(VAULT_FIELDS[n - (8+2)].0, "mint_allowlist"); // AV-191: +3
        assert_eq!(VAULT_FIELDS[n - (8+2)].1, "Option<MintAllowlist>");
        assert_eq!(VAULT_FIELDS[n - (8+2)].2, 1 + MINT_ALLOWLIST_LEN);
        assert_eq!(VAULT_FIELDS[n - (9+2)].0, "vesting_pause");
        assert_eq!(VAULT_FIELDS[n - (9+2)].1, "Option<VestingPause>");
        assert_eq!(VAULT_FIELDS[n - (9+2)].2, VESTING_PAUSE_TAIL_LEN);
        assert_eq!(VAULT_FIELDS[n - (10+2)].0, "claimants"); // AV-191: +3
        assert_eq!(VAULT_FIELDS[n - (10+2)].1, "Option<ClaimantRoster>");
        assert_eq!(VAULT_FIELDS[n - (10+2)].2, CLAIMANT_ROSTER_TAIL_LEN);
        assert_eq!(VAULT_FIELDS[n - (11+2)].0, "taker_locked");
        assert_eq!(VAULT_FIELDS[n - (11+2)].1, "u64");
        assert_eq!(VAULT_FIELDS[n - (11+2)].2, 8);
        assert_eq!(VAULT_FIELDS[n - (12+2)].0, "rent_sweep_grace_secs");
        assert_eq!(VAULT_FIELDS[n - (12+2)].1, "u64");
        assert_eq!(VAULT_FIELDS[n - (12+2)].2, 8);
        assert_eq!(VAULT_FIELDS[n - (13+2)].0, "terminal_at");
        assert_eq!(VAULT_FIELDS[n - (13+2)].1, "u64");
        assert_eq!(VAULT_FIELDS[n - (13+2)].2, 8);
        assert_eq!(RENT_SWEEP_TAIL_LEN, 16);
    }

    #[test]
    fn dual_control_tail_survives_serialization_round_trip() {
        let e = declared(400_000, NOW);
        let body = super::account_space_tests::encode_escrow(&e);
        assert_eq!(body.len(), ESCROW_BODY_LEN);
        let mut account = vault_account_discriminator().to_vec();
        account.extend_from_slice(&body);
        let decoded = decode_vault_account(&account).unwrap();
        assert_eq!(decoded.dual_control_checker(), Some(CHECKER));
        let intent = decoded.dual_control_intent().unwrap();
        assert_eq!(intent.amount, 400_000);
        assert_eq!(intent.mint, None);
        assert_eq!(intent.payout_to, BOB);
        assert_eq!(intent.initiated_at, NOW);
        assert_eq!(intent.intent_expires_at, NOW + TTL);
    }

    #[test]
    fn escrow_state_gains_no_new_variant() {
        // AV-130 reuses Funded for the two-step protocol — the state
        // enum's discriminants stay stable.
        assert_eq!(EscrowState::Uninitialized as u8, 0);
        assert_eq!(EscrowState::Funded as u8, 1);
        assert_eq!(EscrowState::Released as u8, 2);
    }

    // ----- IndexedEscrow events -----

    #[test]
    fn indexed_escrow_emits_dual_control_lifecycle_events() {
        use crate::events::IndexedEscrow;
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xE0; 32], NOW)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let before = e.event_count();
        e.initiate_release(ALICE, 400_000, None, BOB, TTL, NOW)
            .unwrap();
        assert_eq!(e.event_count(), before + 1);
        let ev = e.events().last().unwrap();
        assert_eq!(ev.kind, EscrowEventKind::DualControlInitiated);
        assert_eq!(ev.from, EscrowState::Funded);
        assert_eq!(ev.to, EscrowState::Funded);

        let (payout, _) = e.confirm_release(CHECKER, NOW + 100).unwrap();
        assert_eq!(payout, 400_000);
        let ev = e.events().last().unwrap();
        assert_eq!(ev.kind, EscrowEventKind::DualControlConfirmed);
        assert_eq!(ev.from, EscrowState::Funded);
        assert_eq!(ev.to, EscrowState::Funded);

        e.initiate_release(ALICE, 100_000, None, BOB, TTL, NOW + 200)
            .unwrap();
        e.cancel_release(CHECKER, NOW + 300).unwrap();
        let ev = e.events().last().unwrap();
        assert_eq!(ev.kind, EscrowEventKind::DualControlCancelled);
        assert_eq!(ev.from, EscrowState::Funded);
        assert_eq!(ev.to, EscrowState::Funded);
    }

    #[test]
    fn indexed_escrow_failed_dual_control_calls_emit_nothing() {
        use crate::events::IndexedEscrow;
        let mut e = IndexedEscrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT, [0xE0; 32], NOW)
            .unwrap()
            .with_dual_control(CHECKER)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let before = e.event_count();
        // Stranger declares: Unauthorized, no event.
        assert_eq!(
            e.initiate_release(MALLORY, 400_000, None, BOB, TTL, NOW)
                .unwrap_err(),
            EscrowError::Unauthorized
        );
        assert_eq!(e.event_count(), before);
        // Nothing to confirm: no event.
        assert_eq!(
            e.confirm_release(CHECKER, NOW).unwrap_err(),
            EscrowError::DualControlNotInitiated
        );
        assert_eq!(e.event_count(), before);
    }
}

// ---------- AV-134: vault funding amount bounds ----------
mod amount_bounds_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_750_000_000;

    const AMOUNT: u64 = 1_000_000;
    const MIN: u64 = 100_000;
    const MAX: u64 = 900_000;

    /// An `Uninitialized` escrow with the AV-134 window attached.
    fn bounded() -> Escrow {
        Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(MIN, MAX)
            .unwrap()
    }

    // ----- the builder -----

    #[test]
    fn with_amount_bounds_happy_path() {
        let e = bounded();
        assert_eq!(e.amount_bounds(), Some((MIN, MAX)));
        assert_eq!(e.min_funding_amount(), Some(MIN));
        assert_eq!(e.max_funding_amount(), Some(MAX));
        assert_eq!(e.state(), EscrowState::Uninitialized);
    }

    #[test]
    fn with_amount_bounds_rejects_an_inverted_window() {
        let err = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(MAX, MIN)
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidAmountBounds);
        assert_eq!(err.code(), 196);
    }

    #[test]
    fn with_amount_bounds_accepts_a_degenerate_window() {
        // min == max is a legal (if tight) window — the deposit must
        // land exactly on it; only an inversion is a config error.
        let e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(AMOUNT, AMOUNT)
            .unwrap();
        assert_eq!(e.amount_bounds(), Some((AMOUNT, AMOUNT)));
    }

    #[test]
    fn with_amount_bounds_is_uninitialized_only() {
        // Fund a window-conformant amount first (1_000_000 would trip
        // the ceiling — use MIN as the deal size).
        let mut e = Escrow::initialize(ALICE, BOB, MIN, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(MIN, MAX)
            .unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e.with_amount_bounds(MIN, MAX).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn amount_bounds_error_codes_are_pinned() {
        assert_eq!(EscrowError::InvalidAmountBounds.code(), 196);
        assert_eq!(EscrowError::AmountOutOfBounds.code(), 197);
        assert!(EscrowError::all().contains(&EscrowError::InvalidAmountBounds));
        assert!(EscrowError::all().contains(&EscrowError::AmountOutOfBounds));
    }

    // ----- fund -----

    #[test]
    fn fund_rejects_a_deposit_below_the_floor() {
        // amount == 1_000_000 sits above max == 900_000: widen the
        // window first so only the floor is under test.
        let mut e = Escrow::initialize(ALICE, BOB, 50_000, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(MIN, MAX)
            .unwrap();
        let err = e.fund(ALICE, NOW).unwrap_err();
        assert_eq!(err, EscrowError::AmountOutOfBounds);
        assert_eq!(err.code(), 197);
        assert_eq!(e.state(), EscrowState::Uninitialized);
        assert_eq!(e.funded_total(), 0);
    }

    #[test]
    fn fund_rejects_a_deposit_above_the_ceiling() {
        let mut e = bounded();
        let err = e.fund(ALICE, NOW).unwrap_err();
        assert_eq!(err, EscrowError::AmountOutOfBounds);
        assert_eq!(err.code(), 197);
        // A rejected deposit moves nothing.
        assert_eq!(e.state(), EscrowState::Uninitialized);
        assert_eq!(e.funded_total(), 0);
        assert_eq!(e.fund_at(), 0);
    }

    #[test]
    fn fund_accepts_the_window_edges_exactly() {
        for edge in [MIN, MAX] {
            let mut e = Escrow::initialize(ALICE, BOB, edge, EXPIRES_AT)
                .unwrap()
                .with_amount_bounds(MIN, MAX)
                .unwrap();
            e.fund(ALICE, NOW).unwrap();
            assert_eq!(e.state(), EscrowState::Funded);
            assert_eq!(e.funded_total(), edge);
            assert_eq!(e.fund_at(), NOW);
        }
    }

    #[test]
    fn fund_check_order_authority_state_before_amount() {
        let mut e = bounded();
        // A stranger learns nothing about the window: Unauthorized
        // wins over AmountOutOfBounds.
        assert_eq!(
            e.fund(MALLORY, NOW).unwrap_err(),
            EscrowError::Unauthorized
        );
        // A double fund is a state error even when the amount is
        // out of bounds: the state gate precedes the amount gate.
        let mut ok = Escrow::initialize(ALICE, BOB, MIN, EXPIRES_AT)
            .unwrap()
            .with_amount_bounds(MIN, MAX)
            .unwrap();
        ok.fund(ALICE, NOW).unwrap();
        assert_eq!(
            ok.fund(ALICE, NOW).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
    }

    #[test]
    fn fund_without_bounds_is_unchanged() {
        // Backward compatible: no opt-in, no gate — any positive
        // amount funds exactly like before AV-134.
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        assert_eq!(e.amount_bounds(), None);
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        assert_eq!(e.funded_total(), AMOUNT);
    }

    // ----- fund_tranche (AV-111 combination) -----

    /// A tranched escrow (4 tranches of 250_000) with the window
    /// attached: every tranche must sit inside [100_000, 900_000].
    fn tranched() -> Escrow {
        let mut e = bounded();
        e.with_funding_plan(AMOUNT, 4).unwrap();
        e
    }

    #[test]
    fn fund_tranche_rejects_an_out_of_bounds_tranche() {
        let mut e = tranched();
        // Below the floor.
        assert_eq!(
            e.fund_tranche(ALICE, MIN - 1, NOW).unwrap_err(),
            EscrowError::AmountOutOfBounds
        );
        // Above the ceiling.
        assert_eq!(
            e.fund_tranche(ALICE, MAX + 1, NOW).unwrap_err(),
            EscrowError::AmountOutOfBounds
        );
        // Rejected tranches consume nothing.
        assert_eq!(e.funded_total(), 0);
        assert_eq!(e.state(), EscrowState::Uninitialized);
    }

    #[test]
    fn fund_tranche_accepts_window_edges_and_completes_the_plan() {
        let mut e = tranched();
        // Edge tranches: the floor and the ceiling both pass.
        e.fund_tranche(ALICE, MIN, NOW).unwrap();
        e.fund_tranche(ALICE, MAX - MIN, NOW).unwrap();
        e.fund_tranche(ALICE, MIN, NOW).unwrap();
        // A fourth tranche inside the window would push funded_total
        // past the plan's total: the plan's overfund cap still fires.
        assert_eq!(
            e.fund_tranche(ALICE, MIN, NOW).unwrap_err(),
            EscrowError::AmountMismatch,
            "the plan's total still caps the deposits"
        );
        // Four in-window tranches complete the 1_000_000 plan.
        let mut e2 = tranched();
        for _ in 0..4 {
            e2.fund_tranche(ALICE, 250_000, NOW).unwrap();
        }
        assert_eq!(e2.funded_total(), AMOUNT);
        assert_eq!(e2.state(), EscrowState::Funded);
        assert!(e2.is_funding_complete());
    }

    #[test]
    fn fund_tranche_without_bounds_is_unchanged() {
        // Backward compatible: a plan with no bounds keeps the
        // existing tranche semantics.
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        e.with_funding_plan(AMOUNT, 2).unwrap();
        assert_eq!(e.amount_bounds(), None);
        e.fund_tranche(ALICE, 1, NOW).unwrap();
        e.fund_tranche(ALICE, AMOUNT - 1, NOW).unwrap();
        assert_eq!(e.funded_total(), AMOUNT);
    }

    // ----- layout pins -----

    #[test]
    fn amount_bounds_tail_layout_is_pinned() {
        assert_eq!(AMOUNT_BOUNDS_TAIL_LEN, 18);
        assert_eq!(ESCROW_BODY_LEN, 7655); // AV-195: +309, AV-196: +1
        assert_eq!(VAULT_SPACE, 7663); // AV-195: +309, AV-196: +1
        assert_eq!(VAULT_SPACE_NO_QUORUM, 7173); // AV-195: +309, AV-196: +1
        // (128 + 7663) * 3480 * 2 = 7791 * 6960 — the main formula,
        // recomputed for the grown account (AV-191: +43).
        assert_eq!(vault_close_rent_reclaimed(), 54_225_360);
        assert_eq!(
            check_vault_rent_exempt(54_225_360, MAINNET_LAMPORTS_PER_BYTE_YEAR, MAINNET_EXEMPTION_THRESHOLD_YEARS),
            Ok(())
        );
        let n = VAULT_FIELDS.len();
        // AV-191: the referral tail appended 3 fields after these.
        assert_eq!(VAULT_FIELDS[n - (17+2)].0, "min_funding_amount");
        assert_eq!(VAULT_FIELDS[n - (17+2)].2, 9);
        assert_eq!(VAULT_FIELDS[n - (16+2)].0, "max_funding_amount");
        assert_eq!(VAULT_FIELDS[n - (16+2)].2, 9);
        // The AV-133 tail offset is unchanged: the new regions went
        // after it, not before (body offset — the IDL's 5514 includes
        // the 8-byte discriminator).
        let auto_unpause_offset: usize = VAULT_FIELDS[..n - (18+2)].iter().map(|f| f.2).sum();
        assert_eq!(auto_unpause_offset, 5907);
    }

    #[test]
    fn amount_bounds_survive_the_encode_decode_round_trip() {
        let e = bounded();
        let body = super::account_space_tests::encode_escrow(&e);
        assert_eq!(body.len(), ESCROW_BODY_LEN);
        let mut account = crate::discriminator::vault_account_discriminator().to_vec();
        account.extend_from_slice(&body);
        let decoded = crate::discriminator::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.amount_bounds(), Some((MIN, MAX)));
        // The tail bytes are the two Option<u64> regions: 1, LE(min),
        // 1, LE(max) — sitting just before the AV-135 arbiter-fee
        // tail (which is itself before the AV-139 rent-sweep tail,
        // the AV-148 taker counter-fund, and the AV-149 claimant
        // roster).
        let tail = &body[body.len() - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - RENT_SWEEP_TAIL_LEN - ARBITER_FEE_TAIL_LEN
            - AMOUNT_BOUNDS_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..body.len() - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - RENT_SWEEP_TAIL_LEN - ARBITER_FEE_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN];
        assert_eq!(tail[0], 1);
        assert_eq!(&tail[1..9], &MIN.to_le_bytes());
        assert_eq!(tail[9], 1);
        assert_eq!(&tail[10..18], &MAX.to_le_bytes());
    }

    #[test]
    fn unconfigured_bounds_encode_as_zeroed_tail() {
        let e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        let body = super::account_space_tests::encode_escrow(&e);
        // The bounds region sits just before the AV-135 arbiter-fee
        // tail — both zeroed on a fresh escrow.
        let tail = &body[body.len() - ARBITER_FEE_TAIL_LEN - AMOUNT_BOUNDS_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN..body.len() - ARBITER_FEE_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN];
        assert_eq!(tail, &[0u8; 18]);
        let mut account = crate::discriminator::vault_account_discriminator().to_vec();
        account.extend_from_slice(&body);
        let decoded = crate::discriminator::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.amount_bounds(), None);
    }
}

// ----- AV-135: arbiter adjudication fee -----

#[cfg(test)]
mod arbiter_fee_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const ARBITER: [u8; 32] = [0xA8; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;

    fn uninitialized() -> Escrow {
        Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap()
    }

    fn disputed_with_fee(flat: u64, bps: u16) -> Escrow {
        let mut e = uninitialized()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_arbiter_fee(flat, bps)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.escalate(ALICE, EXPIRES_AT - 1, e.remaining_amount(), None, None, 0)
            .unwrap();
        e
    }

    fn disputed_plain() -> Escrow {
        let mut e = uninitialized().with_arbiter(ARBITER).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.escalate(ALICE, EXPIRES_AT - 1, e.remaining_amount(), None, None, 0)
            .unwrap();
        e
    }

    // ----- the builder -----

    #[test]
    fn with_arbiter_fee_happy_path() {
        let e = uninitialized().with_arbiter_fee(5_000, 250).unwrap();
        assert_eq!(e.arbiter_fee_flat(), Some(5_000));
        assert_eq!(e.arbiter_fee_bps(), Some(250));
        assert_eq!(e.state(), EscrowState::Uninitialized);
    }

    #[test]
    fn with_arbiter_fee_zero_zero_disables() {
        // (0, 0) is the opt-out: both legs stay None.
        let e = uninitialized().with_arbiter_fee(0, 0).unwrap();
        assert_eq!(e.arbiter_fee_flat(), None);
        assert_eq!(e.arbiter_fee_bps(), None);
    }

    #[test]
    fn with_arbiter_fee_rejects_bps_above_10000() {
        let err = uninitialized().with_arbiter_fee(0, 10_001).unwrap_err();
        assert_eq!(err, EscrowError::InvalidArbiterFee);
        assert_eq!(err.code(), 198);
    }

    #[test]
    fn with_arbiter_fee_accepts_10000_bps() {
        let e = uninitialized().with_arbiter_fee(0, 10_000).unwrap();
        assert_eq!(e.arbiter_fee_bps(), Some(10_000));
    }

    #[test]
    fn with_arbiter_fee_uninitialized_only() {
        // A live escrow cannot retune the fee — the terms are fixed
        // before any funds move, like the arbiter binding itself.
        // `with_arbiter_fee` takes `self` by value, so the rejected
        // call cannot mutate anything.
        let e = disputed_with_fee(0, 0);
        assert_eq!(
            e.with_arbiter_fee(1, 1),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn invalid_arbiter_fee_error_code_is_pinned() {
        // Error codes are never renumbered: 196/197 belong to AV-134.
        assert_eq!(EscrowError::InvalidArbiterFee.code(), 198);
        assert_eq!(EscrowError::InvalidAmountBounds.code(), 196);
        assert_eq!(EscrowError::AmountOutOfBounds.code(), 197);
    }

    // ----- the fee math -----

    #[test]
    fn arbiter_fee_for_flat_and_bps() {
        let e = uninitialized().with_arbiter_fee(5_000, 250).unwrap();
        // flat + floor(1_000_000 * 250 / 10_000) = 5_000 + 25_000.
        assert_eq!(e.arbiter_fee_for(1_000_000), 30_000);
        // The bps leg floors: floor(10_000 * 250 / 10_000) = 250.
        assert_eq!(e.arbiter_fee_for(10_000), 5_250);
        assert_eq!(e.arbiter_fee_for(0), 0);
        // Pure bps floors without rounding up: floor(999 * 250 / 10_000) = 24.
        let e = uninitialized().with_arbiter_fee(0, 250).unwrap();
        assert_eq!(e.arbiter_fee_for(999), 24);
    }

    #[test]
    fn arbiter_fee_for_unconfigured_is_zero() {
        assert_eq!(uninitialized().arbiter_fee_for(1_000_000), 0);
    }

    #[test]
    fn arbiter_fee_for_caps_at_the_share() {
        // A flat leg larger than the share caps — the payout can
        // never go negative.
        let e = uninitialized().with_arbiter_fee(1_000_000, 0).unwrap();
        assert_eq!(e.arbiter_fee_for(600_000), 600_000);
        // 100% bps takes the whole share.
        let e = uninitialized().with_arbiter_fee(0, 10_000).unwrap();
        assert_eq!(e.arbiter_fee_for(600_000), 600_000);
    }

    #[test]
    fn arbiter_fee_for_cannot_overflow() {
        // u64::MAX * 10_000 < u128::MAX — the worst case fits in u128.
        let e = uninitialized()
            .with_arbiter_fee(u64::MAX, 10_000)
            .unwrap();
        assert_eq!(e.arbiter_fee_for(u64::MAX), u64::MAX);
        let e = uninitialized().with_arbiter_fee(1, 1).unwrap();
        assert_eq!(
            e.arbiter_fee_for(u64::MAX),
            1 + (u64::MAX as u128 / 10_000u128) as u64
        );
    }

    // ----- the three settlement paths -----

    #[test]
    fn resolve_charges_the_flat_fee() {
        let mut e = disputed_with_fee(50_000, 0);
        let (payout, fee, refund) =
            e.resolve(ARBITER, 600_000, 0, None, None, BOB).unwrap();
        assert_eq!((payout, fee, refund), (550_000, 0, 400_000));
        assert_eq!(e.state(), EscrowState::Settled);
    }

    #[test]
    fn resolve_charges_the_bps_fee() {
        // 10% of the post-fee share: floor(600_000 * 1_000 / 10_000).
        let mut e = disputed_with_fee(0, 1_000);
        let (payout, fee, refund) =
            e.resolve(ARBITER, 600_000, 0, None, None, BOB).unwrap();
        assert_eq!((payout, fee, refund), (540_000, 0, 400_000));
    }

    #[test]
    fn resolve_fee_zero_is_backward_compatible() {
        // (0, 0) and never-configured settle exactly like the legacy split.
        let mut e = disputed_with_fee(0, 0);
        assert_eq!(
            e.resolve(ARBITER, 600_000, 0, None, None, BOB).unwrap(),
            (600_000, 0, 400_000)
        );
        let mut e = disputed_plain();
        assert_eq!(
            e.resolve(ARBITER, 600_000, 0, None, None, BOB).unwrap(),
            (600_000, 0, 400_000)
        );
    }

    #[test]
    fn resolve_deduction_order_protocol_then_arbiter() {
        // AV-17 protocol fee and AV-135 arbiter fee stack orthogonally:
        // the protocol fee slices the gross share first, the arbiter
        // fee slices the post-fee share.
        let mut e = uninitialized()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_protocol_fee(1_000) // 10%
            .unwrap()
            .with_arbiter_fee(5_000, 500) // flat + 5% of the post-fee share
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.escalate(ALICE, EXPIRES_AT - 1, e.remaining_amount(), None, None, 0)
            .unwrap();
        // protocol: floor(600_000 * 1_000 / 10_000) = 60_000;
        // arbiter: 5_000 + floor(540_000 * 500 / 10_000) = 32_000.
        let (payout, fee, refund) =
            e.resolve(ARBITER, 600_000, 0, None, None, BOB).unwrap();
        assert_eq!(fee, 60_000);
        assert_eq!(payout, 600_000 - 60_000 - 32_000);
        assert_eq!(refund, 400_000);
    }

    #[test]
    fn panel_settling_vote_charges_the_fee() {
        const M1: [u8; 32] = [0xC1; 32];
        let mut e = uninitialized()
            .with_arbiter_panel(&[M1], 1)
            .unwrap()
            .with_arbiter_fee(0, 2_500) // 25%
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e.escalate(ALICE, EXPIRES_AT - 1, e.remaining_amount(), None, None, 0)
            .unwrap();
        // One vote settles at M=1; the fee slices the winning share.
        let settled = e
            .submit_panel_judgment(M1, 600_000, EXPIRES_AT - 1, None, None, BOB)
            .unwrap()
            .expect("settles at threshold 1");
        // floor(600_000 * 2_500 / 10_000) = 150_000.
        assert_eq!(settled, (450_000, 0, 400_000));
        assert_eq!(e.state(), EscrowState::Settled);
    }

    #[test]
    fn default_judgment_charges_the_fee() {
        // A configured + confirmed default judgment, disputed at T:
        // the fee slices the pre-agreed taker amount.
        let mut e = uninitialized()
            .with_arbiter(ARBITER)
            .unwrap()
            .with_arbitration_deadline(3_600, 600_000)
            .unwrap()
            .with_arbiter_fee(10_000, 0)
            .unwrap();
        e.confirm_default_judgment(BOB).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        let disputed_at = EXPIRES_AT - 10_000;
        e.escalate(ALICE, disputed_at, e.remaining_amount(), None, None, 0)
            .unwrap();
        let (payout, fee, refund) = e
            .trigger_default_judgment(ALICE, disputed_at + 3_600, None, BOB)
            .unwrap();
        assert_eq!((payout, fee, refund), (590_000, 0, 400_000));
        assert_eq!(e.state(), EscrowState::Settled);
    }

    // ----- persistence -----

    #[test]
    fn fee_tail_round_trips_through_account_bytes() {
        use crate::account_space_tests::encode_escrow;
        let e = uninitialized().with_arbiter_fee(7_000, 333).unwrap();
        let bytes = encode_escrow(&e);
        assert_eq!(bytes.len(), ESCROW_BODY_LEN);
        // Tail layout: 9-byte flat slice then the 3-byte bps rate.
        let flat_at = ESCROW_BODY_LEN - CLAIMANT_ROSTER_TAIL_LEN - VESTING_PAUSE_TAIL_LEN - TAKER_LOCKED_TAIL_LEN - ARBITER_FEE_TAIL_LEN - RENT_SWEEP_TAIL_LEN - MINT_ALLOWLIST_TAIL_LEN - GOVERNANCE_DELAY_TAIL_LEN - GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(bytes[flat_at], 1, "flat Some discriminant");
        assert_eq!(
            u64::from_le_bytes(bytes[flat_at + 1..flat_at + 9].try_into().unwrap()),
            7_000
        );
        let bps_at = flat_at + 9;
        assert_eq!(bytes[bps_at], 1, "bps Some discriminant");
        assert_eq!(
            u16::from_le_bytes(bytes[bps_at + 1..bps_at + 3].try_into().unwrap()),
            333
        );
        // Full decode preserves the configuration.
        let mut account = crate::discriminator::vault_account_discriminator().to_vec();
        account.extend_from_slice(&bytes);
        let decoded = crate::discriminator::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.arbiter_fee_flat(), Some(7_000));
        assert_eq!(decoded.arbiter_fee_bps(), Some(333));
        assert_eq!(decoded.arbiter_fee_for(600_000), 7_000 + 19_980);
    }
}

#[cfg(test)]
mod rent_sweep_tests {
    use super::*;

    const NOW: u64 = 1_700_000_000;
    const GRACE: u64 = 30 * 24 * 3600;

    fn key(seed: u8) -> [u8; 32] {
        [seed; 32]
    }

    fn funded_escrow() -> Escrow {
        Escrow::initialize(key(1), key(2), 1_000_000, NOW + 10_000)
            .unwrap()
            .with_rent_sweep_grace_secs(0)
            .unwrap()
    }

    fn funded() -> Escrow {
        let mut e = funded_escrow();
        e.fund(key(1), NOW).unwrap();
        e
    }

    #[test]
    fn grace_defaults_to_30_days() {
        let e = funded_escrow();
        assert_eq!(e.rent_sweep_grace_secs(), 0);
        assert_eq!(e.effective_rent_sweep_grace_secs(), GRACE);
        assert_eq!(e.effective_rent_sweep_grace_secs(), DEFAULT_RENT_SWEEP_GRACE_SECS);
    }

    #[test]
    fn custom_grace_is_honored() {
        let e = funded_escrow().with_rent_sweep_grace_secs(3600).unwrap();
        assert_eq!(e.rent_sweep_grace_secs(), 3600);
        assert_eq!(e.effective_rent_sweep_grace_secs(), 3600);
    }

    #[test]
    fn grace_builder_rejected_after_funding() {
        let e = funded();
        // Builder takes self by value; after funding the state is
        // Funded, not Uninitialized.
        let result = e.with_rent_sweep_grace_secs(3600);
        assert_eq!(result.unwrap_err(), EscrowError::InvalidStateTransition);
    }

    #[test]
    fn terminal_at_stamped_on_cancel() {
        let mut e = funded();
        assert_eq!(e.terminal_at(), 0);
        e.cancel(key(1), None, key(1), NOW + 100).unwrap();
        assert_eq!(e.terminal_at(), NOW + 100);
        assert_eq!(e.state(), EscrowState::Cancelled);
    }

    #[test]
    fn terminal_at_stamped_on_release() {
        let mut e = funded();
        e.release(key(1), NOW + 200, 1_000_000, None, key(2)).unwrap();
        assert_eq!(e.terminal_at(), NOW + 200);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn not_eligible_before_grace_elapses() {
        let mut e = funded();
        e.cancel(key(1), None, key(1), NOW).unwrap();
        // Grace not elapsed: not eligible.
        assert!(!e.is_rent_sweep_eligible(NOW + GRACE - 1));
        assert_eq!(
            e.sweep_unclaimed_rent(key(9), NOW + GRACE - 1),
            Err(EscrowError::SweepGraceNotElapsed)
        );
    }

    #[test]
    fn eligible_after_grace_elapses() {
        let mut e = funded();
        e.cancel(key(1), None, key(1), NOW).unwrap();
        assert!(e.is_rent_sweep_eligible(NOW + GRACE));
        assert!(e.is_rent_sweep_eligible(NOW + GRACE + 1));
    }

    #[test]
    fn sweep_moves_rent_only_and_closes() {
        let mut e = funded();
        e.cancel(key(1), None, key(1), NOW).unwrap();
        let rent = e.sweep_unclaimed_rent(key(9), NOW + GRACE).unwrap();
        assert_eq!(rent, vault_close_rent_reclaimed());
        assert_eq!(e.state(), EscrowState::Closed);
        // Escrowed funds were already refunded on cancel; the sweep
        // moved only the rent-exempt lamports.
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn double_sweep_rejected() {
        let mut e = funded();
        e.cancel(key(1), None, key(1), NOW).unwrap();
        e.sweep_unclaimed_rent(key(9), NOW + GRACE).unwrap();
        // Already Closed: not a closeable terminal state.
        assert_eq!(
            e.sweep_unclaimed_rent(key(9), NOW + GRACE + 1),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn sweep_rejected_when_not_terminal() {
        let mut e = funded();
        // Funded is not terminal.
        assert_eq!(
            e.sweep_unclaimed_rent(key(9), NOW + GRACE),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn keeper_scan_lists_only_eligible() {
        use crate::keeper::{scan_unclaimed_rent, WatchedEscrow};
        let mut e1 = funded();
        e1.cancel(key(1), None, key(1), NOW).unwrap(); // eligible at NOW+GRACE
        // e2 uses a longer custom grace, so it is not yet eligible at
        // NOW+GRACE.
        let mut e2 = Escrow::initialize(key(1), key(2), 1_000_000, NOW + 10_000)
            .unwrap()
            .with_rent_sweep_grace_secs(GRACE + 100)
            .unwrap();
        e2.fund(key(1), NOW).unwrap();
        e2.cancel(key(1), None, key(1), NOW).unwrap(); // eligible at NOW+GRACE+100
        let e3 = funded(); // not terminal

        let watched = vec![
            WatchedEscrow {
                escrow_id: key(11),
                escrow: e1,
                reference: None,
                vault_derivation: None,
                pending_intent: None,
            },
            WatchedEscrow {
                escrow_id: key(22),
                escrow: e2,
                reference: None,
                vault_derivation: None,
                pending_intent: None,
            },
            WatchedEscrow {
                escrow_id: key(33),
                escrow: e3,
                reference: None,
                vault_derivation: None,
                pending_intent: None,
            },
        ];
        // At NOW+GRACE: only e1 is eligible.
        let report = scan_unclaimed_rent(&watched, NOW + GRACE);
        assert_eq!(report.sweepable.len(), 1);
        assert_eq!(report.sweepable[0].escrow_id, key(11));
        assert_eq!(report.sweepable[0].state, EscrowState::Cancelled);
        assert_eq!(report.total_rent_lamports, vault_close_rent_reclaimed());
        // Before grace: none eligible.
        let report = scan_unclaimed_rent(&watched, NOW + GRACE - 1);
        assert!(report.sweepable.is_empty());
        assert_eq!(report.total_rent_lamports, 0);
    }

}

// ---------- AV-148: bilateral taker counter-fund ----------

#[cfg(test)]
mod av148_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;

    fn funded() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    #[test]
    fn fund_taker_rejects_non_taker_authority() {
        let mut e = funded();
        // Stranger.
        assert_eq!(
            e.fund_taker(MALLORY, 100_000, EXPIRES_AT - 3_000),
            Err(EscrowError::Unauthorized)
        );
        // Initializer (not the taker).
        assert_eq!(
            e.fund_taker(ALICE, 100_000, EXPIRES_AT - 3_000),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.taker_locked(), 0);
    }

    #[test]
    fn fund_taker_requires_funded_state() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Uninitialized -> InvalidStateTransition.
        assert_eq!(
            e.fund_taker(BOB, 100_000, EXPIRES_AT - 3_600),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn fund_taker_rejects_zero_amount() {
        let mut e = funded();
        assert_eq!(
            e.fund_taker(BOB, 0, EXPIRES_AT - 3_000),
            Err(EscrowError::AmountMismatch)
        );
        assert_eq!(e.taker_locked(), 0);
    }

    #[test]
    fn fund_taker_accumulates_and_preserves_state() {
        let mut e = funded();
        e.fund_taker(BOB, 100_000, EXPIRES_AT - 3_000).unwrap();
        assert_eq!(e.taker_locked(), 100_000);
        assert_eq!(e.state(), EscrowState::Funded);
        // Second call accumulates.
        e.fund_taker(BOB, 50_000, EXPIRES_AT - 2_000).unwrap();
        assert_eq!(e.taker_locked(), 150_000);
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn fund_taker_refuses_milestone_and_subscription() {
        // Milestone plan.
        let plan = MilestonePlan::new(&[250_000, 250_000, 250_000, 250_000]).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_milestones(plan)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        assert_eq!(
            e.fund_taker(BOB, 100_000, EXPIRES_AT - 3_000),
            Err(EscrowError::InvalidMilestones)
        );
    }

    #[test]
    fn cancel_returns_bilateral_legs() {
        let mut e = funded();
        e.fund_taker(BOB, 300_000, EXPIRES_AT - 3_000).unwrap();
        let (init_refund, taker_refund) = e.cancel(ALICE, None, ALICE, EXPIRES_AT - 1_000).unwrap();
        // Initializer gets their leg back, taker gets theirs.
        assert_eq!(init_refund, 1_000_000);
        assert_eq!(taker_refund, 300_000);
        assert_eq!(e.state(), EscrowState::Cancelled);
    }

    #[test]
    fn release_settles_from_bilateral_lockup() {
        let mut e = funded();
        e.fund_taker(BOB, 500_000, EXPIRES_AT - 3_000).unwrap();
        // Release 1_200_000: consumes the 1M initializer leg first,
        // then 200k of the taker's leg.
        let (payout, fee) = e.release(ALICE, EXPIRES_AT, 1_200_000, None, BOB).unwrap();
        assert_eq!(payout + fee, 1_200_000);
        assert_eq!(e.released_amount(), 1_200_000);
        // Remaining: 300k of taker's leg.
        let (init_leg, taker_leg) = e.bilateral_legs();
        assert_eq!(init_leg, 0);
        assert_eq!(taker_leg, 300_000);
    }

    #[test]
    fn bilateral_conservation_holds() {
        let mut e = funded();
        e.fund_taker(BOB, 400_000, EXPIRES_AT - 3_000).unwrap();
        // Inflow = 1M + 400k = 1.4M.
        let inflow = 1_400_000u64;
        // Release 500k.
        e.release(ALICE, EXPIRES_AT, 500_000, None, BOB).unwrap();
        // Cancel the rest.
        let (init_refund, taker_refund) = e.cancel(ALICE, None, ALICE, EXPIRES_AT - 1_000).unwrap();
        // Released (500k) + refunded (500k init + 400k taker) = 1.4M = inflow.
        assert_eq!(e.released_amount() + init_refund + taker_refund, inflow);
    }

    #[test]
    fn taker_locked_survives_encode_decode() {
        let mut e = funded();
        e.fund_taker(BOB, 123_456, EXPIRES_AT - 3_000).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        let mut account = vec![0u8; 8 + super::ESCROW_BODY_LEN];
        account[..8].copy_from_slice(&crate::discriminator::vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = crate::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.taker_locked(), 123_456);
    }

    #[test]
    fn taker_funded_event_kind_is_pinned() {
        let kind = EscrowEventKind::TakerFunded;
        assert_eq!(kind.discriminant(), 76);
        assert_eq!(EscrowEventKind::from_discriminant(76), Some(kind));
        assert_eq!(kind.name(), "taker_funded");
        assert_eq!(EscrowEventKind::from_name("taker_funded"), Some(kind));
    }
}

// ---------- AV-149: multi-taker share claiming ----------
//
// `with_claimants` opts the taker side into a pull roster (payroll
// run, revenue split, treasury beneficiaries); each claimant pulls
// their own bps share via `claim_share`, the claimed bitmask stops
// replays, and the last pull releases the escrow.
#[cfg(test)]
mod av149_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32]; // initializer
    const BOB: [u8; 32] = [0xBB; 32]; // taker (unused on the roster path)
    const MALLORY: [u8; 32] = [0xCC; 32]; // stranger
    const C1: [u8; 32] = [0xC1; 32];
    const C2: [u8; 32] = [0xC2; 32];
    const C3: [u8; 32] = [0xC3; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;

    fn rostered_funded(shares: &[([u8; 32], u16)]) -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_claimants(shares)
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e
    }

    #[test]
    fn with_claimants_rejects_malformed_tables() {
        let base = || Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        // Empty.
        assert_eq!(
            base().with_claimants(&[]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // Over 8.
        let many: Vec<([u8; 32], u16)> =
            (0..9).map(|i| ([i as u8 + 1; 32], 1112)).collect();
        assert_eq!(
            base().with_claimants(&many).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // Σ != 10_000 (under and over).
        assert_eq!(
            base().with_claimants(&[(C1, 5000), (C2, 4999)]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        assert_eq!(
            base().with_claimants(&[(C1, 5000), (C2, 5001)]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // Zero claimant address.
        assert_eq!(
            base().with_claimants(&[([0u8; 32], 10_000)]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // Zero share.
        assert_eq!(
            base().with_claimants(&[(C1, 0), (C2, 10_000)]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // Duplicate claimant.
        assert_eq!(
            base().with_claimants(&[(C1, 5000), (C1, 5000)]).unwrap_err(),
            EscrowError::InvalidClaimantShares
        );
        // A malformed table leaves no roster behind.
        let e = base();
        assert_eq!(e.claimants(), None);
    }

    #[test]
    fn with_claimants_rejects_reconfiguration_on_live_escrow() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        assert_eq!(
            e.clone().with_claimants(&[(C1, 10_000)]).unwrap_err(),
            EscrowError::InvalidStateTransition
        );
        // The original roster is untouched.
        let r = e.claimants().unwrap();
        assert_eq!(r.claimant_count, 2);
        assert_eq!(r.claimed, 0);
        let _ = e.claim_share(C1, C1, T0 + 1).unwrap();
    }

    #[test]
    fn with_claimants_attaches_roster() {
        let e = rostered_funded(&[(C1, 2500), (C2, 2500), (C3, 5000)]);
        let r = e.claimants().unwrap();
        assert!(r.is_configured());
        assert_eq!(r.claimant_count, 3);
        assert_eq!(r.find(C1), Some(0));
        assert_eq!(r.find(C2), Some(1));
        assert_eq!(r.find(C3), Some(2));
        assert_eq!(r.find(MALLORY), None);
        assert_eq!(r.share_bps[0], 2500);
        assert_eq!(r.unclaimed_bps(), 10_000);
        assert!(!r.all_claimed());
        // Plain escrows stay roster-less.
        let mut plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        plain.fund(ALICE, T0).unwrap();
        assert_eq!(plain.claimants(), None);
        assert!(!plain.claimants().unwrap_or_default().is_configured());
    }

    #[test]
    fn claim_share_rejects_wrong_authority_first() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        // Stranger, initializer, and one claimant pulling for another.
        for bad in [MALLORY, ALICE, C2] {
            assert_eq!(
                e.claim_share(bad, C1, T0 + 1),
                Err(EscrowError::Unauthorized),
                "authority {bad:?}"
            );
        }
        // Authority is checked before state: a stranger on an
        // Uninitialized escrow is Unauthorized, not
        // InvalidStateTransition.
        let mut fresh = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_claimants(&[(C1, 10_000)])
            .unwrap();
        assert_eq!(
            fresh.claim_share(MALLORY, C1, T0 + 1),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            fresh.claim_share(C1, C1, T0 + 1),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn claim_share_requires_funded_state() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_claimants(&[(C1, 10_000)])
            .unwrap();
        // Uninitialized.
        assert_eq!(
            e.claim_share(C1, C1, T0 + 1),
            Err(EscrowError::InvalidStateTransition)
        );
        e.fund(ALICE, T0).unwrap();
        e.cancel(ALICE, None, ALICE, T0 + 2).unwrap();
        // Terminal.
        assert_eq!(
            e.claim_share(C1, C1, T0 + 3),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn claim_share_rejects_non_roster_claimant() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        // On the roster's escrow but not on the roster — and the
        // authority check passes (caller == claimant), so this is
        // the roster gate, not the authority gate.
        assert_eq!(
            e.claim_share(MALLORY, MALLORY, T0 + 1),
            Err(EscrowError::ClaimantNotInRoster)
        );
        // Roster-less escrow: no legs to pull.
        let mut plain = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        plain.fund(ALICE, T0).unwrap();
        assert_eq!(
            plain.claim_share(C1, C1, T0 + 1),
            Err(EscrowError::ClaimantNotInRoster)
        );
        assert_eq!(e.claimants().unwrap().claimed, 0);
    }

    #[test]
    fn claim_share_rejects_double_claim() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        let (payout, fee) = e.claim_share(C1, C1, T0 + 1).unwrap();
        assert_eq!((payout, fee), (500_000, 0));
        assert_eq!(
            e.claim_share(C1, C1, T0 + 2),
            Err(EscrowError::ClaimantAlreadyClaimed)
        );
        // The other leg still pulls fine.
        let (payout2, _) = e.claim_share(C2, C2, T0 + 3).unwrap();
        assert_eq!(payout2, 500_000);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn claim_share_settles_pro_rata_and_conserves() {
        let mut e = rostered_funded(&[(C1, 2500), (C2, 2500), (C3, 5000)]);
        // Pull in roster order: each leg prices against the current
        // remainder over the unclaimed bps.
        let (p1, f1) = e.claim_share(C1, C1, T0 + 1).unwrap();
        assert_eq!((p1, f1), (250_000, 0));
        assert_eq!(e.state(), EscrowState::Funded);
        let (p2, f2) = e.claim_share(C2, C2, T0 + 2).unwrap();
        assert_eq!((p2, f2), (250_000, 0));
        // Last leg takes the whole remainder.
        let (p3, f3) = e.claim_share(C3, C3, T0 + 3).unwrap();
        assert_eq!((p3, f3), (500_000, 0));
        // Conservation: Σ payouts == locked amount; released keeps
        // the gross; nothing remains.
        assert_eq!(p1 + p2 + p3, 1_000_000);
        assert_eq!(e.released_amount(), 1_000_000);
        assert_eq!(e.remaining_amount(), 0);
        assert_eq!(e.state(), EscrowState::Released);
        assert!(e.claimants().unwrap().all_claimed());
    }

    #[test]
    fn claim_share_last_leg_absorbs_flooring_dust() {
        // 3333/3333/3334 bps on 10 lamports: the floored legs drop
        // fractions that the last leg sweeps.
        let mut e = Escrow::initialize(ALICE, BOB, 10, EXPIRES_AT)
            .unwrap()
            .with_claimants(&[(C1, 3333), (C2, 3333), (C3, 3334)])
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        let (p1, _) = e.claim_share(C1, C1, T0 + 1).unwrap();
        // floor(10 * 3333 / 10_000) = 3.
        assert_eq!(p1, 3);
        let (p2, _) = e.claim_share(C2, C2, T0 + 2).unwrap();
        // floor(7 * 3333 / 6667) = 3.
        assert_eq!(p2, 3);
        let (p3, _) = e.claim_share(C3, C3, T0 + 3).unwrap();
        // 10 - 3 - 3 = 4 (the dropped 0.33 + 0.33 dust lands here,
        // not lost).
        assert_eq!(p3, 4);
        assert_eq!(p1 + p2 + p3, 10);
        assert_eq!(e.released_amount(), 10);
        assert_eq!(e.remaining_amount(), 0);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn claim_share_prices_against_post_release_remainder() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        // The initializer pushes half out first; the roster splits
        // what is still locked.
        let (rp, _) = e.release(ALICE, T0 + 1, 400_000, None, BOB).unwrap();
        assert_eq!(rp, 400_000);
        let (p1, _) = e.claim_share(C1, C1, T0 + 2).unwrap();
        assert_eq!(p1, 300_000);
        let (p2, _) = e.claim_share(C2, C2, T0 + 3).unwrap();
        assert_eq!(p2, 300_000);
        // released keeps every gross: the push plus both pulls.
        assert_eq!(e.released_amount(), 1_000_000);
        assert_eq!(e.remaining_amount(), 0);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn claim_share_slices_protocol_fee_like_claim() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_claimants(&[(C1, 5000), (C2, 5000)])
            .unwrap()
            .with_protocol_fee(100) // 1%
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        // Gross 500_000, fee 5_000, net 495_000.
        let (p1, f1) = e.claim_share(C1, C1, T0 + 1).unwrap();
        assert_eq!((p1, f1), (495_000, 5_000));
        assert_eq!(e.fees_paid(), 5_000);
        assert_eq!(e.released_amount(), 500_000);
        // The fee is a routing slice of the gross: payout + fee ==
        // gross, and the last leg still sweeps the remainder.
        let (p2, f2) = e.claim_share(C2, C2, T0 + 2).unwrap();
        assert_eq!((p2, f2), (495_000, 5_000));
        assert_eq!(e.fees_paid(), 10_000);
        assert_eq!(e.released_amount(), 1_000_000);
        assert_eq!(e.remaining_amount(), 0);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn claim_share_refuses_milestone_escrow() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_claimants(&[(C1, 10_000)])
            .unwrap()
            .with_milestones(MilestonePlan::new(&[400_000, 600_000]).unwrap())
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        // The tranche plan owns the release path — the AV-13 claim
        // precedent.
        assert_eq!(
            e.claim_share(C1, C1, T0 + 1),
            Err(EscrowError::InvalidMilestones)
        );
        assert_eq!(e.claimants().unwrap().claimed, 0);
    }

    #[test]
    fn share_claimed_event_kind_is_pinned() {
        let kind = EscrowEventKind::ShareClaimed;
        assert_eq!(kind.discriminant(), 77);
        assert_eq!(EscrowEventKind::from_discriminant(77), Some(kind));
        assert_eq!(kind.name(), "share_claimed");
        assert_eq!(EscrowEventKind::from_name("share_claimed"), Some(kind));
    }

    #[test]
    fn claimant_roster_tail_len_is_pinned() {
        // 1-byte live count + 8 x 32-byte claimant slots + 8 x 2-byte
        // share slots + 1-byte claimed bitmask.
        assert_eq!(CLAIMANT_ROSTER_LEN, 1 + 8 * 32 + 8 * 2 + 1);
        assert_eq!(CLAIMANT_ROSTER_LEN, 274);
        assert_eq!(CLAIMANT_ROSTER_TAIL_LEN, 275);
        assert_eq!(MAX_CLAIMANTS, 8);
        assert_eq!(CLAIMANT_SHARE_TOTAL_BPS, 10_000);
    }

    #[test]
    fn claimant_roster_survives_encode_decode_roundtrip() {
        let mut e = rostered_funded(&[(C1, 5000), (C2, 5000)]);
        e.claim_share(C1, C1, T0 + 1).unwrap();
        let bytes = super::account_space_tests::encode_escrow(&e);
        assert_eq!(bytes.len(), crate::ESCROW_BODY_LEN);
        // The roster tail sits just before the body's end (the
        // AV-150 vesting-pause tail is the absolute tail): 1-byte
        // Some discriminant + the 274-byte region.
        let tail_at =
            bytes.len() - crate::VESTING_PAUSE_TAIL_LEN - crate::CLAIMANT_ROSTER_TAIL_LEN - crate::MINT_ALLOWLIST_TAIL_LEN - crate::GOVERNANCE_DELAY_TAIL_LEN - crate::GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(bytes[tail_at], 1, "Some discriminant");
        assert_eq!(bytes[tail_at + 1], 2, "live count");
        assert_eq!(&bytes[tail_at + 2..tail_at + 34], &C1, "first claimant");
        assert_eq!(&bytes[tail_at + 34..tail_at + 66], &C2, "second claimant");
        assert_eq!(&bytes[tail_at + 258..tail_at + 260], &5000u16.to_le_bytes());
        assert_eq!(&bytes[tail_at + 260..tail_at + 262], &5000u16.to_le_bytes());
        assert_eq!(bytes[tail_at + 274], 0b01, "claimed bitmask");
        // Full decode round-trips the roster and the bitmask.
        let mut account = vec![0u8; 8 + bytes.len()];
        account[..8].copy_from_slice(&crate::discriminator::vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = crate::decode_vault_account(&account).unwrap();
        assert_eq!(decoded, e);
        assert_eq!(decoded.claimants().unwrap().claimed, 0b01);
    }
}

#[cfg(test)]
mod av150_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32]; // initializer
    const BOB: [u8; 32] = [0xBB; 32]; // taker
    const MALLORY: [u8; 32] = [0xCC; 32]; // stranger
    const EXPIRES_AT: u64 = 1_800_000_000;
    const T0: u64 = 1_700_000_000;
    const AMOUNT: u64 = 1_000_000;
    const WINDOW: u64 = 1_000;

    fn vesting_funded() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_vesting(VestingSchedule::new(T0, T0 + WINDOW).unwrap())
            .unwrap();
        e.fund(ALICE, T0).unwrap();
        e
    }

    fn plain_funded() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT).unwrap();
        e.fund(ALICE, T0).unwrap();
        e
    }

    #[test]
    fn pause_vesting_happy_path_stamps_paused_at() {
        let mut e = vesting_funded();
        assert_eq!(e.vesting_pause(), None);
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        assert_eq!(
            e.vesting_pause(),
            Some(VestingPause { paused_at: T0 + 100 })
        );
        // The pause is a schedule freeze, not a lifecycle move.
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn pause_vesting_rejects_non_initializer() {
        let mut e = vesting_funded();
        // The taker cannot freeze their own unlock clock, and a
        // stranger learns nothing beyond the refusal.
        assert_eq!(
            e.pause_vesting(BOB, T0 + 100),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            e.pause_vesting(MALLORY, T0 + 100),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(e.vesting_pause(), None);
    }

    #[test]
    fn pause_vesting_rejects_unfunded_escrow() {
        let mut e = Escrow::initialize(ALICE, BOB, AMOUNT, EXPIRES_AT)
            .unwrap()
            .with_vesting(VestingSchedule::new(T0, T0 + WINDOW).unwrap())
            .unwrap();
        assert_eq!(
            e.pause_vesting(ALICE, T0 + 100),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn pause_vesting_rejects_schedule_less_escrow() {
        // No vesting schedule attached — there is no unlock clock to
        // freeze.
        let mut e = plain_funded();
        assert_eq!(
            e.pause_vesting(ALICE, T0 + 100),
            Err(EscrowError::InvalidVesting)
        );
        assert_eq!(e.vesting_pause(), None);
    }

    #[test]
    fn pause_vesting_rejects_double_pause() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        // The pause is a strict toggle: a second pause is refused
        // rather than silently re-stamping paused_at (which would
        // steal the taker's unlock time).
        assert_eq!(
            e.pause_vesting(ALICE, T0 + 200),
            Err(EscrowError::VestingAlreadyPaused)
        );
        assert_eq!(
            e.vesting_pause(),
            Some(VestingPause { paused_at: T0 + 100 }),
            "paused_at keeps the first stamp"
        );
    }

    #[test]
    fn claim_frozen_while_paused() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        // Half the schedule is vested at T0 + 500, but the unlock
        // clock is frozen — the taker's pull is refused.
        assert_eq!(
            e.claim(BOB, T0 + 500, None, BOB),
            Err(EscrowError::VestingPaused)
        );
        assert_eq!(e.released_amount(), 0, "refused claim moves nothing");
    }

    #[test]
    fn resume_vesting_shifts_schedule_by_paused_duration() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        e.resume_vesting(ALICE, T0 + 400).unwrap();
        // The 300-second pause slides the whole window: start, end
        // and cliff_at all move by the paused duration, so the
        // unlock duration is unchanged.
        let schedule = e.vesting_schedule().unwrap();
        assert_eq!(schedule.start(), T0 + 300);
        assert_eq!(schedule.end(), T0 + WINDOW + 300);
        assert_eq!(schedule.cliff_at(), T0 + 300);
        assert_eq!(e.vesting_pause(), None, "marker cleared");
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn resume_vesting_rejects_when_not_paused() {
        let mut e = vesting_funded();
        assert_eq!(
            e.resume_vesting(ALICE, T0 + 400),
            Err(EscrowError::VestingNotPaused)
        );
        // And again after a full pause/resume cycle.
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        e.resume_vesting(ALICE, T0 + 400).unwrap();
        assert_eq!(
            e.resume_vesting(ALICE, T0 + 500),
            Err(EscrowError::VestingNotPaused)
        );
    }

    #[test]
    fn resume_vesting_rejects_non_initializer() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        assert_eq!(
            e.resume_vesting(BOB, T0 + 400),
            Err(EscrowError::Unauthorized)
        );
        assert_eq!(
            e.resume_vesting(MALLORY, T0 + 400),
            Err(EscrowError::Unauthorized)
        );
        // The pause survives the refused resumes.
        assert_eq!(
            e.vesting_pause(),
            Some(VestingPause { paused_at: T0 + 100 })
        );
    }

    #[test]
    fn resume_vesting_rejects_backwards_clock() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 400).unwrap();
        // A clock that runs backwards would slide the schedule into
        // the past — refused, and the pause stays live.
        assert_eq!(
            e.resume_vesting(ALICE, T0 + 399),
            Err(EscrowError::InvalidVesting)
        );
        assert_eq!(
            e.vesting_pause(),
            Some(VestingPause { paused_at: T0 + 400 })
        );
    }

    #[test]
    fn zero_duration_pause_shifts_nothing() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        e.resume_vesting(ALICE, T0 + 100).unwrap();
        let schedule = e.vesting_schedule().unwrap();
        assert_eq!(schedule.start(), T0);
        assert_eq!(schedule.end(), T0 + WINDOW);
        assert_eq!(e.vesting_pause(), None);
    }

    #[test]
    fn pause_resume_round_trip_restores_claim() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        assert_eq!(
            e.claim(BOB, T0 + 500, None, BOB),
            Err(EscrowError::VestingPaused)
        );
        // Paused 300 seconds: the window slides to [T0+300, T0+1300].
        // At T0 + 500 only 200/1000 of the schedule has elapsed.
        e.resume_vesting(ALICE, T0 + 400).unwrap();
        let (payout, fee) = e.claim(BOB, T0 + 500, None, BOB).unwrap();
        assert_eq!((payout, fee), (AMOUNT / 5, 0));
        assert_eq!(e.released_amount(), AMOUNT / 5);
        // At the shifted end the full amount is vested again.
        let (payout, _) = e.claim(BOB, T0 + WINDOW + 300, None, BOB).unwrap();
        assert_eq!(payout, AMOUNT - AMOUNT / 5);
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn released_counter_conservation_across_pause() {
        let mut e = vesting_funded();
        // Claim a quarter before the pause.
        let (first, _) = e.claim(BOB, T0 + 250, None, BOB).unwrap();
        assert_eq!(first, AMOUNT / 4);
        e.pause_vesting(ALICE, T0 + 300).unwrap();
        e.resume_vesting(ALICE, T0 + 500).unwrap();
        // The 200-second pause slides the window to [T0+200,
        // T0+1200]: at T0 + 700, 500/1000 vested, a quarter already
        // released.
        let (second, _) = e.claim(BOB, T0 + 700, None, BOB).unwrap();
        assert_eq!(second, AMOUNT / 4);
        assert_eq!(e.released_amount(), AMOUNT / 2);
    }

    #[test]
    fn release_stays_open_while_paused() {
        // The freeze is scoped to the taker's schedule-priced pull:
        // the initializer's push path is unaffected.
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        let (payout, fee) = e.release(ALICE, T0 + 200, 100_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (100_000, 0));
        assert_eq!(e.released_amount(), 100_000);
        assert_eq!(e.vesting_pause().unwrap().paused_at, T0 + 100);
    }

    #[test]
    fn pause_marker_survives_serialization_round_trip() {
        let mut e = vesting_funded();
        e.pause_vesting(ALICE, T0 + 100).unwrap();
        let body = super::account_space_tests::encode_escrow(&e);
        assert_eq!(body.len(), crate::ESCROW_BODY_LEN);
        // The pause tail is the absolute tail: 1-byte Some
        // discriminant + the 8-byte paused_at.
        let tail_at = body.len() - crate::VESTING_PAUSE_TAIL_LEN - crate::MINT_ALLOWLIST_TAIL_LEN - crate::GOVERNANCE_DELAY_TAIL_LEN - crate::GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(body[tail_at], 1, "Some discriminant");
        assert_eq!(
            u64::from_le_bytes(body[tail_at + 1..tail_at + 9].try_into().unwrap()),
            T0 + 100,
            "paused_at persists"
        );
        // Full decode round-trips the marker.
        let mut account = vec![0u8; 8 + body.len()];
        account[..8].copy_from_slice(&crate::discriminator::vault_account_discriminator());
        account[8..].copy_from_slice(&body);
        let decoded = crate::decode_vault_account(&account).unwrap();
        assert_eq!(decoded, e);
        assert_eq!(
            decoded.vesting_pause(),
            Some(VestingPause { paused_at: T0 + 100 })
        );
    }

    #[test]
    fn vesting_paused_event_kind_is_pinned() {
        let kind = EscrowEventKind::VestingPaused;
        assert_eq!(kind.discriminant(), 78);
        assert_eq!(EscrowEventKind::from_discriminant(78), Some(kind));
        assert_eq!(kind.name(), "vesting_paused");
        assert_eq!(EscrowEventKind::from_name("vesting_paused"), Some(kind));
    }

    #[test]
    fn vesting_resumed_event_kind_is_pinned() {
        let kind = EscrowEventKind::VestingResumed;
        assert_eq!(kind.discriminant(), 79);
        assert_eq!(EscrowEventKind::from_discriminant(79), Some(kind));
        assert_eq!(kind.name(), "vesting_resumed");
        assert_eq!(EscrowEventKind::from_name("vesting_resumed"), Some(kind));
    }

    #[test]
    fn vesting_pause_tail_len_is_pinned() {
        // 1-byte `Option` discriminant + 8-byte paused_at timestamp.
        assert_eq!(VESTING_PAUSE_TAIL_LEN, 9);
    }

    // ----- AV-157: SPL mint governance allowlist -----

    #[test]
    fn mint_allowlist_empty_disables() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint_allowlist(&[])
            .unwrap();
        assert_eq!(e.mint_allowlist(), None, "empty list = allowlist off");
    }

    #[test]
    fn mint_allowlist_builder_validates() {
        // Zero address rejected.
        let zero = [0u8; 32];
        let err = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint_allowlist(&[zero])
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidMint);
        // More than 8 rejected.
        let many = [[1u8; 32]; 9];
        let err = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint_allowlist(&many)
            .unwrap_err();
        assert_eq!(err, EscrowError::InvalidMint);
    }

    #[test]
    fn mint_allowlist_enforces_on_with_mint() {
        let m1 = [1u8; 32];
        let m2 = [2u8; 32];
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint_allowlist(&[m1])
            .unwrap();
        // Allowlisted mint OK.
        let e = e.with_mint(m1).unwrap();
        assert_eq!(e.mint(), Some(m1));
        // Unlisted mint rejected with 217.
        let err = e.with_mint(m2).unwrap_err();
        assert_eq!(err, EscrowError::MintNotAllowlisted);
        assert_eq!(err.code(), 217);
    }

    #[test]
    fn mint_allowlist_rejects_bound_mint_not_in_new_list() {
        let m1 = [1u8; 32];
        let m2 = [2u8; 32];
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint(m1)
            .unwrap();
        // Setting an allowlist that excludes the bound mint fails.
        let err = e.with_mint_allowlist(&[m2]).unwrap_err();
        assert_eq!(err, EscrowError::MintNotAllowlisted);
    }

    #[test]
    fn mint_allowlist_uninitialized_only() {
        let m1 = [1u8; 32];
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, 1_700_000_000).unwrap();
        let err = e.with_mint_allowlist(&[m1]).unwrap_err();
        // Funded escrow is no longer Uninitialized.
        assert_eq!(err, EscrowError::InvalidStateTransition);
    }

    #[test]
    fn mint_allowlist_round_trips_through_encoding() {
        use crate::account_space_tests::encode_escrow;
        let m1 = [1u8; 32];
        let m2 = [2u8; 32];
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_mint_allowlist(&[m1, m2])
            .unwrap();
        let bytes = encode_escrow(&e);
        assert_eq!(bytes.len(), crate::ESCROW_BODY_LEN);
        // The allowlist tail is the absolute tail.
        let tail_at = bytes.len() - crate::MINT_ALLOWLIST_TAIL_LEN - crate::GOVERNANCE_DELAY_TAIL_LEN - crate::GOVERNANCE_PROPOSAL_TAIL_LEN - FEES_WITHDRAWN_TAIL_LEN - (1 + TIERED_QUORUM_LEN) - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-191 referral tail: 33 + 2 + 8; AV-195 recovery tail + AV-196 jury size
        assert_eq!(bytes[tail_at], 1, "Some discriminant");
        // 256-byte mint array then the 1-byte entry count.
        assert_eq!(&bytes[tail_at + 1..tail_at + 33], &m1, "mint 0");
        assert_eq!(&bytes[tail_at + 33..tail_at + 65], &m2, "mint 1");
        assert_eq!(bytes[tail_at + 257], 2, "len = 2");
        // Full decode round-trips.
        let mut account = vec![0u8; 8 + bytes.len()];
        account[..8].copy_from_slice(&crate::discriminator::vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = crate::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.mint_allowlist().unwrap().as_slice(), &[m1, m2]);
    }
}

// ---------- AV-191: referrer revenue share ----------
#[cfg(test)]
mod referral_tests {
    use super::*;

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const REFERRER: [u8; 32] = [0xCC; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_700_000_000;

    fn funded_referral_escrow(bps: u16) -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, bps)
            .unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        e
    }

    #[test]
    fn builder_matrix() {
        // Happy path.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, 1_000)
            .unwrap();
        assert_eq!(e.referrer(), Some(REFERRER));
        assert_eq!(e.referral_bps(), 1_000);
        assert_eq!(e.referral_paid(), 0);
        // Defaults: no referrer bound.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        assert_eq!(e.referrer(), None);
        assert_eq!(e.referral_bps(), 0);
        assert_eq!(e.referral_paid(), 0);
        // The zero address can never be a referral destination.
        assert_eq!(
            Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
                .unwrap()
                .with_referrer([0u8; 32], 1_000),
            Err(EscrowError::InvalidReferral)
        );
        // Above the 20% cap.
        assert_eq!(
            Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
                .unwrap()
                .with_referrer(REFERRER, MAX_REFERRAL_BPS + 1),
            Err(EscrowError::InvalidReferral)
        );
        // The cap boundary itself is valid.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, MAX_REFERRAL_BPS)
            .unwrap();
        assert_eq!(e.referral_bps(), MAX_REFERRAL_BPS);
        // Builder-style overwrite allowed while Uninitialized.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, 1_000)
            .unwrap()
            .with_referrer(BOB, 500)
            .unwrap();
        assert_eq!(e.referrer(), Some(BOB));
        assert_eq!(e.referral_bps(), 500);
        // Funded escrow is no longer Uninitialized.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e.with_referrer(REFERRER, 1_000),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn referral_for_math() {
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, 1_000)
            .unwrap();
        // floor(1_000_000 * 1000 / 10_000) = 100_000.
        assert_eq!(e.referral_for(1_000_000), 100_000);
        // Floor rounding: 999 * 1000 / 10000 = 99.9 -> 99.
        assert_eq!(e.referral_for(999), 99);
        // Dust: 9 * 1000 / 10000 = 0.9 -> 0.
        assert_eq!(e.referral_for(9), 0);
        // No referrer bound: always zero.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        assert_eq!(e.referral_for(1_000_000), 0);
        // Zero rate with a bound referrer: zero.
        let e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_referrer(REFERRER, 0)
            .unwrap();
        assert_eq!(e.referral_for(1_000_000), 0);
    }

    #[test]
    fn release_slices_referral() {
        let mut e = funded_referral_escrow(1_000);
        // 10% of 1_000_000 = 100_000 to the referrer.
        let (payout, fee) = e.release(ALICE, NOW, 1_000_000, None, BOB).unwrap();
        assert_eq!(payout, 900_000);
        assert_eq!(fee, 100_000, "referral folds into the fee leg");
        assert_eq!(e.referral_paid(), 100_000);
        assert_eq!(e.fees_paid(), 0, "referral never touches fees_paid");
        assert_eq!(e.released_amount(), 1_000_000, "released keeps the gross");
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn release_without_referrer_is_unchanged() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        let (payout, fee) = e.release(ALICE, NOW, 1_000_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (1_000_000, 0));
        assert_eq!(e.referral_paid(), 0);
    }

    #[test]
    fn referral_stacks_with_protocol_fee() {
        // 5% protocol fee + 10% referral on 1_000_000: both computed on
        // the gross, orthogonal ledgers.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_protocol_fee(500)
            .unwrap()
            .with_referrer(REFERRER, 1_000)
            .unwrap();
        e.fund(ALICE, NOW).unwrap();
        let (payout, fee) = e.release(ALICE, NOW, 1_000_000, None, BOB).unwrap();
        assert_eq!(payout, 850_000);
        assert_eq!(fee, 150_000, "protocol fee + referral in one fee leg");
        assert_eq!(e.fees_paid(), 50_000);
        assert_eq!(e.referral_paid(), 100_000);
    }

    #[test]
    fn partial_releases_accumulate_referral() {
        let mut e = funded_referral_escrow(1_000);
        let (payout, fee) = e.release(ALICE, NOW, 400_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (360_000, 40_000));
        assert_eq!(e.referral_paid(), 40_000);
        assert_eq!(e.state(), EscrowState::Funded);
        let (payout, fee) = e.release(ALICE, NOW, 600_000, None, BOB).unwrap();
        assert_eq!((payout, fee), (540_000, 60_000));
        assert_eq!(e.referral_paid(), 100_000);
        assert_eq!(e.released_amount(), 1_000_000);
        assert!(e.referral_paid() <= e.released_amount());
        assert_eq!(e.state(), EscrowState::Released);
    }

    #[test]
    fn failed_release_charges_no_referral() {
        // A gate failure (zero amount) must not touch the counter —
        // charging happens after every gate passes.
        let mut e = funded_referral_escrow(1_000);
        assert_eq!(
            e.release(ALICE, NOW, 0, None, BOB),
            Err(EscrowError::AmountMismatch)
        );
        assert_eq!(e.referral_paid(), 0);
        assert_eq!(e.released_amount(), 0);
    }

    #[test]
    fn cpi_rollback_restores_referral_paid() {
        // A CPI invocation that fails validation after the inner
        // release settles must restore referral_paid (like fees_paid).
        let mut e = funded_referral_escrow(1_000);
        let bad = CpiInvocation {
            program_id: [0u8; 32], // zero program id: InvalidCpiTarget
            accounts: vec![],
            data: vec![],
        };
        assert_eq!(
            e.release_via_cpi(ALICE, NOW, 1_000_000, None, BOB, 0, &bad, |_| Ok(1_000_000)),
            Err(EscrowError::InvalidCpiTarget)
        );
        assert_eq!(e.referral_paid(), 0, "rolled back");
        assert_eq!(e.released_amount(), 0, "rolled back");
        assert_eq!(e.state(), EscrowState::Funded);
    }

    #[test]
    fn referral_tail_encodes_and_decodes() {
        use crate::account_space_tests::encode_escrow;
        let mut e = funded_referral_escrow(2_000);
        e.release(ALICE, NOW, 500_000, None, BOB).unwrap();
        let bytes = encode_escrow(&e);
        assert_eq!(bytes.len(), crate::ESCROW_BODY_LEN);
        // The referral tail is the absolute tail: 33 + 2 + 8.
        let tail_at = bytes.len() - 43 - SOCIAL_RECOVERY_TAIL_LEN - JURY_PANEL_SIZE_TAIL_LEN; // AV-195 recovery + AV-196 jury size appended after the referral tail
        assert_eq!(bytes[tail_at], 1, "referrer: Some discriminant");
        assert_eq!(&bytes[tail_at + 1..tail_at + 33], &REFERRER, "referrer key");
        assert_eq!(
            u16::from_le_bytes(bytes[tail_at + 33..tail_at + 35].try_into().unwrap()),
            2_000,
            "referral_bps"
        );
        assert_eq!(
            u64::from_le_bytes(bytes[tail_at + 35..tail_at + 43].try_into().unwrap()),
            100_000,
            "referral_paid: 20% of 500_000"
        );
        // Full account decode round-trips the referral state.
        let mut account = vec![0u8; 8 + bytes.len()];
        account[..8].copy_from_slice(&crate::discriminator::vault_account_discriminator());
        account[8..].copy_from_slice(&bytes);
        let decoded = crate::decode_vault_account(&account).unwrap();
        assert_eq!(decoded.referrer(), Some(REFERRER));
        assert_eq!(decoded.referral_bps(), 2_000);
        assert_eq!(decoded.referral_paid(), 100_000);
    }

    #[test]
    fn preview_release_folds_referral_into_fee() {
        let e = funded_referral_escrow(1_000);
        let preview = e.preview_release(ALICE, NOW, 1_000_000, None, BOB).unwrap();
        assert_eq!(preview.payout, 900_000);
        assert_eq!(preview.fee, 100_000, "preview fee includes the referral");
        assert_eq!(
            preview.payout + preview.fee + preview.refund,
            1_000_000,
            "conservation identity holds"
        );
        // The preview charges nothing.
        assert_eq!(e.referral_paid(), 0);
    }
}

// ---------- AV-195: social recovery (M-of-N guardian key rotation) ----------
#[cfg(test)]
mod recovery_tests {
    use super::*;
    use crate::discriminator::{decode_vault_account, vault_account_discriminator};

    const ALICE: [u8; 32] = [0xAA; 32];
    const BOB: [u8; 32] = [0xBB; 32];
    const G1: [u8; 32] = [0x11; 32];
    const G2: [u8; 32] = [0x22; 32];
    const G3: [u8; 32] = [0x33; 32];
    const NEW_KEY: [u8; 32] = [0x99; 32];
    const MALLORY: [u8; 32] = [0xCC; 32];
    const EXPIRES_AT: u64 = 1_800_000_000;
    const NOW: u64 = 1_700_000_000;

    fn recovery_escrow() -> Escrow {
        Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_social_recovery(&[G1, G2, G3], 2, 3_600)
            .unwrap()
    }

    fn funded_recovery_escrow() -> Escrow {
        let mut e = recovery_escrow();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(e.state(), EscrowState::Funded);
        e
    }

    #[test]
    fn full_lifecycle_rotates_the_initializer() {
        let mut e = funded_recovery_escrow();
        // Request (G1 opens, approval #1 recorded).
        e.request_recovery(G1, NEW_KEY, NOW).unwrap();
        assert_eq!(e.recovery().unwrap().approval_count(), 1);
        // Threshold not yet reached: crank refuses.
        assert_eq!(
            e.execute_recovery(NOW + 3_600),
            Err(EscrowError::RecoveryThresholdNotReached)
        );
        // Second approval reaches 2-of-3.
        e.approve_recovery(G2).unwrap();
        assert_eq!(e.recovery().unwrap().approval_count(), 2);
        // Timelock not elapsed (boundary-exclusive).
        assert_eq!(
            e.execute_recovery(NOW + 3_599),
            Err(EscrowError::RecoveryTimelockNotElapsed)
        );
        // Timelock inclusive at the boundary: executes.
        e.execute_recovery(NOW + 3_600).unwrap();
        // The initializer rotated; the request is consumed.
        assert_eq!(e.initializer(), NEW_KEY);
        assert!(e.recovery().unwrap().pending().is_none());
    }

    #[test]
    fn execute_clears_activation_bit_like_rotate_initializer() {
        // Dual-sig escrow: the initializer's activation signature is
        // recorded before funding.
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_dual_sig()
            .unwrap()
            .with_social_recovery(&[G1, G2], 2, 0)
            .unwrap();
        e.activate(ALICE).unwrap();
        e.activate(BOB).unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert!(e.initializer_activated());
        // Recovery rotates to a fresh key: the new key never signed.
        e.request_recovery(G1, NEW_KEY, NOW).unwrap();
        e.approve_recovery(G2).unwrap();
        e.execute_recovery(NOW).unwrap();
        assert_eq!(e.initializer(), NEW_KEY);
        assert!(!e.initializer_activated());
    }

    #[test]
    fn veto_by_initializer_cancels_and_stranger_veto_fails() {
        let mut e = funded_recovery_escrow();
        e.request_recovery(G1, NEW_KEY, NOW).unwrap();
        e.approve_recovery(G2).unwrap();
        // A stranger cannot veto.
        assert_eq!(
            e.veto_recovery(MALLORY),
            Err(EscrowError::Unauthorized)
        );
        assert!(e.recovery().unwrap().pending().is_some());
        // The current initializer vetoes: request gone, key unchanged.
        e.veto_recovery(ALICE).unwrap();
        assert!(e.recovery().unwrap().pending().is_none());
        assert_eq!(e.initializer(), ALICE);
        // Executing after the veto: nothing pending.
        assert_eq!(
            e.execute_recovery(NOW + 3_600),
            Err(EscrowError::RecoveryNoPendingRequest)
        );
    }

    #[test]
    fn transitions_fail_without_a_configured_policy() {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, NOW).unwrap();
        assert_eq!(
            e.request_recovery(G1, NEW_KEY, NOW),
            Err(EscrowError::RecoveryNotConfigured)
        );
        assert_eq!(
            e.approve_recovery(G1),
            Err(EscrowError::RecoveryNotConfigured)
        );
        assert_eq!(
            e.execute_recovery(NOW),
            Err(EscrowError::RecoveryNotConfigured)
        );
        assert_eq!(
            e.veto_recovery(ALICE),
            Err(EscrowError::RecoveryNotConfigured)
        );
    }

    #[test]
    fn builder_and_request_check_order() {
        // Builder is Uninitialized-only.
        let mut funded = funded_recovery_escrow();
        assert_eq!(
            funded.with_social_recovery(&[G1], 1, 0),
            Err(EscrowError::InvalidStateTransition)
        );
        // Stranger cannot open a request.
        let mut e = funded_recovery_escrow();
        assert_eq!(
            e.request_recovery(MALLORY, NEW_KEY, NOW),
            Err(EscrowError::RecoveryNotGuardian)
        );
        // Disputed escrow: recovery refused (arbitration in flight).
        let mut d = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_social_recovery(&[G1, G2], 2, 0)
            .unwrap()
            .with_arbiter([0xA9; 32])
            .unwrap();
        d.fund(ALICE, NOW).unwrap();
        d.escalate(ALICE, NOW + 1, 1_000_000, None, None, 0).unwrap();
        assert_eq!(d.state(), EscrowState::Disputed);
        assert_eq!(
            d.request_recovery(G1, NEW_KEY, NOW + 2),
            Err(EscrowError::InvalidStateTransition)
        );
    }

    #[test]
    fn recovery_policy_and_pending_request_survive_encode_decode() {
        use crate::account_space_tests::encode_escrow;
        let mut e = funded_recovery_escrow();
        e.request_recovery(G1, NEW_KEY, NOW).unwrap();
        e.approve_recovery(G2).unwrap();
        let bytes = encode_escrow(&e);
        assert_eq!(bytes.len(), super::ESCROW_BODY_LEN);
        let mut full = vault_account_discriminator().to_vec();
        full.extend_from_slice(&bytes);
        let d = decode_vault_account(&full).unwrap();
        let policy = d.recovery().unwrap();
        assert_eq!(policy.guardian_count(), 3);
        assert_eq!(policy.threshold(), 2);
        assert_eq!(policy.timelock_secs(), 3_600);
        assert_eq!(policy.guardians(), &[G1, G2, G3]);
        let req = policy.pending().unwrap();
        assert_eq!(req.new_authority, NEW_KEY);
        assert_eq!(req.approvals.count_ones(), 2);
        assert_eq!(req.requested_at, NOW);
        // The decoded escrow executes identically.
        let mut d = d;
        assert_eq!(
            d.execute_recovery(NOW + 3_599),
            Err(EscrowError::RecoveryTimelockNotElapsed)
        );
        d.execute_recovery(NOW + 3_600).unwrap();
        assert_eq!(d.initializer(), NEW_KEY);
    }

    #[test]
    fn recovery_error_codes_are_pinned() {
        assert_eq!(EscrowError::InvalidSocialRecovery.code(), 286);
        assert_eq!(EscrowError::RecoveryNotConfigured.code(), 287);
        assert_eq!(EscrowError::RecoveryNotGuardian.code(), 288);
        assert_eq!(EscrowError::RecoveryRequestPending.code(), 289);
        assert_eq!(EscrowError::RecoveryNoPendingRequest.code(), 290);
        assert_eq!(EscrowError::RecoveryThresholdNotReached.code(), 291);
        assert_eq!(EscrowError::RecoveryTimelockNotElapsed.code(), 292);
    }
}
